INSERT INTO is_learn_lessons (id, unit_id, title, kind, sort_order) VALUES ('355c1d6a-dbc7-50b5-8ff4-be182cf9a5e3', '5e15e158-9704-5aca-a1b2-1062a8cb0dbe', '{"en": "The six pillars", "bn": "ছয়টি স্তম্ভ"}', 'lesson', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('d7b7bcfe-ac5f-5aa1-bad7-da67a6bdbfcd', '355c1d6a-dbc7-50b5-8ff4-be182cf9a5e3', 'choice', '{"en": "How many pillars of iman are in the hadith of Jibril?", "bn": "হাদিসে জিবরিলে ঈমানের স্তম্ভ কয়টি?"}', '{"options": [{"en": "4", "bn": "৪"}, {"en": "5", "bn": "৫"}, {"en": "6", "bn": "৬"}, {"en": "7", "bn": "৭"}], "correct": 2}', '{"en": "Belief in Allah, His angels, books, messengers, the Last Day and the decree.", "bn": "আল্লাহ, ফেরেশতা, কিতাব, রাসুল, শেষ দিবস ও তাকদিরে বিশ্বাস।"}', 'Sahih Muslim 8', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('9beef04f-0fe2-52c9-9788-a0fffc8b0148', '355c1d6a-dbc7-50b5-8ff4-be182cf9a5e3', 'order', '{"en": "Put the pillars of iman in the order of the hadith of Jibril", "bn": "হাদিসে জিবরিলের ক্রমে ঈমানের স্তম্ভগুলো সাজান"}', '{"pieces": [{"en": "Allah", "bn": "আল্লাহ"}, {"en": "His angels", "bn": "তাঁর ফেরেশতাগণ"}, {"en": "His books", "bn": "তাঁর কিতাবসমূহ"}, {"en": "His messengers", "bn": "তাঁর রাসুলগণ"}, {"en": "The Last Day", "bn": "শেষ দিবস"}, {"en": "The decree (qadar)", "bn": "তাকদির"}], "rtl": false}', '{"en": "\"That you believe in Allah, His angels, His books, His messengers and the Last Day, and believe in the decree, its good and its bad.\"", "bn": "\"আল্লাহ, তাঁর ফেরেশতা, কিতাব, রাসুল ও শেষ দিবসে বিশ্বাস করবে এবং তাকদিরের ভালো-মন্দে বিশ্বাস করবে।\""}', 'Sahih Muslim 8', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('9518d843-e295-5821-9479-0bb24506f8d4', '355c1d6a-dbc7-50b5-8ff4-be182cf9a5e3', 'true_false', '{"en": "Performing Hajj is one of the pillars of iman.", "bn": "হজ পালন ঈমানের একটি স্তম্ভ।"}', '{"answer": false}', '{"en": "Hajj is a pillar of Islam (an action), not of iman (belief).", "bn": "হজ ইসলামের স্তম্ভ (আমল), ঈমানের (বিশ্বাস) নয়।"}', 'Sahih Muslim 8', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('0bc54e6d-76fa-5e87-be7e-21194fb41c5c', '355c1d6a-dbc7-50b5-8ff4-be182cf9a5e3', 'choice', '{"en": "Belief in Allah’s decree is called…?", "bn": "আল্লাহর নির্ধারণে বিশ্বাসকে কী বলে?"}', '{"options": [{"en": "Qadar", "bn": "তাকদির (কদর)"}, {"en": "Sunnah", "bn": "সুন্নাহ"}, {"en": "Ihsan", "bn": "ইহসান"}, {"en": "Tawbah", "bn": "তওবা"}], "correct": 0}', '{"en": "Believing in qadar, its good and its bad.", "bn": "তাকদিরের ভালো-মন্দে বিশ্বাস করা।"}', 'Sahih Muslim 8', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('210cb795-ba54-545f-9b02-e2e2d571873e', '355c1d6a-dbc7-50b5-8ff4-be182cf9a5e3', 'match', '{"en": "Match each book to its prophet", "bn": "কিতাবের সঙ্গে নবী মেলান"}', '{"pairs": [{"left": {"en": "Tawrah", "bn": "তাওরাত"}, "right": {"en": "Musa", "bn": "মুসা (আ.)"}}, {"left": {"en": "Injil", "bn": "ইঞ্জিল"}, "right": {"en": "Isa", "bn": "ঈসা (আ.)"}}, {"left": {"en": "Zabur", "bn": "যাবুর"}, "right": {"en": "Dawud", "bn": "দাউদ (আ.)"}}, {"left": {"en": "Quran", "bn": "কুরআন"}, "right": {"en": "Muhammad ﷺ", "bn": "মুহাম্মাদ ﷺ"}}]}', '{"en": "Each book and the prophet it was given to.", "bn": "প্রতিটি কিতাব ও যে নবীকে তা দেওয়া হয়েছিল।"}', 'Quran 5:44, 5:46, 4:163', 5) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('63c14cff-c463-5eba-9dc8-3f95ae6a7f1d', '355c1d6a-dbc7-50b5-8ff4-be182cf9a5e3', 'choice', '{"en": "What is ihsan?", "bn": "ইহসান কী?"}', '{"options": [{"en": "Giving charity only", "bn": "শুধু দান করা"}, {"en": "Worshipping Allah as if you see Him", "bn": "এমনভাবে ইবাদত করা যেন আল্লাহকে দেখছেন"}, {"en": "Fasting every day", "bn": "প্রতিদিন রোজা রাখা"}, {"en": "Reading Quran aloud", "bn": "জোরে কুরআন পড়া"}], "correct": 1}', '{"en": "\"…as if you see Him, and if you do not see Him, He surely sees you.\"", "bn": "\"…যেন আপনি তাঁকে দেখছেন; আর যদি না দেখেন, তবে তিনি তো আপনাকে দেখছেন।\""}', 'Sahih Muslim 8', 6) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('bbfcc8f7-3e14-5b52-bb62-ec7084b32901', '355c1d6a-dbc7-50b5-8ff4-be182cf9a5e3', 'true_false', '{"en": "The Prophet ﷺ said that iman has more than sixty branches.", "bn": "নবী ﷺ বলেছেন, ঈমানের ষাটের বেশি শাখা আছে।"}', '{"answer": true}', '{"en": "\"Iman has sixty-odd or seventy-odd branches; modesty is a branch of iman.\"", "bn": "\"ঈমানের ষাট বা সত্তরের অধিক শাখা আছে; লজ্জা ঈমানের একটি শাখা।\""}', 'Sahih Muslim 35', 7) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_lessons (id, unit_id, title, kind, sort_order) VALUES ('7ae7bde2-35b5-568a-a5cb-dabb33423496', '5e15e158-9704-5aca-a1b2-1062a8cb0dbe', '{"en": "Allah and His names", "bn": "আল্লাহ ও তাঁর নামসমূহ"}', 'lesson', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('b7448977-a9f1-530c-95f7-1e10a037fd6c', '7ae7bde2-35b5-568a-a5cb-dabb33423496', 'choice', '{"en": "What does \"Ar-Rahman\" mean?", "bn": "\"আর-রহমান\" অর্থ কী?"}', '{"options": [{"en": "The Most Merciful", "bn": "পরম দয়াময়"}, {"en": "The King", "bn": "অধিপতি"}, {"en": "The Creator", "bn": "সৃষ্টিকর্তা"}, {"en": "The Judge", "bn": "বিচারক"}], "correct": 0}', '{"en": "Ar-Rahman: the One whose mercy covers everything.", "bn": "আর-রহমান: যাঁর দয়া সবকিছুকে ঘিরে আছে।"}', 'Quran 1:3', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('9ee0ecea-3af3-599a-9fd2-9ff7fbe90094', '7ae7bde2-35b5-568a-a5cb-dabb33423496', 'match', '{"en": "Match each name to its meaning", "bn": "প্রতিটি নামের অর্থ মেলান"}', '{"pairs": [{"left": {"ar": "الرزاق"}, "right": {"en": "The Provider", "bn": "রিজিকদাতা"}}, {"left": {"ar": "الغفور"}, "right": {"en": "The Forgiving", "bn": "ক্ষমাশীল"}}, {"left": {"ar": "العليم"}, "right": {"en": "The All-Knowing", "bn": "সর্বজ্ঞ"}}, {"left": {"ar": "الحكيم"}, "right": {"en": "The Wise", "bn": "প্রজ্ঞাময়"}}]}', '{"en": "Ar-Razzaq, Al-Ghafur, Al-‘Alim and Al-Hakim.", "bn": "আর-রাযযাক, আল-গাফুর, আল-আলিম ও আল-হাকিম।"}', 'Quran 51:58, 39:53, 2:32', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('6483d3ae-d79b-514e-a6dd-e1b7ca16511f', '7ae7bde2-35b5-568a-a5cb-dabb33423496', 'choice', '{"en": "Which name means \"The Creator\"?", "bn": "কোন নামের অর্থ \"সৃষ্টিকর্তা\"?"}', '{"options": [{"en": "Al-Khaliq", "bn": "আল-খালিক"}, {"en": "Al-Qawi", "bn": "আল-কাওয়ি"}, {"en": "As-Sami‘", "bn": "আস-সামি"}, {"en": "Al-Karim", "bn": "আল-কারিম"}], "correct": 0}', '{"en": "\"He is Allah, the Creator, the Inventor, the Fashioner.\"", "bn": "\"তিনিই আল্লাহ, সৃষ্টিকর্তা, উদ্ভাবক, রূপদাতা।\""}', 'Quran 59:24', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('d50c5517-e02f-543a-a411-319b600fe32d', '7ae7bde2-35b5-568a-a5cb-dabb33423496', 'true_false', '{"en": "The Prophet ﷺ said Allah has ninety-nine names.", "bn": "নবী ﷺ বলেছেন, আল্লাহর নিরানব্বইটি নাম আছে।"}', '{"answer": true}', '{"en": "\"Allah has ninety-nine names; whoever learns them will enter Paradise.\"", "bn": "\"আল্লাহর নিরানব্বইটি নাম আছে; যে এগুলো আয়ত্ত করবে সে জান্নাতে প্রবেশ করবে।\""}', 'Sahih al-Bukhari 2736', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('6a2f1b87-87f0-5a24-9c64-33374e3239c7', '7ae7bde2-35b5-568a-a5cb-dabb33423496', 'fill', '{"en": "Complete the ayah", "bn": "আয়াতটি পূর্ণ করুন"}', '{"before": {"ar": "قُلْ هُوَ ٱللَّهُ"}, "options": [{"ar": "أَحَدٌ"}, {"ar": "ٱلصَّمَدُ"}, {"ar": "لَّهُۥ"}], "correct": 0, "rtl": true}', '{"en": "\"Say: He is Allah, the One.\"", "bn": "\"বলুন: তিনিই আল্লাহ, এক।\""}', 'Quran 112:1', 5) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('237154b1-d755-5cf4-99f1-2c26a5a86517', '7ae7bde2-35b5-568a-a5cb-dabb33423496', 'choice', '{"en": "The name \"As-Samad\" appears in which surah?", "bn": "\"আস-সামাদ\" নামটি কোন সূরায় আছে?"}', '{"options": [{"en": "Al-Ikhlas", "bn": "আল-ইখলাস"}, {"en": "Al-Fatiha", "bn": "আল-ফাতিহা"}, {"en": "Al-Mulk", "bn": "আল-মুলক"}, {"en": "Ya-Sin", "bn": "ইয়াসিন"}], "correct": 0}', '{"en": "\"Allah, the Eternal Refuge (As-Samad).\"", "bn": "\"আল্লাহ অমুখাপেক্ষী (আস-সামাদ)।\""}', 'Quran 112:2', 6) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('351f374e-e6b0-50d5-9123-01b0e25b28e3', '7ae7bde2-35b5-568a-a5cb-dabb33423496', 'choice', '{"en": "Which name means \"Peace\" (the Source of peace)?", "bn": "কোন নামের অর্থ \"শান্তি\" (শান্তির উৎস)?"}', '{"options": [{"en": "As-Salam", "bn": "আস-সালাম"}, {"en": "Al-Malik", "bn": "আল-মালিক"}, {"en": "Al-Haqq", "bn": "আল-হক"}, {"en": "Al-Wali", "bn": "আল-ওয়ালি"}], "correct": 0}', '{"en": "\"…the King, the Holy, the Peace (As-Salam)…\"", "bn": "\"…অধিপতি, পবিত্র, শান্তি (আস-সালাম)…\""}', 'Quran 59:23', 7) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_lessons (id, unit_id, title, kind, sort_order) VALUES ('49632ebd-a796-5c9f-806f-ee45757f9df3', '5e15e158-9704-5aca-a1b2-1062a8cb0dbe', '{"en": "Angels and the unseen", "bn": "ফেরেশতা ও গায়েব"}', 'lesson', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('6df4940f-1e2f-52d0-b071-e897dc9cdd10', '49632ebd-a796-5c9f-806f-ee45757f9df3', 'choice', '{"en": "Angels were created from…?", "bn": "ফেরেশতারা কী থেকে সৃষ্ট?"}', '{"options": [{"en": "Light", "bn": "নূর (আলো)"}, {"en": "Fire", "bn": "আগুন"}, {"en": "Clay", "bn": "মাটি"}, {"en": "Water", "bn": "পানি"}], "correct": 0}', '{"en": "\"Angels were created from light, jinn from smokeless fire, and Adam from what you have been told.\"", "bn": "\"ফেরেশতারা নূর থেকে, জিন ধোঁয়াহীন আগুন থেকে, আর আদম তা থেকে যা তোমাদের বলা হয়েছে।\""}', 'Sahih Muslim 2996', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('f5bfbc82-a707-5cbd-8303-c19a20d5db1d', '49632ebd-a796-5c9f-806f-ee45757f9df3', 'match', '{"en": "Match each to what it was created from", "bn": "কে কী থেকে সৃষ্টি, মেলান"}', '{"pairs": [{"left": {"en": "Angels", "bn": "ফেরেশতা"}, "right": {"en": "Light", "bn": "নূর (আলো)"}}, {"left": {"en": "Jinn", "bn": "জিন"}, "right": {"en": "Smokeless fire", "bn": "ধোঁয়াহীন আগুন"}}, {"left": {"en": "Adam", "bn": "আদম (আ.)"}, "right": {"en": "Clay", "bn": "মাটি"}}]}', '{"en": "What each was created from.", "bn": "কে কী থেকে সৃষ্টি।"}', 'Sahih Muslim 2996; Quran 55:14–15', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('00f3ca5f-df45-5c11-8d26-74ed50f2aba4', '49632ebd-a796-5c9f-806f-ee45757f9df3', 'choice', '{"en": "Which angel is called \"the trustworthy spirit\" (ar-Ruh al-Amin)?", "bn": "কোন ফেরেশতাকে \"রুহুল আমিন\" (বিশ্বস্ত আত্মা) বলা হয়?"}', '{"options": [{"en": "Jibril", "bn": "জিবরাইল"}, {"en": "Mika’il", "bn": "মিকাইল"}, {"en": "Malik", "bn": "মালিক"}, {"en": "Ridwan", "bn": "রিদওয়ান"}], "correct": 0}', '{"en": "\"The trustworthy spirit has brought it down upon your heart.\"", "bn": "\"বিশ্বস্ত আত্মা (রুহুল আমিন) এটি তোমার হৃদয়ে নাজিল করেছেন।\""}', 'Quran 26:193–194', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('53df2ebb-4b5c-5220-953b-33871e12aaa8', '49632ebd-a796-5c9f-806f-ee45757f9df3', 'true_false', '{"en": "Angels sometimes disobey Allah’s commands.", "bn": "ফেরেশতারা কখনো কখনো আল্লাহর আদেশ অমান্য করেন।"}', '{"answer": false}', '{"en": "\"They do not disobey Allah in what He commands them, and they do what they are commanded.\"", "bn": "\"তারা আল্লাহর আদেশ অমান্য করে না এবং যা আদেশ করা হয় তা-ই করে।\""}', 'Quran 66:6', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('00764ae4-e438-55fe-be3b-93b06dd7ced2', '49632ebd-a796-5c9f-806f-ee45757f9df3', 'choice', '{"en": "What are the angels who record our deeds called in the Quran?", "bn": "আমাদের আমল লেখেন যে ফেরেশতারা, কুরআনে তাঁদের কী বলা হয়েছে?"}', '{"options": [{"en": "Noble recorders (Kiraman Katibin)", "bn": "সম্মানিত লেখকগণ (কিরামান কাতিবিন)"}, {"en": "Ansar", "bn": "আনসার"}, {"en": "Muhajirun", "bn": "মুহাজির"}, {"en": "Hawariyyun", "bn": "হাওয়ারি"}], "correct": 0}', '{"en": "\"Noble, recording; they know what you do.\"", "bn": "\"সম্মানিত লেখকগণ; তারা জানে তোমরা যা করো।\""}', 'Quran 82:10–12', 5) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('fa9ca0d8-f986-5466-8f0e-82685e99a3ce', '49632ebd-a796-5c9f-806f-ee45757f9df3', 'choice', '{"en": "Which two angels question the dead in the grave?", "bn": "কোন দুই ফেরেশতা কবরে মৃতকে প্রশ্ন করেন?"}', '{"options": [{"en": "Munkar and Nakir", "bn": "মুনকার ও নাকির"}, {"en": "Harut and Marut", "bn": "হারুত ও মারুত"}, {"en": "Jibril and Mika’il", "bn": "জিবরাইল ও মিকাইল"}, {"en": "Ridwan and Malik", "bn": "রিদওয়ান ও মালিক"}], "correct": 0}', '{"en": "They ask: Who is your Lord? What is your religion? Who is your prophet?", "bn": "তাঁরা জিজ্ঞেস করেন: তোমার রব কে? তোমার দ্বীন কী? তোমার নবী কে?"}', 'Jami‘ at-Tirmidhi 1071', 6) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('da132a7b-fc04-500e-8577-f0a726d57a13', '49632ebd-a796-5c9f-806f-ee45757f9df3', 'true_false', '{"en": "Iblis was one of the angels.", "bn": "ইবলিস ফেরেশতাদের একজন ছিল।"}', '{"answer": false}', '{"en": "\"He was of the jinn, and he rebelled against his Lord’s command.\"", "bn": "\"সে ছিল জিনদের একজন, সে তার রবের আদেশ অমান্য করল।\""}', 'Quran 18:50', 7) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_lessons (id, unit_id, title, kind, sort_order) VALUES ('2ee9f1cd-b834-55da-b75e-1374ac756f20', '5e15e158-9704-5aca-a1b2-1062a8cb0dbe', '{"en": "The Last Day", "bn": "শেষ দিবস"}', 'lesson', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('bd8ba5b9-c084-5835-821e-5ddd71599e07', '2ee9f1cd-b834-55da-b75e-1374ac756f20', 'choice', '{"en": "What is the stage between death and the Resurrection called?", "bn": "মৃত্যু ও পুনরুত্থানের মাঝের জগৎকে কী বলে?"}', '{"options": [{"en": "Barzakh", "bn": "বারযাখ"}, {"en": "Dunya", "bn": "দুনিয়া"}, {"en": "Mahshar", "bn": "হাশর"}, {"en": "A‘raf", "bn": "আরাফ"}], "correct": 0}', '{"en": "\"…and behind them is a barrier (barzakh) until the Day they are resurrected.\"", "bn": "\"…আর তাদের সামনে পুনরুত্থান দিবস পর্যন্ত এক অন্তরাল (বারযাখ)।\""}', 'Quran 23:100', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('79d646ef-527b-5773-bce4-337d7648cc7a', '2ee9f1cd-b834-55da-b75e-1374ac756f20', 'order', '{"en": "Put these in the order they come", "bn": "যে ক্রমে আসবে সেভাবে সাজান"}', '{"pieces": [{"en": "Death", "bn": "মৃত্যু"}, {"en": "The barzakh (the grave)", "bn": "বারযাখ (কবর)"}, {"en": "The Trumpet and the Resurrection", "bn": "শিঙায় ফুঁ ও পুনরুত্থান"}, {"en": "The Scale (al-Mizan)", "bn": "মিযান (দাঁড়িপাল্লা)"}, {"en": "The bridge (as-Sirat)", "bn": "সিরাত (পুল)"}], "rtl": false}', '{"en": "After death comes the barzakh until the Trumpet; then the Resurrection, the weighing of deeds, and the bridge over Hell.", "bn": "মৃত্যুর পর শিঙায় ফুঁ পর্যন্ত বারযাখ; তারপর পুনরুত্থান, আমল ওজন, আর জাহান্নামের ওপরের পুল।"}', 'Quran 23:100, 39:68, 21:47; Sahih al-Bukhari 806', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('da27db59-5a9d-50e5-9e2d-3cd1f1a1ecd5', '2ee9f1cd-b834-55da-b75e-1374ac756f20', 'choice', '{"en": "What is the bridge over Hell called?", "bn": "জাহান্নামের ওপরের সেতুকে কী বলে?"}', '{"options": [{"en": "As-Sirat", "bn": "সিরাত"}, {"en": "Al-Mizan", "bn": "মিজান"}, {"en": "Al-Hawd", "bn": "হাউজ"}, {"en": "Al-A‘raf", "bn": "আরাফ"}], "correct": 0}', '{"en": "As-Sirat is laid over Hell and everyone passes over it.", "bn": "জাহান্নামের ওপর সিরাত স্থাপন করা হবে এবং সবাই তা পার হবে।"}', 'Sahih al-Bukhari 806', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('e764bc6e-5b6f-58f3-9fcf-81b01962873c', '2ee9f1cd-b834-55da-b75e-1374ac756f20', 'choice', '{"en": "Deeds are weighed on…?", "bn": "আমল কিসে ওজন করা হবে?"}', '{"options": [{"en": "Al-Mizan (the Scale)", "bn": "মিজান (দাঁড়িপাল্লা)"}, {"en": "As-Sirat", "bn": "সিরাত"}, {"en": "The Kursi", "bn": "কুরসি"}, {"en": "The Book", "bn": "আমলনামা"}], "correct": 0}', '{"en": "\"And We place the scales of justice for the Day of Resurrection.\"", "bn": "\"আর কিয়ামতের দিন আমি ন্যায়বিচারের দাঁড়িপাল্লা স্থাপন করব।\""}', 'Quran 21:47', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('77349263-c48b-5f17-bb0e-91d5cc78acca', '2ee9f1cd-b834-55da-b75e-1374ac756f20', 'true_false', '{"en": "Those who fast will enter Paradise through a gate called Ar-Rayyan.", "bn": "রোজাদাররা রাইয়ান নামের দরজা দিয়ে জান্নাতে প্রবেশ করবে।"}', '{"answer": true}', '{"en": "\"In Paradise there is a gate called Ar-Rayyan; those who fast will enter through it.\"", "bn": "\"জান্নাতে রাইয়ান নামে একটি দরজা আছে; রোজাদাররা তা দিয়ে প্রবেশ করবে।\""}', 'Sahih al-Bukhari 1896', 5) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('f068b57a-be88-5c4a-bd33-01dcfb71ba9e', '2ee9f1cd-b834-55da-b75e-1374ac756f20', 'choice', '{"en": "What is the highest level of Paradise?", "bn": "জান্নাতের সর্বোচ্চ স্তর কোনটি?"}', '{"options": [{"en": "Al-Firdaws", "bn": "ফিরদাউস"}, {"en": "Adn", "bn": "আদন"}, {"en": "Na‘im", "bn": "নাঈম"}, {"en": "Ma’wa", "bn": "মাওয়া"}], "correct": 0}', '{"en": "\"When you ask Allah, ask Him for al-Firdaws; it is the middle and highest of Paradise.\"", "bn": "\"আল্লাহর কাছে চাইলে ফিরদাউস চাও; এটি জান্নাতের মধ্যবর্তী ও সর্বোচ্চ।\""}', 'Sahih al-Bukhari 2790', 6) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('c7d63bec-7acb-5010-859b-c929c53e8819', '2ee9f1cd-b834-55da-b75e-1374ac756f20', 'choice', '{"en": "Receiving one’s record in the right hand means…?", "bn": "ডান হাতে আমলনামা পাওয়ার অর্থ…?"}', '{"options": [{"en": "Success", "bn": "সফলতা"}, {"en": "Loss", "bn": "ক্ষতি"}, {"en": "Waiting", "bn": "অপেক্ষা"}, {"en": "Nothing", "bn": "কিছুই না"}], "correct": 0}', '{"en": "\"As for him who is given his record in his right hand, he will say: Here, read my record!\"", "bn": "\"যাকে তার আমলনামা ডান হাতে দেওয়া হবে, সে বলবে: এই নাও, আমার আমলনামা পড়ো!\""}', 'Quran 69:19', 7) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_lessons (id, unit_id, title, kind, sort_order) VALUES ('ba26e970-9ef0-5b8f-8589-b2139fd7616f', '5e15e158-9704-5aca-a1b2-1062a8cb0dbe', '{"en": "Unit review", "bn": "ইউনিট রিভিউ"}', 'checkpoint', 5) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('034a0584-57fb-5ea1-9686-15a7bf9c057b', 'ba26e970-9ef0-5b8f-8589-b2139fd7616f', 'choice', '{"en": "Which book was given to Musa?", "bn": "মুসা (আ.)-কে কোন কিতাব দেওয়া হয়েছিল?"}', '{"options": [{"en": "Injil", "bn": "ইঞ্জিল"}, {"en": "Zabur", "bn": "যাবুর"}, {"en": "Tawrah", "bn": "তাওরাত"}, {"en": "Quran", "bn": "কুরআন"}], "correct": 2}', '{"en": "The Tawrah (Torah), \"in which was guidance and light\".", "bn": "তাওরাত, \"যাতে ছিল হেদায়াত ও আলো\"।"}', 'Quran 5:44', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('787178b2-001c-53ee-8c35-1c790282ea69', 'ba26e970-9ef0-5b8f-8589-b2139fd7616f', 'choice', '{"en": "What does \"Al-Ghafur\" mean?", "bn": "\"আল-গফুর\" অর্থ কী?"}', '{"options": [{"en": "The Strong", "bn": "মহাশক্তিমান"}, {"en": "The Forgiving", "bn": "ক্ষমাশীল"}, {"en": "The Light", "bn": "আলো"}, {"en": "The Rich", "bn": "অভাবমুক্ত"}], "correct": 1}', '{"en": "Al-Ghafur forgives sins again and again.", "bn": "আল-গফুর বারবার গুনাহ ক্ষমা করেন।"}', 'Quran 39:53', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('0c4d5c29-6b38-5279-930c-aac0e1aa82d5', 'ba26e970-9ef0-5b8f-8589-b2139fd7616f', 'true_false', '{"en": "Belief in the decree (qadar) is a pillar of iman.", "bn": "তাকদিরে বিশ্বাস ঈমানের একটি স্তম্ভ।"}', '{"answer": true}', '{"en": "\"…and that you believe in the decree, its good and its bad.\"", "bn": "\"…এবং তাকদিরের ভালো-মন্দে বিশ্বাস করবে।\""}', 'Sahih Muslim 8', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('ee6bfdae-f697-5cd6-bd47-c0969dcb6bad', 'ba26e970-9ef0-5b8f-8589-b2139fd7616f', 'choice', '{"en": "What does the Quran call the angel who takes souls?", "bn": "রুহ কবজকারী ফেরেশতাকে কুরআনে কী বলা হয়েছে?"}', '{"options": [{"en": "The Angel of Death", "bn": "মালাকুল মাওত (মৃত্যুর ফেরেশতা)"}, {"en": "The Angel of Rain", "bn": "বৃষ্টির ফেরেশতা"}, {"en": "The Recorder", "bn": "লেখক"}, {"en": "The Guardian", "bn": "রক্ষী"}], "correct": 0}', '{"en": "\"The Angel of Death who has been entrusted with you will take you.\"", "bn": "\"তোমাদের দায়িত্বে নিযুক্ত মৃত্যুর ফেরেশতা তোমাদের প্রাণ হরণ করবে।\""}', 'Quran 32:11', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('458137a5-e7a6-5738-b40d-894a1a046294', 'ba26e970-9ef0-5b8f-8589-b2139fd7616f', 'choice', '{"en": "The Resurrection begins when what is blown?", "bn": "কী ফুঁ দেওয়ার মাধ্যমে কিয়ামত শুরু হবে?"}', '{"options": [{"en": "The Trumpet (as-Sur)", "bn": "শিঙ্গা (সুর)"}, {"en": "A wind", "bn": "বাতাস"}, {"en": "A drum", "bn": "ঢোল"}, {"en": "A whistle", "bn": "বাঁশি"}], "correct": 0}', '{"en": "\"And the Trumpet will be blown…\"", "bn": "\"আর শিঙ্গায় ফুঁ দেওয়া হবে…\""}', 'Quran 39:68', 5) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('777ca59b-8677-5531-8a79-64e9a64b67cc', 'ba26e970-9ef0-5b8f-8589-b2139fd7616f', 'choice', '{"en": "Which is another Quranic name for the Last Day?", "bn": "শেষ দিবসের আরেকটি কুরআনি নাম কোনটি?"}', '{"options": [{"en": "As-Sa‘ah (the Hour)", "bn": "আস-সাআহ (মহাক্ষণ)"}, {"en": "Al-Hijrah", "bn": "আল-হিজরাহ"}, {"en": "Al-Isra", "bn": "আল-ইসরা"}, {"en": "Al-Qiblah", "bn": "আল-কিবলা"}], "correct": 0}', '{"en": "\"They ask you about the Hour…\"", "bn": "\"তারা আপনাকে কিয়ামত (মহাক্ষণ) সম্পর্কে জিজ্ঞেস করে…\""}', 'Quran 7:187', 6) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('52fabd5b-f651-5930-99bc-b21131f50e19', 'ba26e970-9ef0-5b8f-8589-b2139fd7616f', 'choice', '{"en": "What does \"Al-Hakim\" mean?", "bn": "\"আল-হাকিম\" অর্থ কী?"}', '{"options": [{"en": "The Wise", "bn": "প্রজ্ঞাময়"}, {"en": "The Living", "bn": "চিরঞ্জীব"}, {"en": "The Hearer", "bn": "সর্বশ্রোতা"}, {"en": "The Guardian", "bn": "অভিভাবক"}], "correct": 0}', '{"en": "Everything Al-Hakim does and commands is with wisdom.", "bn": "আল-হাকিম যা করেন ও আদেশ দেন, সবই প্রজ্ঞার সাথে।"}', 'Quran 2:32', 7) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('80011ae7-38a0-5437-94ce-a56268ead928', 'ba26e970-9ef0-5b8f-8589-b2139fd7616f', 'choice', '{"en": "Who will have the greatest intercession (shafa‘ah) on that Day?", "bn": "সেদিন সর্বশ্রেষ্ঠ শাফাআত কার?"}', '{"options": [{"en": "Muhammad ﷺ", "bn": "মুহাম্মাদ ﷺ"}, {"en": "Adam", "bn": "আদম"}, {"en": "Nuh", "bn": "নুহ"}, {"en": "Isa", "bn": "ঈসা"}], "correct": 0}', '{"en": "People will go from prophet to prophet until they come to Muhammad ﷺ.", "bn": "মানুষ নবী থেকে নবীর কাছে যাবে, অবশেষে মুহাম্মাদ ﷺ-এর কাছে আসবে।"}', 'Sahih al-Bukhari 4712', 8) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_units (id, title, description, color, icon, review_status, sort_order, section_id) VALUES ('5118ab6b-d613-5022-aab8-9fb95411b564', '{"en": "Pillars of iman & Allah’s names", "bn": "ঈমানের স্তম্ভ ও আল্লাহর নাম"}', '{}', '#44bd32', 'sparkles', 'in_review', 1, 'a2557c82-65b6-5ce2-bd30-42cc4cfe7fba') ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_lessons (id, unit_id, title, kind, sort_order) VALUES ('f43d3456-bc9f-5859-91a0-91d79c4092e0', '5118ab6b-d613-5022-aab8-9fb95411b564', '{"en": "Part 1", "bn": "পর্ব ১"}', 'lesson', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('347fadf4-7dba-56ee-a861-b3513720d9c4', 'f43d3456-bc9f-5859-91a0-91d79c4092e0', 'choice', '{"en": "Which of these is NOT a pillar of iman?", "bn": "কোনটি ঈমানের স্তম্ভ নয়?"}', '{"options": [{"en": "Belief in angels", "bn": "ফেরেশতায় বিশ্বাস"}, {"en": "Belief in the books", "bn": "কিতাবে বিশ্বাস"}, {"en": "Belief in the decree", "bn": "তাকদিরে বিশ্বাস"}, {"en": "Performing Hajj", "bn": "হজ পালন"}], "correct": 3}', '{"en": "Hajj is a pillar of Islam (an action), not of iman (belief).", "bn": "হজ ইসলামের স্তম্ভ (আমল), ঈমানের (বিশ্বাস) নয়।"}', 'Sahih Muslim 8', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('9b7a4831-6f6a-5d0d-a519-72fd34748dd1', 'f43d3456-bc9f-5859-91a0-91d79c4092e0', 'choice', '{"en": "Which angel is named in the Quran as the keeper of Hellfire?", "bn": "কুরআনে জাহান্নামের রক্ষী হিসেবে কোন ফেরেশতার নাম আছে?"}', '{"options": [{"en": "Ridwan", "bn": "রিদওয়ান"}, {"en": "Malik", "bn": "মালিক"}, {"en": "Jibril", "bn": "জিবরাইল"}, {"en": "Mika’il", "bn": "মিকাইল"}], "correct": 1}', '{"en": "\"They will call: O Malik…\"", "bn": "\"তারা ডাকবে: হে মালিক…\""}', 'Quran 43:77', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('d6adaef0-221b-5d6a-952e-75d4dadb54f5', 'f43d3456-bc9f-5859-91a0-91d79c4092e0', 'choice', '{"en": "The Injil was given to which prophet?", "bn": "ইঞ্জিল কোন নবীকে দেওয়া হয়েছিল?"}', '{"options": [{"en": "Isa", "bn": "ঈসা"}, {"en": "Musa", "bn": "মুসা"}, {"en": "Dawud", "bn": "দাউদ"}, {"en": "Ibrahim", "bn": "ইবরাহিম"}], "correct": 0}', '{"en": "\"And We gave him (Isa) the Injil.\"", "bn": "\"আর আমি তাকে (ঈসাকে) ইঞ্জিল দিয়েছি।\""}', 'Quran 5:46', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('cfbb73f9-ac53-5e3b-8f8a-436cfe424dc1', 'f43d3456-bc9f-5859-91a0-91d79c4092e0', 'choice', '{"en": "Iman, according to the hadith, has how many branches (more than)?", "bn": "হাদিস অনুযায়ী ঈমানের শাখা কতটির বেশি?"}', '{"options": [{"en": "Ten", "bn": "দশ"}, {"en": "Twenty", "bn": "বিশ"}, {"en": "Sixty or seventy", "bn": "ষাট বা সত্তর"}, {"en": "One hundred", "bn": "একশ"}], "correct": 2}', '{"en": "\"Iman has seventy-some (or sixty-some) branches; modesty is one of them.\"", "bn": "\"ঈমানের সত্তরের বেশি (বা ষাটের বেশি) শাখা আছে; লজ্জা তার একটি।\""}', 'Sahih Muslim 35', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('09baa440-2f6f-5f1a-bf68-74b65a5370ed', 'f43d3456-bc9f-5859-91a0-91d79c4092e0', 'choice', '{"en": "Which name means \"The Provider\"?", "bn": "কোন নামের অর্থ \"রিজিকদাতা\"?"}', '{"options": [{"en": "Al-Hakim", "bn": "আল-হাকিম"}, {"en": "Ar-Razzaq", "bn": "আর-রাযযাক"}, {"en": "Al-Basir", "bn": "আল-বাসির"}, {"en": "Al-Awwal", "bn": "আল-আউয়াল"}], "correct": 1}', '{"en": "\"Indeed, Allah is the Provider, the Firm Possessor of strength.\"", "bn": "\"নিশ্চয়ই আল্লাহই রিজিকদাতা, প্রবল শক্তির অধিকারী।\""}', 'Quran 51:58', 5) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('e77ad589-3401-5387-a4d1-52df40691d19', 'f43d3456-bc9f-5859-91a0-91d79c4092e0', 'choice', '{"en": "What does \"Al-‘Alim\" mean?", "bn": "\"আল-আলিম\" অর্থ কী?"}', '{"options": [{"en": "The All-Knowing", "bn": "সর্বজ্ঞ"}, {"en": "The Most High", "bn": "সর্বোচ্চ"}, {"en": "The Patient", "bn": "ধৈর্যশীল"}, {"en": "The Generous", "bn": "দানশীল"}], "correct": 0}', '{"en": "Nothing is hidden from Al-‘Alim.", "bn": "আল-আলিমের কাছে কিছুই গোপন নয়।"}', 'Quran 2:29', 6) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('4679e37b-9d96-508d-a64e-41e594cd911e', 'f43d3456-bc9f-5859-91a0-91d79c4092e0', 'choice', '{"en": "What does \"Al-Wadud\" mean?", "bn": "\"আল-ওয়াদুদ\" অর্থ কী?"}', '{"options": [{"en": "The Loving", "bn": "প্রেমময়"}, {"en": "The Last", "bn": "অন্তিম"}, {"en": "The Witness", "bn": "সাক্ষী"}, {"en": "The Opener", "bn": "উন্মোচনকারী"}], "correct": 0}', '{"en": "\"And He is the Forgiving, the Loving.\"", "bn": "\"আর তিনি ক্ষমাশীল, প্রেমময়।\""}', 'Quran 85:14', 7) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('20e7efa7-878b-55c7-8de9-9e0bcc9c5536', 'f43d3456-bc9f-5859-91a0-91d79c4092e0', 'choice', '{"en": "How many names does the hadith mention, whoever learns them enters Paradise?", "bn": "যে হাদিসে বলা হয়েছে এগুলো আয়ত্ত করলে জান্নাত, সেখানে কয়টি নামের কথা আছে?"}', '{"options": [{"en": "33", "bn": "৩৩"}, {"en": "77", "bn": "৭৭"}, {"en": "99", "bn": "৯৯"}, {"en": "100", "bn": "১০০"}], "correct": 2}', '{"en": "\"Allah has ninety-nine names; whoever enumerates them enters Paradise.\"", "bn": "\"আল্লাহর নিরানব্বইটি নাম আছে; যে এগুলো আয়ত্ত করবে সে জান্নাতে যাবে।\""}', 'Sahih al-Bukhari 2736', 8) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_lessons (id, unit_id, title, kind, sort_order) VALUES ('febd30bc-f292-535f-a167-94472b2a3d52', '5118ab6b-d613-5022-aab8-9fb95411b564', '{"en": "Unit review", "bn": "ইউনিট রিভিউ"}', 'checkpoint', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('3b55b327-29a6-58ee-b9bd-d3063ac02687', 'febd30bc-f292-535f-a167-94472b2a3d52', 'choice', '{"en": "Which angel is named in the Quran as the keeper of Hellfire?", "bn": "কুরআনে জাহান্নামের রক্ষী হিসেবে কোন ফেরেশতার নাম আছে?"}', '{"options": [{"en": "Ridwan", "bn": "রিদওয়ান"}, {"en": "Malik", "bn": "মালিক"}, {"en": "Jibril", "bn": "জিবরাইল"}, {"en": "Mika’il", "bn": "মিকাইল"}], "correct": 1}', '{"en": "\"They will call: O Malik…\"", "bn": "\"তারা ডাকবে: হে মালিক…\""}', 'Quran 43:77', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('199a54d8-c7a0-5d3f-8fa9-a6abb06c7529', 'febd30bc-f292-535f-a167-94472b2a3d52', 'choice', '{"en": "Iman, according to the hadith, has how many branches (more than)?", "bn": "হাদিস অনুযায়ী ঈমানের শাখা কতটির বেশি?"}', '{"options": [{"en": "Ten", "bn": "দশ"}, {"en": "Twenty", "bn": "বিশ"}, {"en": "Sixty or seventy", "bn": "ষাট বা সত্তর"}, {"en": "One hundred", "bn": "একশ"}], "correct": 2}', '{"en": "\"Iman has seventy-some (or sixty-some) branches; modesty is one of them.\"", "bn": "\"ঈমানের সত্তরের বেশি (বা ষাটের বেশি) শাখা আছে; লজ্জা তার একটি।\""}', 'Sahih Muslim 35', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('db7ac897-418f-5415-8382-55e7144a2bd0', 'febd30bc-f292-535f-a167-94472b2a3d52', 'choice', '{"en": "What does \"Al-‘Alim\" mean?", "bn": "\"আল-আলিম\" অর্থ কী?"}', '{"options": [{"en": "The All-Knowing", "bn": "সর্বজ্ঞ"}, {"en": "The Most High", "bn": "সর্বোচ্চ"}, {"en": "The Patient", "bn": "ধৈর্যশীল"}, {"en": "The Generous", "bn": "দানশীল"}], "correct": 0}', '{"en": "Nothing is hidden from Al-‘Alim.", "bn": "আল-আলিমের কাছে কিছুই গোপন নয়।"}', 'Quran 2:29', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('d63abfa7-0462-52d9-8c92-17f6e4263b29', 'febd30bc-f292-535f-a167-94472b2a3d52', 'choice', '{"en": "How many names does the hadith mention, whoever learns them enters Paradise?", "bn": "যে হাদিসে বলা হয়েছে এগুলো আয়ত্ত করলে জান্নাত, সেখানে কয়টি নামের কথা আছে?"}', '{"options": [{"en": "33", "bn": "৩৩"}, {"en": "77", "bn": "৭৭"}, {"en": "99", "bn": "৯৯"}, {"en": "100", "bn": "১০০"}], "correct": 2}', '{"en": "\"Allah has ninety-nine names; whoever enumerates them enters Paradise.\"", "bn": "\"আল্লাহর নিরানব্বইটি নাম আছে; যে এগুলো আয়ত্ত করবে সে জান্নাতে যাবে।\""}', 'Sahih al-Bukhari 2736', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('ebce3998-4a9e-5d3c-8eac-530d0c6159ba', 'febd30bc-f292-535f-a167-94472b2a3d52', 'choice', '{"en": "Which of these is NOT a pillar of iman?", "bn": "কোনটি ঈমানের স্তম্ভ নয়?"}', '{"options": [{"en": "Belief in angels", "bn": "ফেরেশতায় বিশ্বাস"}, {"en": "Belief in the books", "bn": "কিতাবে বিশ্বাস"}, {"en": "Belief in the decree", "bn": "তাকদিরে বিশ্বাস"}, {"en": "Performing Hajj", "bn": "হজ পালন"}], "correct": 3}', '{"en": "Hajj is a pillar of Islam (an action), not of iman (belief).", "bn": "হজ ইসলামের স্তম্ভ (আমল), ঈমানের (বিশ্বাস) নয়।"}', 'Sahih Muslim 8', 5) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_units (id, title, description, color, icon, review_status, sort_order, section_id) VALUES ('566887b0-c10c-5810-96e3-2777cd8ef91e', '{"en": "The unseen & the Hereafter", "bn": "গায়েব ও আখিরাত"}', '{}', '#44bd32', 'sparkles', 'in_review', 2, 'a2557c82-65b6-5ce2-bd30-42cc4cfe7fba') ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_lessons (id, unit_id, title, kind, sort_order) VALUES ('62b5eb6c-62a2-5d2c-8782-02be60279e71', '566887b0-c10c-5810-96e3-2777cd8ef91e', '{"en": "Part 1", "bn": "পর্ব ১"}', 'lesson', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('6da70ba5-3eb9-5dae-91f0-81620780f540', '62b5eb6c-62a2-5d2c-8782-02be60279e71', 'choice', '{"en": "Jinn were created from…?", "bn": "জিন কী থেকে সৃষ্ট?"}', '{"options": [{"en": "Smokeless fire", "bn": "ধোঁয়াহীন আগুন"}, {"en": "Light", "bn": "আলো"}, {"en": "Clay", "bn": "মাটি"}, {"en": "Air", "bn": "বাতাস"}], "correct": 0}', '{"en": "\"And He created the jinn from a smokeless flame of fire.\"", "bn": "\"আর তিনি জিনকে সৃষ্টি করেছেন ধোঁয়াহীন অগ্নিশিখা থেকে।\""}', 'Quran 55:15', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('352fdb2c-1ced-5df4-9464-edcfdeead276', '62b5eb6c-62a2-5d2c-8782-02be60279e71', 'choice', '{"en": "Adam was created from…?", "bn": "আদম (আ.) কী থেকে সৃষ্ট?"}', '{"options": [{"en": "Clay", "bn": "মাটি"}, {"en": "Light", "bn": "আলো"}, {"en": "Fire", "bn": "আগুন"}, {"en": "Stone", "bn": "পাথর"}], "correct": 0}', '{"en": "\"He created man from clay like pottery.\"", "bn": "\"তিনি মানুষকে সৃষ্টি করেছেন পোড়ামাটির মতো শুকনো মাটি থেকে।\""}', 'Quran 55:14', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('e959ce23-5d6d-57bd-90e9-60a540c2bebc', '62b5eb6c-62a2-5d2c-8782-02be60279e71', 'choice', '{"en": "Iblis refused to prostrate to whom?", "bn": "ইবলিস কাকে সিজদা করতে অস্বীকার করেছিল?"}', '{"options": [{"en": "Adam", "bn": "আদম"}, {"en": "Nuh", "bn": "নুহ"}, {"en": "The Ka‘bah", "bn": "কাবা"}, {"en": "The angels", "bn": "ফেরেশতাদের"}], "correct": 0}', '{"en": "\"…so they prostrated, except Iblis; he refused and was arrogant.\"", "bn": "\"…তারা সিজদা করল, ইবলিস ছাড়া; সে অস্বীকার করল ও অহংকার করল।\""}', 'Quran 2:34', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('2bc3f3d7-ac06-5f4f-acb5-c30d3d95f7d2', '62b5eb6c-62a2-5d2c-8782-02be60279e71', 'choice', '{"en": "Iblis was one of the…?", "bn": "ইবলিস কাদের অন্তর্ভুক্ত ছিল?"}', '{"options": [{"en": "Jinn", "bn": "জিন"}, {"en": "Angels", "bn": "ফেরেশতা"}, {"en": "Humans", "bn": "মানুষ"}, {"en": "Animals", "bn": "প্রাণী"}], "correct": 0}', '{"en": "\"…except Iblis. He was of the jinn.\"", "bn": "\"…ইবলিস ছাড়া। সে ছিল জিনদের একজন।\""}', 'Quran 18:50', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('f86ac832-5d9e-5662-9987-2057e5e3fd56', '62b5eb6c-62a2-5d2c-8782-02be60279e71', 'choice', '{"en": "Do angels disobey Allah’s commands?", "bn": "ফেরেশতারা কি আল্লাহর আদেশ অমান্য করেন?"}', '{"options": [{"en": "Never", "bn": "কখনো না"}, {"en": "Sometimes", "bn": "মাঝে মাঝে"}, {"en": "Often", "bn": "প্রায়ই"}, {"en": "Only at night", "bn": "শুধু রাতে"}], "correct": 0}', '{"en": "\"…they do not disobey Allah in what He commands them, and do what they are commanded.\"", "bn": "\"…তারা আল্লাহর আদেশ অমান্য করে না এবং যা আদেশ করা হয় তা-ই করে।\""}', 'Quran 66:6', 5) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('e91ada50-d3fc-5225-ad59-772042685918', '62b5eb6c-62a2-5d2c-8782-02be60279e71', 'choice', '{"en": "Harut and Marut were sent down in…?", "bn": "হারুত ও মারুতকে কোথায় পাঠানো হয়েছিল?"}', '{"options": [{"en": "Babylon", "bn": "বাবেল (ব্যাবিলন)"}, {"en": "Egypt", "bn": "মিশর"}, {"en": "Makkah", "bn": "মক্কা"}, {"en": "Yemen", "bn": "ইয়েমেন"}], "correct": 0}', '{"en": "\"…the two angels at Babylon, Harut and Marut.\"", "bn": "\"…বাবেলের দুই ফেরেশতা হারুত ও মারুত।\""}', 'Quran 2:102', 6) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('42277ce8-60fa-5572-bd47-d5d3d9ed6388', '62b5eb6c-62a2-5d2c-8782-02be60279e71', 'choice', '{"en": "What is the Prophet’s ﷺ pool on the Day of Judgement called?", "bn": "কিয়ামতের দিন নবীজির ﷺ হাউজের নাম কী?"}', '{"options": [{"en": "Al-Kawthar (al-Hawd)", "bn": "হাউজে কাউসার"}, {"en": "Zamzam", "bn": "যমযম"}, {"en": "Salsabil", "bn": "সালসাবিল"}, {"en": "Tasnim", "bn": "তাসনিম"}], "correct": 0}', '{"en": "Its water is whiter than milk; whoever drinks will never thirst again.", "bn": "এর পানি দুধের চেয়ে সাদা; যে পান করবে সে আর কখনো তৃষ্ণার্ত হবে না।"}', 'Sahih al-Bukhari 6579', 7) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('ca5ed105-6b8a-5e15-812e-ae5115675bdf', '62b5eb6c-62a2-5d2c-8782-02be60279e71', 'choice', '{"en": "Through which gate of Paradise will the fasting people enter?", "bn": "রোজাদাররা জান্নাতের কোন দরজা দিয়ে প্রবেশ করবে?"}', '{"options": [{"en": "Ar-Rayyan", "bn": "রাইয়ান"}, {"en": "As-Salam", "bn": "সালাম"}, {"en": "Al-Firdaws", "bn": "ফিরদাউস"}, {"en": "Al-Kawthar", "bn": "কাওসার"}], "correct": 0}', '{"en": "\"In Paradise there is a gate called ar-Rayyan; only those who fast enter through it.\"", "bn": "\"জান্নাতে রাইয়ান নামে একটি দরজা আছে; শুধু রোজাদাররাই তা দিয়ে প্রবেশ করবে।\""}', 'Sahih al-Bukhari 1896', 8) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('66e8ae77-b1df-586c-b19c-f75e8e9f7ca9', '62b5eb6c-62a2-5d2c-8782-02be60279e71', 'choice', '{"en": "The Quran describes a Day whose length is…?", "bn": "কুরআন এমন এক দিনের বর্ণনা দেয় যার দৈর্ঘ্য…?"}', '{"options": [{"en": "Fifty thousand years", "bn": "পঞ্চাশ হাজার বছর"}, {"en": "One week", "bn": "এক সপ্তাহ"}, {"en": "One year", "bn": "এক বছর"}, {"en": "One hour", "bn": "এক ঘণ্টা"}], "correct": 0}', '{"en": "\"…in a Day whose measure is fifty thousand years.\"", "bn": "\"…এমন এক দিনে যার পরিমাণ পঞ্চাশ হাজার বছর।\""}', 'Quran 70:4', 9) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_lessons (id, unit_id, title, kind, sort_order) VALUES ('a050bf29-bb4a-5bb4-968c-f0dc5f6f6f01', '566887b0-c10c-5810-96e3-2777cd8ef91e', '{"en": "Unit review", "bn": "ইউনিট রিভিউ"}', 'checkpoint', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('3bed61ed-ba5d-5791-933e-3c273bc7bd96', 'a050bf29-bb4a-5bb4-968c-f0dc5f6f6f01', 'choice', '{"en": "Adam was created from…?", "bn": "আদম (আ.) কী থেকে সৃষ্ট?"}', '{"options": [{"en": "Clay", "bn": "মাটি"}, {"en": "Light", "bn": "আলো"}, {"en": "Fire", "bn": "আগুন"}, {"en": "Stone", "bn": "পাথর"}], "correct": 0}', '{"en": "\"He created man from clay like pottery.\"", "bn": "\"তিনি মানুষকে সৃষ্টি করেছেন পোড়ামাটির মতো শুকনো মাটি থেকে।\""}', 'Quran 55:14', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('149f393e-1b83-5b4d-a2c7-09b5699bf41f', 'a050bf29-bb4a-5bb4-968c-f0dc5f6f6f01', 'choice', '{"en": "Iblis was one of the…?", "bn": "ইবলিস কাদের অন্তর্ভুক্ত ছিল?"}', '{"options": [{"en": "Jinn", "bn": "জিন"}, {"en": "Angels", "bn": "ফেরেশতা"}, {"en": "Humans", "bn": "মানুষ"}, {"en": "Animals", "bn": "প্রাণী"}], "correct": 0}', '{"en": "\"…except Iblis. He was of the jinn.\"", "bn": "\"…ইবলিস ছাড়া। সে ছিল জিনদের একজন।\""}', 'Quran 18:50', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('dc502367-94ee-5a72-a982-9d31e12d1d31', 'a050bf29-bb4a-5bb4-968c-f0dc5f6f6f01', 'choice', '{"en": "Harut and Marut were sent down in…?", "bn": "হারুত ও মারুতকে কোথায় পাঠানো হয়েছিল?"}', '{"options": [{"en": "Babylon", "bn": "বাবেল (ব্যাবিলন)"}, {"en": "Egypt", "bn": "মিশর"}, {"en": "Makkah", "bn": "মক্কা"}, {"en": "Yemen", "bn": "ইয়েমেন"}], "correct": 0}', '{"en": "\"…the two angels at Babylon, Harut and Marut.\"", "bn": "\"…বাবেলের দুই ফেরেশতা হারুত ও মারুত।\""}', 'Quran 2:102', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('7cc13b79-e50a-5331-bc75-255d007768f4', 'a050bf29-bb4a-5bb4-968c-f0dc5f6f6f01', 'choice', '{"en": "Through which gate of Paradise will the fasting people enter?", "bn": "রোজাদাররা জান্নাতের কোন দরজা দিয়ে প্রবেশ করবে?"}', '{"options": [{"en": "Ar-Rayyan", "bn": "রাইয়ান"}, {"en": "As-Salam", "bn": "সালাম"}, {"en": "Al-Firdaws", "bn": "ফিরদাউস"}, {"en": "Al-Kawthar", "bn": "কাওসার"}], "correct": 0}', '{"en": "\"In Paradise there is a gate called ar-Rayyan; only those who fast enter through it.\"", "bn": "\"জান্নাতে রাইয়ান নামে একটি দরজা আছে; শুধু রোজাদাররাই তা দিয়ে প্রবেশ করবে।\""}', 'Sahih al-Bukhari 1896', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('ddf72b57-4e25-5388-ab6b-813ed3ad0aa9', 'a050bf29-bb4a-5bb4-968c-f0dc5f6f6f01', 'choice', '{"en": "Jinn were created from…?", "bn": "জিন কী থেকে সৃষ্ট?"}', '{"options": [{"en": "Smokeless fire", "bn": "ধোঁয়াহীন আগুন"}, {"en": "Light", "bn": "আলো"}, {"en": "Clay", "bn": "মাটি"}, {"en": "Air", "bn": "বাতাস"}], "correct": 0}', '{"en": "\"And He created the jinn from a smokeless flame of fire.\"", "bn": "\"আর তিনি জিনকে সৃষ্টি করেছেন ধোঁয়াহীন অগ্নিশিখা থেকে।\""}', 'Quran 55:15', 5) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_units (id, title, description, color, icon, review_status, sort_order, section_id) VALUES ('5ce0dd03-14de-52d5-8b57-6646858b4501', '{"en": "Purity & Salah", "bn": "পবিত্রতা ও নামাজ"}', '{"en": "Wudu, the five prayers, the parts of salah and Al-Fatiha.", "bn": "অজু, পাঁচ ওয়াক্ত নামাজ, নামাজের অংশ ও সূরা ফাতিহা।"}', '#0097e6', 'clock', 'in_review', 1, 'a16558b9-89a0-5902-be44-64cf6a979fb0') ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_lessons (id, unit_id, title, kind, sort_order) VALUES ('8c485c97-cb2e-5596-85bd-f6881cca9b80', '5ce0dd03-14de-52d5-8b57-6646858b4501', '{"en": "Wudu", "bn": "অজু"}', 'lesson', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('176f1b65-fa1a-5bce-930f-99cb21b5b607', '8c485c97-cb2e-5596-85bd-f6881cca9b80', 'true_false', '{"en": "Wudu is needed before salah.", "bn": "নামাজের আগে অজু করা আবশ্যক।"}', '{"answer": true}', '{"en": "\"Allah does not accept the prayer of one who has broken his wudu until he performs wudu.\"", "bn": "\"অজু ভেঙে গেলে অজু না করা পর্যন্ত আল্লাহ নামাজ কবুল করেন না।\""}', 'Sahih al-Bukhari 135', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('eb79fc8c-3c71-5552-b52a-879a77908a93', '8c485c97-cb2e-5596-85bd-f6881cca9b80', 'order', '{"en": "Put the steps of wudu in order", "bn": "অজুর ধাপগুলো ক্রমানুসারে সাজান"}', '{"pieces": [{"en": "Wash the hands", "bn": "দুই হাত ধোয়া"}, {"en": "Rinse the mouth and nose", "bn": "কুলি করা ও নাকে পানি দেওয়া"}, {"en": "Wash the face", "bn": "মুখমণ্ডল ধোয়া"}, {"en": "Wash the arms to the elbows", "bn": "কনুই পর্যন্ত হাত ধোয়া"}, {"en": "Wipe the head", "bn": "মাথা মাসেহ করা"}, {"en": "Wash the feet to the ankles", "bn": "টাখনু পর্যন্ত পা ধোয়া"}], "rtl": false}', '{"en": "As Uthman (RA) showed the Prophet’s ﷺ wudu; the Quran names the face, arms, head and feet in this order.", "bn": "উসমান (রা.) নবী ﷺ-এর অজু যেভাবে দেখিয়েছেন; কুরআনেও মুখ, হাত, মাথা ও পা এই ক্রমে আছে।"}', 'Quran 5:6; Sahih al-Bukhari 159', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('39d6a701-c417-50ff-8c90-42595b9ff117', '8c485c97-cb2e-5596-85bd-f6881cca9b80', 'choice', '{"en": "Which of these breaks wudu?", "bn": "কোনটি অজু ভঙ্গ করে?"}', '{"options": [{"en": "Eating dates", "bn": "খেজুর খাওয়া"}, {"en": "Passing wind", "bn": "বায়ু নির্গত হওয়া"}, {"en": "Reading Quran", "bn": "কুরআন পড়া"}, {"en": "Smiling", "bn": "মুচকি হাসা"}], "correct": 1}', '{"en": "The Prophet ﷺ said prayer is not accepted from one who broke wudu until he makes wudu again; passing wind breaks it.", "bn": "নবী ﷺ বলেছেন, অজু ভেঙে গেলে নতুন অজু ছাড়া নামাজ কবুল হয় না; বায়ু নির্গত হলে অজু ভাঙে।"}', 'Sahih al-Bukhari 135', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('3061d88e-9f28-53ba-abe8-97574083e06a', '8c485c97-cb2e-5596-85bd-f6881cca9b80', 'true_false', '{"en": "Washing the feet up to the ankles is part of wudu.", "bn": "টাখনু পর্যন্ত পা ধোয়া অজুর অংশ।"}', '{"answer": true}', '{"en": "\"…and wash your feet to the ankles.\"", "bn": "\"…এবং টাখনু পর্যন্ত পা ধৌত করো।\""}', 'Quran 5:6', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('b4633bdd-fec1-50e2-b396-8f9ab4946167', '8c485c97-cb2e-5596-85bd-f6881cca9b80', 'choice', '{"en": "Purifying with clean earth when there is no water is called…?", "bn": "পানি না থাকলে পবিত্র মাটি দিয়ে পবিত্রতা অর্জনকে কী বলে?"}', '{"options": [{"en": "Ghusl", "bn": "গোসল"}, {"en": "Tayammum", "bn": "তায়াম্মুম"}, {"en": "Istinja", "bn": "ইস্তিনজা"}, {"en": "I‘tikaf", "bn": "ইতিকাফ"}], "correct": 1}', '{"en": "\"…and you find no water, then do tayammum with clean earth.\"", "bn": "\"…আর পানি না পাও, তবে পবিত্র মাটি দিয়ে তায়াম্মুম করো।\""}', 'Quran 4:43', 5) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('b65d9248-455e-5340-bf78-bbde557a4139', '8c485c97-cb2e-5596-85bd-f6881cca9b80', 'choice', '{"en": "Muslims face which direction in prayer?", "bn": "নামাজে মুসলমানরা কোন দিকে মুখ করেন?"}', '{"options": [{"en": "Jerusalem", "bn": "জেরুজালেম"}, {"en": "The Ka‘bah in Makkah", "bn": "মক্কার কাবা"}, {"en": "Madinah", "bn": "মদিনা"}, {"en": "East", "bn": "পূর্ব দিক"}], "correct": 1}', '{"en": "\"So turn your face towards al-Masjid al-Haram.\"", "bn": "\"সুতরাং আপনার মুখ মসজিদুল হারামের দিকে ফেরান।\""}', 'Quran 2:144', 6) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_lessons (id, unit_id, title, kind, sort_order) VALUES ('5f69c21f-f419-599d-bb92-c5cbdd4d609c', '5ce0dd03-14de-52d5-8b57-6646858b4501', '{"en": "The five prayers", "bn": "পাঁচ ওয়াক্ত নামাজ"}', 'lesson', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('e9d9f277-3cca-51ee-85d1-d387bee79184', '5f69c21f-f419-599d-bb92-c5cbdd4d609c', 'choice', '{"en": "How many obligatory prayers are there each day?", "bn": "প্রতিদিন কয় ওয়াক্ত নামাজ ফরজ?"}', '{"options": [{"en": "3", "bn": "৩"}, {"en": "5", "bn": "৫"}, {"en": "7", "bn": "৭"}, {"en": "2", "bn": "২"}], "correct": 1}', '{"en": "Fajr, Dhuhr, Asr, Maghrib and Isha.", "bn": "ফজর, যোহর, আসর, মাগরিব ও ইশা।"}', 'Sahih al-Bukhari 349', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('9513d332-44f3-5a56-9bf7-965497eabf19', '5f69c21f-f419-599d-bb92-c5cbdd4d609c', 'order', '{"en": "Put the prayers in the order of the day", "bn": "দিনের ক্রমে নামাজগুলো সাজান"}', '{"pieces": [{"en": "Fajr", "bn": "ফজর"}, {"en": "Dhuhr", "bn": "যোহর"}, {"en": "Asr", "bn": "আসর"}, {"en": "Maghrib", "bn": "মাগরিব"}, {"en": "Isha", "bn": "এশা"}], "rtl": false}', '{"en": "Fajr at dawn, Dhuhr after midday, Asr in the afternoon, Maghrib at sunset and Isha at night.", "bn": "ভোরে ফজর, দুপুরের পর যোহর, বিকেলে আসর, সূর্যাস্তে মাগরিব, রাতে এশা।"}', NULL, 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('dc276606-441d-5e83-9e35-3bbdc3385bb5', '5f69c21f-f419-599d-bb92-c5cbdd4d609c', 'match', '{"en": "Match each prayer to its fard rak‘ahs", "bn": "প্রতিটি নামাজের ফরজ রাকাত মেলান"}', '{"pairs": [{"left": {"en": "Fajr", "bn": "ফজর"}, "right": {"en": "2", "bn": "২"}}, {"left": {"en": "Maghrib", "bn": "মাগরিব"}, "right": {"en": "3", "bn": "৩"}}, {"left": {"en": "Isha", "bn": "এশা"}, "right": {"en": "4", "bn": "৪"}}]}', '{"en": "The fard rak‘ahs of each prayer (when not travelling).", "bn": "প্রতিটি নামাজের ফরজ রাকাত (মুসাফির না হলে)।"}', NULL, 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('be746c57-6f6c-519c-acd7-93fd73d97131', '5f69c21f-f419-599d-bb92-c5cbdd4d609c', 'choice', '{"en": "How many fard rak‘ahs are in Dhuhr (when not travelling)?", "bn": "যোহরের ফরজ কত রাকাত (মুসাফির না হলে)?"}', '{"options": [{"en": "2", "bn": "২"}, {"en": "3", "bn": "৩"}, {"en": "4", "bn": "৪"}, {"en": "5", "bn": "৫"}], "correct": 2}', '{"en": "Dhuhr, Asr and Isha have four fard rak‘ahs each.", "bn": "যোহর, আসর ও ইশার ফরজ চার রাকাত করে।"}', NULL, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('21db81a2-587f-50dd-bf93-afab4b807ad6', '5f69c21f-f419-599d-bb92-c5cbdd4d609c', 'choice', '{"en": "What is the call to prayer called?", "bn": "নামাজের আহ্বানকে কী বলে?"}', '{"options": [{"en": "Iqamah", "bn": "ইকামত"}, {"en": "Adhan", "bn": "আজান"}, {"en": "Khutbah", "bn": "খুতবা"}, {"en": "Takbir", "bn": "তাকবির"}], "correct": 1}', '{"en": "The adhan announces that the prayer time has come.", "bn": "আজান নামাজের সময় হয়েছে তা ঘোষণা করে।"}', NULL, 5) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('8d88973d-3295-5467-93ae-a8c1155ea276', '5f69c21f-f419-599d-bb92-c5cbdd4d609c', 'choice', '{"en": "What is the second call, just before the prayer starts?", "bn": "নামাজ শুরুর ঠিক আগের দ্বিতীয় আহ্বানকে কী বলে?"}', '{"options": [{"en": "Iqamah", "bn": "ইকামত"}, {"en": "Adhan", "bn": "আজান"}, {"en": "Du‘a", "bn": "দোয়া"}, {"en": "Salam", "bn": "সালাম"}], "correct": 0}', '{"en": "The iqamah tells those present that the congregation is starting.", "bn": "ইকামত জানিয়ে দেয় জামাত শুরু হচ্ছে।"}', NULL, 6) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('82e82d40-86a1-563c-96c6-3134ea07f93b', '5f69c21f-f419-599d-bb92-c5cbdd4d609c', 'choice', '{"en": "Which prayer replaces Dhuhr on Friday?", "bn": "শুক্রবার যোহরের পরিবর্তে কোন নামাজ?"}', '{"options": [{"en": "Jumu‘ah", "bn": "জুমা"}, {"en": "Eid", "bn": "ঈদ"}, {"en": "Duha", "bn": "দুহা"}, {"en": "Tahajjud", "bn": "তাহাজ্জুদ"}], "correct": 0}', '{"en": "The Friday prayer, with its khutbah.", "bn": "খুতবাসহ জুমার নামাজ।"}', 'Quran 62:9', 7) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_lessons (id, unit_id, title, kind, sort_order) VALUES ('648f2f29-8db5-5cb6-b084-2dd5ecc04bfd', '5ce0dd03-14de-52d5-8b57-6646858b4501', '{"en": "Inside the salah", "bn": "নামাজের ভেতরে"}', 'lesson', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('dc471cce-4b7d-5ec9-8ec0-eed198dd1498', '648f2f29-8db5-5cb6-b084-2dd5ecc04bfd', 'choice', '{"en": "With what words does salah begin?", "bn": "কোন বাক্য দিয়ে নামাজ শুরু হয়?"}', '{"options": [{"en": "Bismillah", "bn": "বিসমিল্লাহ"}, {"en": "Allahu Akbar", "bn": "আল্লাহু আকবার"}, {"en": "Alhamdulillah", "bn": "আলহামদুলিল্লাহ"}, {"en": "As-salamu alaykum", "bn": "আসসালামু আলাইকুম"}], "correct": 1}', '{"en": "The opening takbir; salah ends with the salam.", "bn": "তাকবিরে তাহরিমা দিয়ে শুরু, সালাম দিয়ে শেষ।"}', 'Sunan Abi Dawud 61', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('15e7e3c8-eaec-504a-aa46-4d4b3258590c', '648f2f29-8db5-5cb6-b084-2dd5ecc04bfd', 'order', '{"en": "Put the parts of a rak‘ah and its ending in order", "bn": "নামাজের অংশগুলো ক্রমানুসারে সাজান"}', '{"pieces": [{"en": "Takbir: Allahu Akbar", "bn": "তাকবির: আল্লাহু আকবার"}, {"en": "Standing and reciting Al-Fatiha", "bn": "দাঁড়িয়ে সূরা ফাতিহা পড়া"}, {"en": "Ruku‘ (bowing)", "bn": "রুকু"}, {"en": "Sujud (prostration)", "bn": "সিজদা"}, {"en": "Tashahhud (sitting)", "bn": "তাশাহহুদ (বসা)"}, {"en": "Salam", "bn": "সালাম"}], "rtl": false}', '{"en": "\"Its opening is the takbir and its closing is the salam.\"", "bn": "\"নামাজের শুরু তাকবির আর শেষ সালাম।\""}', 'Sunan Abi Dawud 61; Sahih al-Bukhari 757', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('609a919a-c74c-5210-a5ed-c0ca9735e0a2', '648f2f29-8db5-5cb6-b084-2dd5ecc04bfd', 'match', '{"en": "Match each word to its meaning", "bn": "প্রতিটি শব্দের অর্থ মেলান"}', '{"pairs": [{"left": {"en": "Qiyam", "bn": "কিয়াম"}, "right": {"en": "Standing", "bn": "দাঁড়ানো"}}, {"left": {"en": "Ruku‘", "bn": "রুকু"}, "right": {"en": "Bowing", "bn": "ঝুঁকে থাকা"}}, {"left": {"en": "Sujud", "bn": "সিজদা"}, "right": {"en": "Prostration", "bn": "মাটিতে কপাল রাখা"}}, {"left": {"en": "Tashahhud", "bn": "তাশাহহুদ"}, "right": {"en": "Sitting with the testimony", "bn": "বসে সাক্ষ্যবাণী পড়া"}}]}', '{"en": "The names of the positions of salah.", "bn": "নামাজের অবস্থাগুলোর নাম।"}', NULL, 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('9dd934b4-780d-5d81-87fd-142f9ed6e903', '648f2f29-8db5-5cb6-b084-2dd5ecc04bfd', 'choice', '{"en": "Which surah is recited in every rak‘ah?", "bn": "প্রতি রাকাতে কোন সূরা পড়া হয়?"}', '{"options": [{"en": "Al-Ikhlas", "bn": "আল-ইখলাস"}, {"en": "Al-Fatiha", "bn": "আল-ফাতিহা"}, {"en": "Al-Kawthar", "bn": "আল-কাওসার"}, {"en": "An-Nas", "bn": "আন-নাস"}], "correct": 1}', '{"en": "\"There is no prayer for one who does not recite al-Fatiha.\"", "bn": "\"যে সূরা ফাতিহা পড়ে না, তার নামাজ হয় না।\""}', 'Sahih al-Bukhari 756', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('7ed50b61-5d6a-5658-a1ae-4919737c1572', '648f2f29-8db5-5cb6-b084-2dd5ecc04bfd', 'choice', '{"en": "Prostrating in salah is called…?", "bn": "নামাজে সিজদা দেওয়াকে কী বলে?"}', '{"options": [{"en": "Ruku‘", "bn": "রুকু"}, {"en": "Sujud", "bn": "সিজদা"}, {"en": "Qiyam", "bn": "কিয়াম"}, {"en": "Tashahhud", "bn": "তাশাহহুদ"}], "correct": 1}', '{"en": "\"The closest a servant is to his Lord is while in sujud.\"", "bn": "\"বান্দা সিজদারত অবস্থায় তার রবের সবচেয়ে কাছে থাকে।\""}', 'Sahih Muslim 482', 5) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('086d15d6-0b3b-5cc7-88d8-3897653ced02', '648f2f29-8db5-5cb6-b084-2dd5ecc04bfd', 'true_false', '{"en": "Salah ends with the salam.", "bn": "সালামের মাধ্যমে নামাজ শেষ হয়।"}', '{"answer": true}', '{"en": "\"Its opening is the takbir and its closing is the salam.\"", "bn": "\"নামাজের শুরু তাকবির আর শেষ সালাম।\""}', 'Sunan Abi Dawud 61', 6) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('2d2f1551-41e7-5480-846d-c56ad9846d28', '648f2f29-8db5-5cb6-b084-2dd5ecc04bfd', 'choice', '{"en": "How does salah end?", "bn": "নামাজ কীভাবে শেষ হয়?"}', '{"options": [{"en": "With the salam", "bn": "সালাম দিয়ে"}, {"en": "With a takbir", "bn": "তাকবির দিয়ে"}, {"en": "With Ameen", "bn": "আমিন বলে"}, {"en": "By standing up", "bn": "উঠে দাঁড়িয়ে"}], "correct": 0}', '{"en": "\"Its beginning is the takbir and its ending is the taslim (salam).\"", "bn": "\"এর শুরু তাকবির আর শেষ সালাম।\""}', 'Sunan Abi Dawud 61', 7) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_lessons (id, unit_id, title, kind, sort_order) VALUES ('497a9db6-6eb1-5a92-bda8-8b3bb5ed4eda', '5ce0dd03-14de-52d5-8b57-6646858b4501', '{"en": "Al-Fatiha", "bn": "সূরা ফাতিহা"}', 'lesson', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('5fb6d94b-2a62-5be7-8827-8aaad9df769f', '497a9db6-6eb1-5a92-bda8-8b3bb5ed4eda', 'true_false', '{"en": "Al-Fatiha has seven ayahs.", "bn": "সূরা ফাতিহায় সাতটি আয়াত আছে।"}', '{"answer": true}', '{"en": "It is \"the seven oft-repeated (verses)\" and the Mother of the Quran.", "bn": "এটি \"বারবার পঠিত সাত আয়াত\" ও উম্মুল কুরআন।"}', 'Quran 15:87; Sahih al-Bukhari 4474', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('2a09decf-e72d-5616-9041-c7584e321c8b', '497a9db6-6eb1-5a92-bda8-8b3bb5ed4eda', 'order', '{"en": "Put the words of this ayah in order", "bn": "আয়াতের শব্দগুলো সাজান"}', '{"pieces": [{"ar": "ٱلْحَمْدُ"}, {"ar": "لِلَّهِ"}, {"ar": "رَبِّ"}, {"ar": "ٱلْعَٰلَمِينَ"}], "rtl": true}', '{"en": "\"All praise is for Allah, Lord of all the worlds.\"", "bn": "\"সকল প্রশংসা আল্লাহর, যিনি সকল জগতের রব।\""}', 'Quran 1:2', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('5a89a865-1af5-56ad-896c-bdf00f6ffab3', '497a9db6-6eb1-5a92-bda8-8b3bb5ed4eda', 'choice', '{"en": "What does \"Al-hamdu lillah\" mean?", "bn": "\"আলহামদুলিল্লাহ\" অর্থ কী?"}', '{"options": [{"en": "All praise is for Allah", "bn": "সকল প্রশংসা আল্লাহর"}, {"en": "Allah is the Greatest", "bn": "আল্লাহ সবচেয়ে বড়"}, {"en": "Glory be to Allah", "bn": "আল্লাহ পবিত্র"}, {"en": "In the name of Allah", "bn": "আল্লাহর নামে"}], "correct": 0}', '{"en": "Al-hamdu = all praise, lillah = is for Allah.", "bn": "আল-হামদু = সকল প্রশংসা, লিল্লাহ = আল্লাহর জন্য।"}', 'Quran 1:2', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('e51ffcab-13aa-5bf4-beca-5021f81e252c', '497a9db6-6eb1-5a92-bda8-8b3bb5ed4eda', 'fill', '{"en": "Complete the ayah", "bn": "আয়াতটি পূর্ণ করুন"}', '{"before": {"ar": "مَٰلِكِ يَوْمِ"}, "options": [{"ar": "ٱلدِّينِ"}, {"ar": "ٱلْعَٰلَمِينَ"}, {"ar": "ٱلْمُسْتَقِيمَ"}], "correct": 0, "rtl": true}', '{"en": "\"Master of the Day of Judgement.\"", "bn": "\"বিচার দিবসের মালিক।\""}', 'Quran 1:4', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('a5696638-6f4b-5dc3-8285-5bbb9527fbcc', '497a9db6-6eb1-5a92-bda8-8b3bb5ed4eda', 'order', '{"en": "Put the words of this ayah in order", "bn": "আয়াতের শব্দগুলো সাজান"}', '{"pieces": [{"ar": "مَٰلِكِ"}, {"ar": "يَوْمِ"}, {"ar": "ٱلدِّينِ"}], "rtl": true}', '{"en": "\"Master of the Day of Judgement.\"", "bn": "\"বিচার দিবসের মালিক।\""}', 'Quran 1:4', 5) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('069428da-2886-589c-849b-e4b489710d41', '497a9db6-6eb1-5a92-bda8-8b3bb5ed4eda', 'fill', '{"en": "Complete the ayah", "bn": "আয়াতটি পূর্ণ করুন"}', '{"before": {"ar": "ٱهْدِنَا"}, "after": {"ar": "ٱلْمُسْتَقِيمَ"}, "options": [{"ar": "ٱلصِّرَٰطَ"}, {"ar": "عَلَيْهِمْ"}, {"ar": "رَبِّ"}], "correct": 0, "rtl": true}', '{"en": "\"Guide us to the straight path.\"", "bn": "\"আমাদের সরল পথ দেখান।\""}', 'Quran 1:6', 6) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('4a72a180-8045-5ded-9049-bb35a1310d0e', '497a9db6-6eb1-5a92-bda8-8b3bb5ed4eda', 'choice', '{"en": "In \"Iyyaka na‘budu wa iyyaka nasta‘in\", what do we ask Allah for?", "bn": "\"ইয়্যাকা নাবুদু ওয়া ইয়্যাকা নাসতাইন\"-এ আমরা আল্লাহর কাছে কী চাই?"}', '{"options": [{"en": "Help", "bn": "সাহায্য"}, {"en": "Wealth", "bn": "সম্পদ"}, {"en": "Rain", "bn": "বৃষ্টি"}, {"en": "Sleep", "bn": "ঘুম"}], "correct": 0}', '{"en": "\"You alone we worship, and You alone we ask for help.\"", "bn": "\"আমরা শুধু আপনারই ইবাদত করি এবং শুধু আপনারই সাহায্য চাই।\""}', 'Quran 1:5', 7) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_lessons (id, unit_id, title, kind, sort_order) VALUES ('4fac71d1-ce22-5d6e-956f-ade2e7e55c4f', '5ce0dd03-14de-52d5-8b57-6646858b4501', '{"en": "Unit review", "bn": "ইউনিট রিভিউ"}', 'checkpoint', 5) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('c9bbea85-3d64-59c3-8db8-ed9d78a62767', '4fac71d1-ce22-5d6e-956f-ade2e7e55c4f', 'choice', '{"en": "How many fard rak‘ahs does Fajr have?", "bn": "ফজরের ফরজ কত রাকাত?"}', '{"options": [{"en": "2", "bn": "২"}, {"en": "3", "bn": "৩"}, {"en": "4", "bn": "৪"}, {"en": "1", "bn": "১"}], "correct": 0}', '{"en": "Fajr has two fard rak‘ahs.", "bn": "ফজরের ফরজ দুই রাকাত।"}', NULL, 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('baedf9a6-44da-5a93-81b0-1865e86cb39c', '4fac71d1-ce22-5d6e-956f-ade2e7e55c4f', 'choice', '{"en": "How many fard rak‘ahs does Maghrib have?", "bn": "মাগরিবের ফরজ কত রাকাত?"}', '{"options": [{"en": "2", "bn": "২"}, {"en": "3", "bn": "৩"}, {"en": "4", "bn": "৪"}, {"en": "5", "bn": "৫"}], "correct": 1}', '{"en": "Maghrib is the only fard prayer with three rak‘ahs.", "bn": "মাগরিবই একমাত্র ফরজ নামাজ যা তিন রাকাত।"}', NULL, 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('a49dae15-dc4a-5bce-98f8-f235288a94ff', '4fac71d1-ce22-5d6e-956f-ade2e7e55c4f', 'fill', '{"en": "Complete the ayah", "bn": "আয়াতটি পূর্ণ করুন"}', '{"after": {"ar": "لِلَّهِ رَبِّ ٱلْعَٰلَمِينَ"}, "options": [{"ar": "ٱلْحَمْدُ"}, {"ar": "ٱلرَّحْمَٰنِ"}, {"ar": "ٱلصِّرَٰطَ"}], "correct": 0, "rtl": true}', '{"en": "\"All praise is for Allah, Lord of all the worlds.\"", "bn": "\"সকল প্রশংসা আল্লাহর, যিনি সকল জগতের রব।\""}', 'Quran 1:2', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('f11f3b06-0397-54df-b6e2-cfcf04fc8b40', '4fac71d1-ce22-5d6e-956f-ade2e7e55c4f', 'choice', '{"en": "How many fard rak‘ahs are in Isha?", "bn": "ইশার ফরজ কত রাকাত?"}', '{"options": [{"en": "2", "bn": "২"}, {"en": "3", "bn": "৩"}, {"en": "4", "bn": "৪"}, {"en": "6", "bn": "৬"}], "correct": 2}', '{"en": "Isha has four fard rak‘ahs.", "bn": "ইশার ফরজ চার রাকাত।"}', NULL, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('0deb66c8-a648-5d68-b2ab-d9101de4f913', '4fac71d1-ce22-5d6e-956f-ade2e7e55c4f', 'true_false', '{"en": "Tayammum with clean earth is allowed when there is no water.", "bn": "পানি না থাকলে পবিত্র মাটি দিয়ে তায়াম্মুম করা যায়।"}', '{"answer": true}', '{"en": "\"…and you find no water, then seek clean earth.\"", "bn": "\"…আর পানি না পাও, তবে পবিত্র মাটি দিয়ে তায়াম্মুম করো।\""}', 'Quran 4:43', 5) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('629a907e-a4ba-5e04-9dd9-8b8a7088adad', '4fac71d1-ce22-5d6e-956f-ade2e7e55c4f', 'choice', '{"en": "What is the first pillar?", "bn": "প্রথম স্তম্ভ কোনটি?"}', '{"options": [{"en": "Salah", "bn": "নামাজ"}, {"en": "The shahadah", "bn": "শাহাদাহ (কালেমা)"}, {"en": "Zakat", "bn": "যাকাত"}, {"en": "Hajj", "bn": "হজ"}], "correct": 1}', '{"en": "Bearing witness that there is no god but Allah and that Muhammad is His Messenger.", "bn": "সাক্ষ্য দেওয়া যে আল্লাহ ছাড়া কোনো উপাস্য নেই এবং মুহাম্মাদ ﷺ তাঁর রাসুল।"}', 'Sahih al-Bukhari 8', 6) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('f7d1d84b-1865-510a-ac53-09f5bc74408b', '4fac71d1-ce22-5d6e-956f-ade2e7e55c4f', 'choice', '{"en": "How many pillars of Islam are there?", "bn": "ইসলামের স্তম্ভ কয়টি?"}', '{"options": [{"en": "3", "bn": "৩"}, {"en": "4", "bn": "৪"}, {"en": "5", "bn": "৫"}, {"en": "6", "bn": "৬"}], "correct": 2}', '{"en": "Islam is built on five: the shahadah, salah, zakat, Hajj and fasting Ramadan.", "bn": "ইসলাম পাঁচটির ওপর প্রতিষ্ঠিত: শাহাদাহ, নামাজ, যাকাত, হজ ও রমজানের রোজা।"}', 'Sahih al-Bukhari 8', 7) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('21c0ad00-bd5e-514d-b976-de4e957307f2', '4fac71d1-ce22-5d6e-956f-ade2e7e55c4f', 'true_false', '{"en": "Maghrib has four fard rak‘ahs.", "bn": "মাগরিবে চার রাকাত ফরজ।"}', '{"answer": false}', '{"en": "Maghrib has three fard rak‘ahs.", "bn": "মাগরিবে তিন রাকাত ফরজ।"}', NULL, 8) ON CONFLICT (id) DO NOTHING;
