INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('82fb7e6e-4778-5089-882a-e2aaf1e94db4', 'd91a7b59-2796-54a3-b8f7-de25c1017d35', 'choice', '{"en": "How many pillars of Islam are there?", "bn": "ইসলামের স্তম্ভ কয়টি?"}', '{"options": [{"en": "3", "bn": "৩"}, {"en": "4", "bn": "৪"}, {"en": "5", "bn": "৫"}, {"en": "6", "bn": "৬"}], "correct": 2}', '{"en": "Islam is built on five: the shahadah, salah, zakat, Hajj and fasting Ramadan.", "bn": "ইসলাম পাঁচটির ওপর প্রতিষ্ঠিত: শাহাদাহ, নামাজ, যাকাত, হজ ও রমজানের রোজা।"}', 'Sahih al-Bukhari 8', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('406d04c5-a8d0-5072-a8fd-e329f88ddd08', 'd91a7b59-2796-54a3-b8f7-de25c1017d35', 'choice', '{"en": "What is the first pillar?", "bn": "প্রথম স্তম্ভ কোনটি?"}', '{"options": [{"en": "Salah", "bn": "নামাজ"}, {"en": "The shahadah", "bn": "শাহাদাহ (কালেমা)"}, {"en": "Zakat", "bn": "যাকাত"}, {"en": "Hajj", "bn": "হজ"}], "correct": 1}', '{"en": "Bearing witness that there is no god but Allah and that Muhammad is His Messenger.", "bn": "সাক্ষ্য দেওয়া যে আল্লাহ ছাড়া কোনো উপাস্য নেই এবং মুহাম্মাদ ﷺ তাঁর রাসুল।"}', 'Sahih al-Bukhari 8', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('c68e5660-e1ca-523c-ae5b-69ee4bd47a95', 'd91a7b59-2796-54a3-b8f7-de25c1017d35', 'choice', '{"en": "How many obligatory prayers are there each day?", "bn": "প্রতিদিন কয় ওয়াক্ত নামাজ ফরজ?"}', '{"options": [{"en": "3", "bn": "৩"}, {"en": "5", "bn": "৫"}, {"en": "7", "bn": "৭"}, {"en": "2", "bn": "২"}], "correct": 1}', '{"en": "Fajr, Dhuhr, Asr, Maghrib and Isha.", "bn": "ফজর, যোহর, আসর, মাগরিব ও ইশা।"}', 'Sahih al-Bukhari 349', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('bf8cd0f4-51e6-5a7d-9d94-d2b1ac5e8530', 'd91a7b59-2796-54a3-b8f7-de25c1017d35', 'choice', '{"en": "How many fard rak‘ahs does Fajr have?", "bn": "ফজরের ফরজ কত রাকাত?"}', '{"options": [{"en": "2", "bn": "২"}, {"en": "3", "bn": "৩"}, {"en": "4", "bn": "৪"}, {"en": "1", "bn": "১"}], "correct": 0}', '{"en": "Fajr has two fard rak‘ahs.", "bn": "ফজরের ফরজ দুই রাকাত।"}', NULL, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('c4e150e5-a358-593f-ad58-cacd7c912b21', 'd91a7b59-2796-54a3-b8f7-de25c1017d35', 'choice', '{"en": "How many fard rak‘ahs does Maghrib have?", "bn": "মাগরিবের ফরজ কত রাকাত?"}', '{"options": [{"en": "2", "bn": "২"}, {"en": "3", "bn": "৩"}, {"en": "4", "bn": "৪"}, {"en": "5", "bn": "৫"}], "correct": 1}', '{"en": "Maghrib is the only fard prayer with three rak‘ahs.", "bn": "মাগরিবই একমাত্র ফরজ নামাজ যা তিন রাকাত।"}', NULL, 5) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_lessons (id, unit_id, title, kind, sort_order) VALUES ('b27a1ab1-ac98-5de8-baac-72e87a1c8453', '4eaad95e-2cf0-5d61-bb56-68a947b40488', '{"en": "Part 2", "bn": "পর্ব ২"}', 'lesson', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('b5f2b3f6-18d8-5447-b60d-5ddbb698dfdd', 'b27a1ab1-ac98-5de8-baac-72e87a1c8453', 'choice', '{"en": "What share of savings is given as zakat each lunar year?", "bn": "প্রতি চান্দ্র বছরে সঞ্চয়ের কত অংশ যাকাত দিতে হয়?"}', '{"options": [{"en": "1%", "bn": "১%"}, {"en": "2.5%", "bn": "২.৫%"}, {"en": "5%", "bn": "৫%"}, {"en": "10%", "bn": "১০%"}], "correct": 1}', '{"en": "One fortieth (2.5%) of money and trade goods above the nisab.", "bn": "নিসাবের ওপরে থাকা টাকা ও ব্যবসায়িক পণ্যের চল্লিশ ভাগের এক ভাগ (২.৫%)।"}', NULL, 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('83e181e6-337c-55a1-be1e-d0e98d34749a', 'b27a1ab1-ac98-5de8-baac-72e87a1c8453', 'choice', '{"en": "Fasting is obligatory in which month?", "bn": "কোন মাসে রোজা ফরজ?"}', '{"options": [{"en": "Sha‘ban", "bn": "শাবান"}, {"en": "Ramadan", "bn": "রমজান"}, {"en": "Shawwal", "bn": "শাওয়াল"}, {"en": "Dhul Hijjah", "bn": "জিলহজ"}], "correct": 1}', '{"en": "\"O you who believe, fasting is prescribed for you…\"", "bn": "\"হে মুমিনগণ, তোমাদের ওপর রোজা ফরজ করা হয়েছে…\""}', 'Quran 2:183–185', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('4048c683-9bea-56c5-a403-20b344103461', 'b27a1ab1-ac98-5de8-baac-72e87a1c8453', 'choice', '{"en": "For someone able, how often is Hajj obligatory?", "bn": "সামর্থ্যবানের জন্য হজ কতবার ফরজ?"}', '{"options": [{"en": "Every year", "bn": "প্রতি বছর"}, {"en": "Once in a lifetime", "bn": "জীবনে একবার"}, {"en": "Every five years", "bn": "প্রতি পাঁচ বছরে"}, {"en": "Three times", "bn": "তিনবার"}], "correct": 1}', '{"en": "The Prophet ﷺ said that had he said \"every year\", it would have become obligatory; it is once.", "bn": "নবী ﷺ বলেছেন, \"প্রতি বছর\" বললে তা ফরজ হয়ে যেত; হজ জীবনে একবার ফরজ।"}', 'Sahih Muslim 1337', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('b176aaa2-2e9f-5993-96b3-b236411efe1a', 'b27a1ab1-ac98-5de8-baac-72e87a1c8453', 'choice', '{"en": "Muslims face which direction in prayer?", "bn": "নামাজে মুসলমানরা কোন দিকে মুখ করেন?"}', '{"options": [{"en": "Jerusalem", "bn": "জেরুজালেম"}, {"en": "The Ka‘bah in Makkah", "bn": "মক্কার কাবা"}, {"en": "Madinah", "bn": "মদিনা"}, {"en": "East", "bn": "পূর্ব দিক"}], "correct": 1}', '{"en": "\"So turn your face towards al-Masjid al-Haram.\"", "bn": "\"সুতরাং আপনার মুখ মসজিদুল হারামের দিকে ফেরান।\""}', 'Quran 2:144', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('25e9e2be-d289-5fa2-8291-b81fafd65883', 'b27a1ab1-ac98-5de8-baac-72e87a1c8453', 'choice', '{"en": "Which prayer replaces Dhuhr on Friday?", "bn": "শুক্রবার যোহরের পরিবর্তে কোন নামাজ?"}', '{"options": [{"en": "Jumu‘ah", "bn": "জুমা"}, {"en": "Eid", "bn": "ঈদ"}, {"en": "Duha", "bn": "দুহা"}, {"en": "Tahajjud", "bn": "তাহাজ্জুদ"}], "correct": 0}', '{"en": "The Friday prayer, with its khutbah.", "bn": "খুতবাসহ জুমার নামাজ।"}', 'Quran 62:9', 5) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_lessons (id, unit_id, title, kind, sort_order) VALUES ('f7ae7944-2f39-5e32-8a0b-94f95853976b', '4eaad95e-2cf0-5d61-bb56-68a947b40488', '{"en": "Unit review", "bn": "ইউনিট রিভিউ"}', 'checkpoint', 3) ON CONFLICT (id) DO NOTHING;
