INSERT INTO is_learn_lessons (id, unit_id, title, kind, sort_order) VALUES ('3e87bb86-bdcb-590f-bdef-04394490e836', 'e4f7f700-ab64-5f49-9c29-4b9bad63c04a', '{"en": "Part 1", "bn": "পর্ব ১"}', 'lesson', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('3d9913a6-9ca8-5681-beb8-7c62474cdb73', '3e87bb86-bdcb-590f-bdef-04394490e836', 'choice', '{"en": "Which of these breaks wudu?", "bn": "কোনটি অজু ভঙ্গ করে?"}', '{"options": [{"en": "Eating dates", "bn": "খেজুর খাওয়া"}, {"en": "Passing wind", "bn": "বায়ু নির্গত হওয়া"}, {"en": "Reading Quran", "bn": "কুরআন পড়া"}, {"en": "Smiling", "bn": "মুচকি হাসা"}], "correct": 1}', '{"en": "The Prophet ﷺ said prayer is not accepted from one who broke wudu until he makes wudu again; passing wind breaks it.", "bn": "নবী ﷺ বলেছেন, অজু ভেঙে গেলে নতুন অজু ছাড়া নামাজ কবুল হয় না; বায়ু নির্গত হলে অজু ভাঙে।"}', 'Sahih al-Bukhari 135', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('9a8dd48c-0d98-592d-9e92-7414e1e331a1', '3e87bb86-bdcb-590f-bdef-04394490e836', 'choice', '{"en": "Purifying with clean earth when there is no water is called…?", "bn": "পানি না থাকলে পবিত্র মাটি দিয়ে পবিত্রতা অর্জনকে কী বলে?"}', '{"options": [{"en": "Ghusl", "bn": "গোসল"}, {"en": "Tayammum", "bn": "তায়াম্মুম"}, {"en": "Istinja", "bn": "ইস্তিনজা"}, {"en": "I‘tikaf", "bn": "ইতিকাফ"}], "correct": 1}', '{"en": "\"…and you find no water, then do tayammum with clean earth.\"", "bn": "\"…আর পানি না পাও, তবে পবিত্র মাটি দিয়ে তায়াম্মুম করো।\""}', 'Quran 4:43', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('ca028381-d043-54cc-b779-bdada759b593', '3e87bb86-bdcb-590f-bdef-04394490e836', 'choice', '{"en": "With what words does salah begin?", "bn": "কোন বাক্য দিয়ে নামাজ শুরু হয়?"}', '{"options": [{"en": "Bismillah", "bn": "বিসমিল্লাহ"}, {"en": "Allahu Akbar", "bn": "আল্লাহু আকবার"}, {"en": "Alhamdulillah", "bn": "আলহামদুলিল্লাহ"}, {"en": "As-salamu alaykum", "bn": "আসসালামু আলাইকুম"}], "correct": 1}', '{"en": "The opening takbir; salah ends with the salam.", "bn": "তাকবিরে তাহরিমা দিয়ে শুরু, সালাম দিয়ে শেষ।"}', 'Sunan Abi Dawud 61', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('2eeed0ab-4612-51d7-9889-bbf5498fa95f', '3e87bb86-bdcb-590f-bdef-04394490e836', 'choice', '{"en": "Which surah is recited in every rak‘ah?", "bn": "প্রতি রাকাতে কোন সূরা পড়া হয়?"}', '{"options": [{"en": "Al-Ikhlas", "bn": "আল-ইখলাস"}, {"en": "Al-Fatiha", "bn": "আল-ফাতিহা"}, {"en": "Al-Kawthar", "bn": "আল-কাওসার"}, {"en": "An-Nas", "bn": "আন-নাস"}], "correct": 1}', '{"en": "\"There is no prayer for one who does not recite al-Fatiha.\"", "bn": "\"যে সূরা ফাতিহা পড়ে না, তার নামাজ হয় না।\""}', 'Sahih al-Bukhari 756', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('8ac3b770-38c7-5c4d-9bb1-46a1ac20ce5c', '3e87bb86-bdcb-590f-bdef-04394490e836', 'choice', '{"en": "What is the call to prayer called?", "bn": "নামাজের আহ্বানকে কী বলে?"}', '{"options": [{"en": "Iqamah", "bn": "ইকামত"}, {"en": "Adhan", "bn": "আজান"}, {"en": "Khutbah", "bn": "খুতবা"}, {"en": "Takbir", "bn": "তাকবির"}], "correct": 1}', '{"en": "The adhan announces that the prayer time has come.", "bn": "আজান নামাজের সময় হয়েছে তা ঘোষণা করে।"}', NULL, 5) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_lessons (id, unit_id, title, kind, sort_order) VALUES ('2e2f6a6b-6501-5f9e-8b8a-7c1fee2ab154', 'e4f7f700-ab64-5f49-9c29-4b9bad63c04a', '{"en": "Part 2", "bn": "পর্ব ২"}', 'lesson', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('cb4a2ef8-2206-5438-b92d-147bf552b117', '2e2f6a6b-6501-5f9e-8b8a-7c1fee2ab154', 'choice', '{"en": "What is the second call, just before the prayer starts?", "bn": "নামাজ শুরুর ঠিক আগের দ্বিতীয় আহ্বানকে কী বলে?"}', '{"options": [{"en": "Iqamah", "bn": "ইকামত"}, {"en": "Adhan", "bn": "আজান"}, {"en": "Du‘a", "bn": "দোয়া"}, {"en": "Salam", "bn": "সালাম"}], "correct": 0}', '{"en": "The iqamah tells those present that the congregation is starting.", "bn": "ইকামত জানিয়ে দেয় জামাত শুরু হচ্ছে।"}', NULL, 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('2274ae46-4bf1-54b1-97c3-c2aa62bbd94a', '2e2f6a6b-6501-5f9e-8b8a-7c1fee2ab154', 'choice', '{"en": "How many fard rak‘ahs are in Dhuhr (when not travelling)?", "bn": "যোহরের ফরজ কত রাকাত (মুসাফির না হলে)?"}', '{"options": [{"en": "2", "bn": "২"}, {"en": "3", "bn": "৩"}, {"en": "4", "bn": "৪"}, {"en": "5", "bn": "৫"}], "correct": 2}', '{"en": "Dhuhr, Asr and Isha have four fard rak‘ahs each.", "bn": "যোহর, আসর ও ইশার ফরজ চার রাকাত করে।"}', NULL, 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('be6edae6-de8e-53c3-b32d-187175104266', '2e2f6a6b-6501-5f9e-8b8a-7c1fee2ab154', 'choice', '{"en": "How many fard rak‘ahs are in Isha?", "bn": "ইশার ফরজ কত রাকাত?"}', '{"options": [{"en": "2", "bn": "২"}, {"en": "3", "bn": "৩"}, {"en": "4", "bn": "৪"}, {"en": "6", "bn": "৬"}], "correct": 2}', '{"en": "Isha has four fard rak‘ahs.", "bn": "ইশার ফরজ চার রাকাত।"}', NULL, 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('b7fabd22-fd98-5fcd-a90c-d890689fa6d5', '2e2f6a6b-6501-5f9e-8b8a-7c1fee2ab154', 'choice', '{"en": "Prostrating in salah is called…?", "bn": "নামাজে সিজদা দেওয়াকে কী বলে?"}', '{"options": [{"en": "Ruku‘", "bn": "রুকু"}, {"en": "Sujud", "bn": "সিজদা"}, {"en": "Qiyam", "bn": "কিয়াম"}, {"en": "Tashahhud", "bn": "তাশাহহুদ"}], "correct": 1}', '{"en": "\"The closest a servant is to his Lord is while in sujud.\"", "bn": "\"বান্দা সিজদারত অবস্থায় তার রবের সবচেয়ে কাছে থাকে।\""}', 'Sahih Muslim 482', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('0048bdc1-9a55-5680-a33a-06b8662fd96b', '2e2f6a6b-6501-5f9e-8b8a-7c1fee2ab154', 'choice', '{"en": "How does salah end?", "bn": "নামাজ কীভাবে শেষ হয়?"}', '{"options": [{"en": "With the salam", "bn": "সালাম দিয়ে"}, {"en": "With a takbir", "bn": "তাকবির দিয়ে"}, {"en": "With Ameen", "bn": "আমিন বলে"}, {"en": "By standing up", "bn": "উঠে দাঁড়িয়ে"}], "correct": 0}', '{"en": "\"Its beginning is the takbir and its ending is the taslim (salam).\"", "bn": "\"এর শুরু তাকবির আর শেষ সালাম।\""}', 'Sunan Abi Dawud 61', 5) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_lessons (id, unit_id, title, kind, sort_order) VALUES ('387f1e37-d565-5916-8d4c-4a4e2958524b', 'e4f7f700-ab64-5f49-9c29-4b9bad63c04a', '{"en": "Unit review", "bn": "ইউনিট রিভিউ"}', 'checkpoint', 3) ON CONFLICT (id) DO NOTHING;
