INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('b7d277cb-16dc-5fcb-88e6-1c6116581688', '00815614-cbcd-51ca-9d09-a3a38a24303f', 'choice', '{"en": "How many surahs are in the Quran?", "bn": "কুরআনে কয়টি সূরা আছে?"}', '{"options": [{"en": "110", "bn": "১১০"}, {"en": "114", "bn": "১১৪"}, {"en": "120", "bn": "১২০"}, {"en": "99", "bn": "৯৯"}], "correct": 1}', '{"en": "The Quran has 114 surahs, from al-Fatiha to an-Nas.", "bn": "কুরআনে ১১৪টি সূরা আছে, আল-ফাতিহা থেকে আন-নাস পর্যন্ত।"}', NULL, 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('7ddead93-21e8-5292-b746-e591fa4970ff', '00815614-cbcd-51ca-9d09-a3a38a24303f', 'choice', '{"en": "Which surah comes first in the Quran?", "bn": "কুরআনের প্রথম সূরা কোনটি?"}', '{"options": [{"en": "Al-Baqarah", "bn": "আল-বাকারা"}, {"en": "Al-Ikhlas", "bn": "আল-ইখলাস"}, {"en": "Al-Fatiha", "bn": "আল-ফাতিহা"}, {"en": "An-Nas", "bn": "আন-নাস"}], "correct": 2}', '{"en": "Al-Fatiha, \"the Opening\", is the first surah and is recited in every rak‘ah.", "bn": "আল-ফাতিহা প্রথম সূরা, যা প্রতি রাকাতে পড়া হয়।"}', 'Quran 1', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('ea1e3283-25a7-5574-9aec-1d946b93cda4', '00815614-cbcd-51ca-9d09-a3a38a24303f', 'choice', '{"en": "Which is the longest surah?", "bn": "সবচেয়ে বড় সূরা কোনটি?"}', '{"options": [{"en": "Al-Baqarah", "bn": "আল-বাকারা"}, {"en": "Al Imran", "bn": "আলে ইমরান"}, {"en": "An-Nisa", "bn": "আন-নিসা"}, {"en": "Yasin", "bn": "ইয়াসিন"}], "correct": 0}', '{"en": "Al-Baqarah has 286 ayahs.", "bn": "আল-বাকারায় ২৮৬টি আয়াত আছে।"}', 'Quran 2', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('ba53edd5-ac61-59b0-861a-5b42e3ae349c', '00815614-cbcd-51ca-9d09-a3a38a24303f', 'choice', '{"en": "Which of these surahs has the fewest words?", "bn": "নিচের কোন সূরায় সবচেয়ে কম শব্দ?"}', '{"options": [{"en": "Al-Fatiha", "bn": "আল-ফাতিহা"}, {"en": "Al-Kawthar", "bn": "আল-কাওসার"}, {"en": "Al-Ikhlas", "bn": "আল-ইখলাস"}, {"en": "Al-Mulk", "bn": "আল-মুলক"}], "correct": 1}', '{"en": "Al-Kawthar (108) has three short ayahs, about ten words.", "bn": "আল-কাওসারে (১০৮) তিনটি ছোট আয়াত, প্রায় দশটি শব্দ।"}', 'Quran 108', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('a2278584-39de-52fd-ba4b-800c36a91f11', '00815614-cbcd-51ca-9d09-a3a38a24303f', 'choice', '{"en": "In which month did the revelation of the Quran begin?", "bn": "কোন মাসে কুরআন নাজিল শুরু হয়?"}', '{"options": [{"en": "Rajab", "bn": "রজব"}, {"en": "Sha‘ban", "bn": "শাবান"}, {"en": "Ramadan", "bn": "রমজান"}, {"en": "Muharram", "bn": "মহররম"}], "correct": 2}', '{"en": "\"The month of Ramadan, in which the Quran was revealed…\"", "bn": "\"রমজান মাস, যে মাসে কুরআন নাজিল হয়েছে…\""}', 'Quran 2:185', 5) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_lessons (id, unit_id, title, kind, sort_order) VALUES ('b869a5cc-7549-54c8-ad8f-971cf9504184', 'a359c3f5-dc6f-5fc1-9697-abaae9d21c68', '{"en": "Part 2", "bn": "পর্ব ২"}', 'lesson', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('e2b5564a-b24b-5e38-a4c1-45600b93bb2a', 'b869a5cc-7549-54c8-ad8f-971cf9504184', 'choice', '{"en": "Which surah does not begin with Bismillah?", "bn": "কোন সূরা বিসমিল্লাহ দিয়ে শুরু হয় না?"}', '{"options": [{"en": "At-Tawbah", "bn": "আত-তাওবা"}, {"en": "Al-Anfal", "bn": "আল-আনফাল"}, {"en": "Al-Kahf", "bn": "আল-কাহফ"}, {"en": "Yunus", "bn": "ইউনুস"}], "correct": 0}', '{"en": "At-Tawbah (9) is the only surah without Bismillah at its start.", "bn": "আত-তাওবা (৯) একমাত্র সূরা যার শুরুতে বিসমিল্লাহ নেই।"}', 'Quran 9', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('744be71c-cc83-572c-976c-1a89d22f356b', 'b869a5cc-7549-54c8-ad8f-971cf9504184', 'choice', '{"en": "The first words revealed came from which surah?", "bn": "প্রথম নাজিলকৃত আয়াত কোন সূরার?"}', '{"options": [{"en": "Al-Fatiha", "bn": "আল-ফাতিহা"}, {"en": "Al-Muddaththir", "bn": "আল-মুদ্দাসসির"}, {"en": "Al-‘Alaq", "bn": "আল-আলাক"}, {"en": "Al-Qadr", "bn": "আল-কদর"}], "correct": 2}', '{"en": "\"Read in the name of your Lord who created\" (al-‘Alaq 96:1–5) was revealed first, in the cave of Hira.", "bn": "\"পড়ুন আপনার রবের নামে যিনি সৃষ্টি করেছেন\" (আল-আলাক ৯৬:১–৫) প্রথম নাজিল হয়, হেরা গুহায়।"}', 'Sahih al-Bukhari 3', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('67b85d8c-2586-5230-8fab-9c23b1de1e4a', 'b869a5cc-7549-54c8-ad8f-971cf9504184', 'choice', '{"en": "Into how many juz (para) is the Quran divided?", "bn": "কুরআন কয়টি পারায় বিভক্ত?"}', '{"options": [{"en": "20", "bn": "২০"}, {"en": "30", "bn": "৩০"}, {"en": "40", "bn": "৪০"}, {"en": "60", "bn": "৬০"}], "correct": 1}', '{"en": "There are 30 juz, which is why many read one juz a day in Ramadan.", "bn": "৩০ পারা, তাই অনেকে রমজানে প্রতিদিন এক পারা পড়েন।"}', NULL, 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('fe0f69b2-fb57-5419-ab7e-0f32219075ba', 'b869a5cc-7549-54c8-ad8f-971cf9504184', 'choice', '{"en": "Which angel brought the revelation to the Prophet ﷺ?", "bn": "কোন ফেরেশতা নবী ﷺ-এর কাছে ওহি নিয়ে আসতেন?"}', '{"options": [{"en": "Mika‘il", "bn": "মিকাইল"}, {"en": "Jibril", "bn": "জিবরাইল"}, {"en": "Israfil", "bn": "ইসরাফিল"}, {"en": "Malik", "bn": "মালিক"}], "correct": 1}', '{"en": "Jibril brought the Quran down to the heart of the Prophet ﷺ.", "bn": "জিবরাইল (আ.) কুরআন নবী ﷺ-এর অন্তরে নাজিল করেছেন।"}', 'Quran 2:97', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('9d930e40-006b-538c-9fde-35f076a5c324', 'b869a5cc-7549-54c8-ad8f-971cf9504184', 'choice', '{"en": "Ayat al-Kursi is in which surah?", "bn": "আয়াতুল কুরসি কোন সূরায়?"}', '{"options": [{"en": "Al-Baqarah", "bn": "আল-বাকারা"}, {"en": "Al Imran", "bn": "আলে ইমরান"}, {"en": "Al-Ma’idah", "bn": "আল-মায়িদা"}, {"en": "Yasin", "bn": "ইয়াসিন"}], "correct": 0}', '{"en": "Ayat al-Kursi is ayah 255 of al-Baqarah.", "bn": "আয়াতুল কুরসি সূরা বাকারার ২৫৫ নম্বর আয়াত।"}', 'Quran 2:255', 5) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_lessons (id, unit_id, title, kind, sort_order) VALUES ('78e6b30a-2036-52b4-b783-2fc3b7ad3d0c', 'a359c3f5-dc6f-5fc1-9697-abaae9d21c68', '{"en": "Unit review", "bn": "ইউনিট রিভিউ"}', 'checkpoint', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('183c0cc1-b25e-5c15-b429-4da8ea6de077', '78e6b30a-2036-52b4-b783-2fc3b7ad3d0c', 'choice', '{"en": "Which surah comes first in the Quran?", "bn": "কুরআনের প্রথম সূরা কোনটি?"}', '{"options": [{"en": "Al-Baqarah", "bn": "আল-বাকারা"}, {"en": "Al-Ikhlas", "bn": "আল-ইখলাস"}, {"en": "Al-Fatiha", "bn": "আল-ফাতিহা"}, {"en": "An-Nas", "bn": "আন-নাস"}], "correct": 2}', '{"en": "Al-Fatiha, \"the Opening\", is the first surah and is recited in every rak‘ah.", "bn": "আল-ফাতিহা প্রথম সূরা, যা প্রতি রাকাতে পড়া হয়।"}', 'Quran 1', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('6a5a3c84-addc-51af-b10b-2e3a63005008', '78e6b30a-2036-52b4-b783-2fc3b7ad3d0c', 'choice', '{"en": "Which of these surahs has the fewest words?", "bn": "নিচের কোন সূরায় সবচেয়ে কম শব্দ?"}', '{"options": [{"en": "Al-Fatiha", "bn": "আল-ফাতিহা"}, {"en": "Al-Kawthar", "bn": "আল-কাওসার"}, {"en": "Al-Ikhlas", "bn": "আল-ইখলাস"}, {"en": "Al-Mulk", "bn": "আল-মুলক"}], "correct": 1}', '{"en": "Al-Kawthar (108) has three short ayahs, about ten words.", "bn": "আল-কাওসারে (১০৮) তিনটি ছোট আয়াত, প্রায় দশটি শব্দ।"}', 'Quran 108', 2) ON CONFLICT (id) DO NOTHING;
