INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('879df92a-97df-502b-ab73-5531a79c0819', '78e6b30a-2036-52b4-b783-2fc3b7ad3d0c', 'choice', '{"en": "Into how many juz (para) is the Quran divided?", "bn": "কুরআন কয়টি পারায় বিভক্ত?"}', '{"options": [{"en": "20", "bn": "২০"}, {"en": "30", "bn": "৩০"}, {"en": "40", "bn": "৪০"}, {"en": "60", "bn": "৬০"}], "correct": 1}', '{"en": "There are 30 juz, which is why many read one juz a day in Ramadan.", "bn": "৩০ পারা, তাই অনেকে রমজানে প্রতিদিন এক পারা পড়েন।"}', NULL, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('76e6c3f3-9d9d-57fa-b37b-33e5b2cfb311', '78e6b30a-2036-52b4-b783-2fc3b7ad3d0c', 'choice', '{"en": "Ayat al-Kursi is in which surah?", "bn": "আয়াতুল কুরসি কোন সূরায়?"}', '{"options": [{"en": "Al-Baqarah", "bn": "আল-বাকারা"}, {"en": "Al Imran", "bn": "আলে ইমরান"}, {"en": "Al-Ma’idah", "bn": "আল-মায়িদা"}, {"en": "Yasin", "bn": "ইয়াসিন"}], "correct": 0}', '{"en": "Ayat al-Kursi is ayah 255 of al-Baqarah.", "bn": "আয়াতুল কুরসি সূরা বাকারার ২৫৫ নম্বর আয়াত।"}', 'Quran 2:255', 5) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('b687b0fb-70d0-5669-b43f-b9e0f56dab09', '78e6b30a-2036-52b4-b783-2fc3b7ad3d0c', 'choice', '{"en": "How many surahs are in the Quran?", "bn": "কুরআনে কয়টি সূরা আছে?"}', '{"options": [{"en": "110", "bn": "১১০"}, {"en": "114", "bn": "১১৪"}, {"en": "120", "bn": "১২০"}, {"en": "99", "bn": "৯৯"}], "correct": 1}', '{"en": "The Quran has 114 surahs, from al-Fatiha to an-Nas.", "bn": "কুরআনে ১১৪টি সূরা আছে, আল-ফাতিহা থেকে আন-নাস পর্যন্ত।"}', NULL, 6) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_units (id, title, description, color, icon, review_status, sort_order, section_id) VALUES ('6a910218-3be9-54ce-9a2b-156d31b567ff', '{"en": "How the Quran is arranged", "bn": "কুরআনের বিন্যাস"}', '{}', '#8c7ae6', 'book-open', 'in_review', 2, '1258ec1a-d818-5934-870a-a1d8fe595730') ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_lessons (id, unit_id, title, kind, sort_order) VALUES ('7a628e01-83b8-5d15-909a-51d0b9b5d31e', '6a910218-3be9-54ce-9a2b-156d31b567ff', '{"en": "Part 1", "bn": "পর্ব ১"}', 'lesson', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('60639331-b757-53f3-a31a-7b9af7b75bd5', '7a628e01-83b8-5d15-909a-51d0b9b5d31e', 'choice', '{"en": "How many ayahs does the Quran have in the common (Kufan) count?", "bn": "প্রচলিত (কুফি) গণনায় কুরআনে কতটি আয়াত?"}', '{"options": [{"en": "6,236", "bn": "৬,২৩৬"}, {"en": "6,666", "bn": "৬,৬৬৬"}, {"en": "5,000", "bn": "৫,০০০"}, {"en": "7,000", "bn": "৭,০০০"}], "correct": 0}', '{"en": "6,236 in the Kufan count used in most printed mushafs (Hafs).", "bn": "বেশিরভাগ মুদ্রিত মুসহাফে (হাফস) ব্যবহৃত কুফি গণনায় ৬,২৩৬।"}', NULL, 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('3b720c91-7eb4-5f00-b3fa-5737d5e7feb0', '7a628e01-83b8-5d15-909a-51d0b9b5d31e', 'choice', '{"en": "Under which caliph was the Quran first gathered into one book?", "bn": "কোন খলিফার সময়ে কুরআন প্রথম এক গ্রন্থে সংকলিত হয়?"}', '{"options": [{"en": "Abu Bakr", "bn": "আবু বকর"}, {"en": "‘Ali", "bn": "আলী"}, {"en": "Mu‘awiyah", "bn": "মুয়াবিয়া"}, {"en": "‘Umar ibn ‘Abd al-‘Aziz", "bn": "উমর ইবনে আবদুল আজিজ"}], "correct": 0}', '{"en": "After many reciters were martyred at Yamamah, ‘Umar urged Abu Bakr to gather it.", "bn": "ইয়ামামায় বহু কারি শহিদ হলে উমর (রা.) আবু বকর (রা.)-কে সংকলনের পরামর্শ দেন।"}', 'Sahih al-Bukhari 4986', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('085aafd3-3c85-5779-aebf-15858a34b5f6', '7a628e01-83b8-5d15-909a-51d0b9b5d31e', 'choice', '{"en": "Which scribe of revelation was given the task of gathering it?", "bn": "ওহির কোন লেখককে সংকলনের দায়িত্ব দেওয়া হয়?"}', '{"options": [{"en": "Zayd ibn Thabit", "bn": "যায়েদ ইবনে সাবিত"}, {"en": "Abu Hurayrah", "bn": "আবু হুরায়রা"}, {"en": "Bilal", "bn": "বিলাল"}, {"en": "Salman", "bn": "সালমান"}], "correct": 0}', '{"en": "Zayd ibn Thabit, a young, trusted scribe of the Prophet ﷺ.", "bn": "যায়েদ ইবনে সাবিত (রা.), নবীজির ﷺ তরুণ ও বিশ্বস্ত লেখক।"}', 'Sahih al-Bukhari 4986', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('4ef386d7-bbde-5bfd-b812-9495bdeb6eb8', '7a628e01-83b8-5d15-909a-51d0b9b5d31e', 'choice', '{"en": "Which surah is called \"Umm al-Kitab\" (the Mother of the Book)?", "bn": "কোন সূরাকে \"উম্মুল কিতাব\" বলা হয়?"}', '{"options": [{"en": "Al-Fatiha", "bn": "আল-ফাতিহা"}, {"en": "Al-Baqarah", "bn": "আল-বাকারা"}, {"en": "Al-Ikhlas", "bn": "আল-ইখলাস"}, {"en": "Ya-Sin", "bn": "ইয়াসিন"}], "correct": 0}', '{"en": "Al-Fatiha, the seven oft-repeated ayahs.", "bn": "আল-ফাতিহা, বারবার পঠিত সাত আয়াত।"}', 'Sahih al-Bukhari 4704', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('f7099200-ed2a-5320-b871-4b0f3b883e79', '7a628e01-83b8-5d15-909a-51d0b9b5d31e', 'choice', '{"en": "How many surahs begin with \"Alif Lam Mim\"?", "bn": "কয়টি সূরা \"আলিফ লাম মিম\" দিয়ে শুরু?"}', '{"options": [{"en": "3", "bn": "৩"}, {"en": "6", "bn": "৬"}, {"en": "9", "bn": "৯"}, {"en": "12", "bn": "১২"}], "correct": 1}', '{"en": "Al-Baqarah, Al Imran, al-‘Ankabut, ar-Rum, Luqman and as-Sajdah.", "bn": "আল-বাকারা, আলে ইমরান, আল-আনকাবুত, আর-রুম, লুকমান ও আস-সাজদা।"}', NULL, 5) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_lessons (id, unit_id, title, kind, sort_order) VALUES ('bb6c790a-c73a-524b-bc4d-c6511259ea67', '6a910218-3be9-54ce-9a2b-156d31b567ff', '{"en": "Part 2", "bn": "পর্ব ২"}', 'lesson', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('8b33af36-509a-55b0-8ec4-1ddcb012a763', 'bb6c790a-c73a-524b-bc4d-c6511259ea67', 'choice', '{"en": "A \"hizb\" is how much of the Quran?", "bn": "\"হিজব\" কুরআনের কতটুকু?"}', '{"options": [{"en": "Half a juz", "bn": "অর্ধেক পারা"}, {"en": "One surah", "bn": "এক সূরা"}, {"en": "Ten ayahs", "bn": "দশ আয়াত"}, {"en": "Two juz", "bn": "দুই পারা"}], "correct": 0}', '{"en": "The Quran has 30 juz and 60 hizb.", "bn": "কুরআনে ৩০ পারা ও ৬০ হিজব।"}', NULL, 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('2d7b30a8-9ebf-53ea-b6b6-c7bd2dd7eff2', 'bb6c790a-c73a-524b-bc4d-c6511259ea67', 'choice', '{"en": "About how many years did the revelation of the Quran take?", "bn": "কুরআন নাজিল হতে প্রায় কত বছর লেগেছিল?"}', '{"options": [{"en": "5", "bn": "৫"}, {"en": "10", "bn": "১০"}, {"en": "23", "bn": "২৩"}, {"en": "40", "bn": "৪০"}], "correct": 2}', '{"en": "From age forty until the Prophet’s ﷺ death: about 23 years, in parts.", "bn": "চল্লিশ বছর বয়স থেকে ইন্তেকাল পর্যন্ত, প্রায় ২৩ বছর ধরে অল্প অল্প করে।"}', 'Quran 17:106', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('d1ab2544-5b11-5773-bbe1-bf0596bacaa3', 'bb6c790a-c73a-524b-bc4d-c6511259ea67', 'choice', '{"en": "Which surah begins with the letters \"Ta Ha\"?", "bn": "কোন সূরা \"তা-হা\" অক্ষর দিয়ে শুরু?"}', '{"options": [{"en": "Ta-Ha", "bn": "তা-হা"}, {"en": "Ya-Sin", "bn": "ইয়াসিন"}, {"en": "Sad", "bn": "সোয়াদ"}, {"en": "Qaf", "bn": "কাফ"}], "correct": 0}', '{"en": "Surah 20 is named after its opening letters.", "bn": "সূরা ২০-এর নাম এর শুরুর অক্ষর থেকে।"}', 'Quran 20:1', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('8dfdfc72-8354-5e40-965d-1a73a2207b79', 'bb6c790a-c73a-524b-bc4d-c6511259ea67', 'choice', '{"en": "Which surah is named after the Prophet Muhammad ﷺ?", "bn": "কোন সূরার নাম নবী মুহাম্মাদ ﷺ-এর নামে?"}', '{"options": [{"en": "Muhammad", "bn": "মুহাম্মাদ"}, {"en": "Al-Ahzab", "bn": "আল-আহযাব"}, {"en": "Al-Fath", "bn": "আল-ফাতহ"}, {"en": "Al-Hujurat", "bn": "আল-হুজুরাত"}], "correct": 0}', '{"en": "Surah 47, Muhammad.", "bn": "সূরা ৪৭, মুহাম্মাদ।"}', 'Quran 47:2', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('895b9f32-34b3-5109-be79-3d74af09ae2d', 'bb6c790a-c73a-524b-bc4d-c6511259ea67', 'choice', '{"en": "Which surah opens the second half of the Quran (juz 16 begins inside it)?", "bn": "কোন সূরার ভেতরে ১৬তম পারা শুরু, যা কুরআনের দ্বিতীয় অর্ধেক?"}', '{"options": [{"en": "Al-Kahf", "bn": "আল-কাহফ"}, {"en": "Al-Baqarah", "bn": "আল-বাকারা"}, {"en": "Ya-Sin", "bn": "ইয়াসিন"}, {"en": "Al-Mulk", "bn": "আল-মুলক"}], "correct": 0}', '{"en": "Juz 16 starts at al-Kahf 18:75.", "bn": "১৬তম পারা শুরু আল-কাহফ ১৮:৭৫ থেকে।"}', NULL, 5) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_lessons (id, unit_id, title, kind, sort_order) VALUES ('adcbb4c1-b90b-5241-bf7c-f4ab269a289b', '6a910218-3be9-54ce-9a2b-156d31b567ff', '{"en": "Unit review", "bn": "ইউনিট রিভিউ"}', 'checkpoint', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('d6b6d56a-9028-5103-b8e5-6a6d2a674598', 'adcbb4c1-b90b-5241-bf7c-f4ab269a289b', 'choice', '{"en": "Under which caliph was the Quran first gathered into one book?", "bn": "কোন খলিফার সময়ে কুরআন প্রথম এক গ্রন্থে সংকলিত হয়?"}', '{"options": [{"en": "Abu Bakr", "bn": "আবু বকর"}, {"en": "‘Ali", "bn": "আলী"}, {"en": "Mu‘awiyah", "bn": "মুয়াবিয়া"}, {"en": "‘Umar ibn ‘Abd al-‘Aziz", "bn": "উমর ইবনে আবদুল আজিজ"}], "correct": 0}', '{"en": "After many reciters were martyred at Yamamah, ‘Umar urged Abu Bakr to gather it.", "bn": "ইয়ামামায় বহু কারি শহিদ হলে উমর (রা.) আবু বকর (রা.)-কে সংকলনের পরামর্শ দেন।"}', 'Sahih al-Bukhari 4986', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('03885cae-167a-555c-9649-a6eeba74c5c4', 'adcbb4c1-b90b-5241-bf7c-f4ab269a289b', 'choice', '{"en": "Which surah is called \"Umm al-Kitab\" (the Mother of the Book)?", "bn": "কোন সূরাকে \"উম্মুল কিতাব\" বলা হয়?"}', '{"options": [{"en": "Al-Fatiha", "bn": "আল-ফাতিহা"}, {"en": "Al-Baqarah", "bn": "আল-বাকারা"}, {"en": "Al-Ikhlas", "bn": "আল-ইখলাস"}, {"en": "Ya-Sin", "bn": "ইয়াসিন"}], "correct": 0}', '{"en": "Al-Fatiha, the seven oft-repeated ayahs.", "bn": "আল-ফাতিহা, বারবার পঠিত সাত আয়াত।"}', 'Sahih al-Bukhari 4704', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('88a6ff35-1a98-50ea-80d9-25668470a58b', 'adcbb4c1-b90b-5241-bf7c-f4ab269a289b', 'choice', '{"en": "A \"hizb\" is how much of the Quran?", "bn": "\"হিজব\" কুরআনের কতটুকু?"}', '{"options": [{"en": "Half a juz", "bn": "অর্ধেক পারা"}, {"en": "One surah", "bn": "এক সূরা"}, {"en": "Ten ayahs", "bn": "দশ আয়াত"}, {"en": "Two juz", "bn": "দুই পারা"}], "correct": 0}', '{"en": "The Quran has 30 juz and 60 hizb.", "bn": "কুরআনে ৩০ পারা ও ৬০ হিজব।"}', NULL, 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('6f3e2b8c-08c3-53cb-87c6-4fa3130a0fab', 'adcbb4c1-b90b-5241-bf7c-f4ab269a289b', 'choice', '{"en": "Which surah begins with the letters \"Ta Ha\"?", "bn": "কোন সূরা \"তা-হা\" অক্ষর দিয়ে শুরু?"}', '{"options": [{"en": "Ta-Ha", "bn": "তা-হা"}, {"en": "Ya-Sin", "bn": "ইয়াসিন"}, {"en": "Sad", "bn": "সোয়াদ"}, {"en": "Qaf", "bn": "কাফ"}], "correct": 0}', '{"en": "Surah 20 is named after its opening letters.", "bn": "সূরা ২০-এর নাম এর শুরুর অক্ষর থেকে।"}', 'Quran 20:1', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('fcad01e2-d1ee-5da1-ab27-9d1a5035a26e', 'adcbb4c1-b90b-5241-bf7c-f4ab269a289b', 'choice', '{"en": "Which surah opens the second half of the Quran (juz 16 begins inside it)?", "bn": "কোন সূরার ভেতরে ১৬তম পারা শুরু, যা কুরআনের দ্বিতীয় অর্ধেক?"}', '{"options": [{"en": "Al-Kahf", "bn": "আল-কাহফ"}, {"en": "Al-Baqarah", "bn": "আল-বাকারা"}, {"en": "Ya-Sin", "bn": "ইয়াসিন"}, {"en": "Al-Mulk", "bn": "আল-মুলক"}], "correct": 0}', '{"en": "Juz 16 starts at al-Kahf 18:75.", "bn": "১৬তম পারা শুরু আল-কাহফ ১৮:৭৫ থেকে।"}', NULL, 5) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('77d35d86-8b01-5ea1-bb8d-648dd77b2fb5', 'adcbb4c1-b90b-5241-bf7c-f4ab269a289b', 'choice', '{"en": "How many ayahs does the Quran have in the common (Kufan) count?", "bn": "প্রচলিত (কুফি) গণনায় কুরআনে কতটি আয়াত?"}', '{"options": [{"en": "6,236", "bn": "৬,২৩৬"}, {"en": "6,666", "bn": "৬,৬৬৬"}, {"en": "5,000", "bn": "৫,০০০"}, {"en": "7,000", "bn": "৭,০০০"}], "correct": 0}', '{"en": "6,236 in the Kufan count used in most printed mushafs (Hafs).", "bn": "বেশিরভাগ মুদ্রিত মুসহাফে (হাফস) ব্যবহৃত কুফি গণনায় ৬,২৩৬।"}', NULL, 6) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_units (id, title, description, color, icon, review_status, sort_order, section_id) VALUES ('d95e8ee1-cd64-58d6-a337-d49706ac7024', '{"en": "Surah facts", "bn": "সূরা সম্পর্কিত তথ্য"}', '{}', '#8c7ae6', 'book-open', 'in_review', 3, '1258ec1a-d818-5934-870a-a1d8fe595730') ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_lessons (id, unit_id, title, kind, sort_order) VALUES ('a30d3efc-afaf-502b-9757-c8e7f4d43e10', 'd95e8ee1-cd64-58d6-a337-d49706ac7024', '{"en": "Part 1", "bn": "পর্ব ১"}', 'lesson', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('5039a295-68e6-51db-860c-a7118b40a791', 'a30d3efc-afaf-502b-9757-c8e7f4d43e10', 'choice', '{"en": "Which surah is named after a metal?", "bn": "কোন সূরার নাম একটি ধাতুর নামে?"}', '{"options": [{"en": "Al-Hadid", "bn": "আল-হাদিদ"}, {"en": "Adh-Dhahab", "bn": "আয-যাহাব"}, {"en": "An-Nahl", "bn": "আন-নাহল"}, {"en": "Al-Kahf", "bn": "আল-কাহফ"}], "correct": 0}', '{"en": "Al-Hadid means \"Iron\" (surah 57).", "bn": "আল-হাদিদ অর্থ \"লোহা\" (সূরা ৫৭)।"}', 'Quran 57:25', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('dfc8df33-9628-5eeb-a77c-5c54ae045365', 'a30d3efc-afaf-502b-9757-c8e7f4d43e10', 'choice', '{"en": "Which surah has Bismillah twice?", "bn": "কোন সূরায় বিসমিল্লাহ দুইবার আছে?"}', '{"options": [{"en": "An-Naml", "bn": "আন-নামল"}, {"en": "At-Tawbah", "bn": "আত-তাওবা"}, {"en": "Al-Fatiha", "bn": "আল-ফাতিহা"}, {"en": "Ya-Sin", "bn": "ইয়াসিন"}], "correct": 0}', '{"en": "At its start and inside Sulayman’s letter: \"…it is in the name of Allah, the Most Merciful\".", "bn": "শুরুতে এবং সুলাইমানের চিঠিতে: \"…তা পরম দয়াময় আল্লাহর নামে\"।"}', 'Quran 27:30', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('6da4ffb0-7018-5b22-8feb-eb2a4c4edfed', 'a30d3efc-afaf-502b-9757-c8e7f4d43e10', 'choice', '{"en": "Which surah is equal to a third of the Quran?", "bn": "কোন সূরা কুরআনের এক-তৃতীয়াংশের সমান?"}', '{"options": [{"en": "Al-Ikhlas", "bn": "আল-ইখলাস"}, {"en": "Al-Fatiha", "bn": "আল-ফাতিহা"}, {"en": "Al-Mulk", "bn": "আল-মুলক"}, {"en": "An-Nas", "bn": "আন-নাস"}], "correct": 0}', '{"en": "\"By Him in whose hand my soul is, it equals a third of the Quran.\"", "bn": "\"যাঁর হাতে আমার প্রাণ, তাঁর কসম, এটি কুরআনের এক-তৃতীয়াংশের সমান।\""}', 'Sahih al-Bukhari 5013', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('c2c61c0d-116c-544d-9c57-5471cc0ba058', 'a30d3efc-afaf-502b-9757-c8e7f4d43e10', 'choice', '{"en": "Which surah is named after the bee?", "bn": "কোন সূরার নাম মৌমাছির নামে?"}', '{"options": [{"en": "An-Naml", "bn": "আন-নামল"}, {"en": "An-Nahl", "bn": "আন-নাহল"}, {"en": "Al-‘Ankabut", "bn": "আল-আনকাবুত"}, {"en": "Al-Fil", "bn": "আল-ফিল"}], "correct": 1}', '{"en": "An-Nahl (16): \"And your Lord inspired the bee…\"", "bn": "আন-নাহল (১৬): \"আর তোমার রব মৌমাছিকে ইলহাম করলেন…\""}', 'Quran 16:68', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('ef053bda-c2b6-5d71-a9b1-0d160611272a', 'a30d3efc-afaf-502b-9757-c8e7f4d43e10', 'choice', '{"en": "Which surah is named after the spider?", "bn": "কোন সূরার নাম মাকড়সার নামে?"}', '{"options": [{"en": "Al-‘Ankabut", "bn": "আল-আনকাবুত"}, {"en": "An-Naml", "bn": "আন-নামল"}, {"en": "Al-Baqarah", "bn": "আল-বাকারা"}, {"en": "Al-Qalam", "bn": "আল-কলম"}], "correct": 0}', '{"en": "Al-‘Ankabut (29): \"…the weakest of houses is the spider’s house.\"", "bn": "আল-আনকাবুত (২৯): \"…সবচেয়ে দুর্বল ঘর মাকড়সার ঘর।\""}', 'Quran 29:41', 5) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_lessons (id, unit_id, title, kind, sort_order) VALUES ('fdadfd9f-ef06-5ce5-bfb5-9a46723d1a23', 'd95e8ee1-cd64-58d6-a337-d49706ac7024', '{"en": "Part 2", "bn": "পর্ব ২"}', 'lesson', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('a6868e8e-6ff5-5343-9eee-8446e5127b4d', 'fdadfd9f-ef06-5ce5-bfb5-9a46723d1a23', 'choice', '{"en": "Surah number 36 is…?", "bn": "৩৬ নম্বর সূরা কোনটি?"}', '{"options": [{"en": "Ya-Sin", "bn": "ইয়াসিন"}, {"en": "Ar-Rahman", "bn": "আর-রহমান"}, {"en": "Al-Waqi‘ah", "bn": "আল-ওয়াকিয়া"}, {"en": "Al-Mulk", "bn": "আল-মুলক"}], "correct": 0}', '{"en": "Ya-Sin is surah 36.", "bn": "ইয়াসিন ৩৬ নম্বর সূরা।"}', 'Quran 36', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('d4e1921c-9a3d-5045-9590-08499694bdc1', 'fdadfd9f-ef06-5ce5-bfb5-9a46723d1a23', 'choice', '{"en": "The longest ayah of the Quran is about…?", "bn": "কুরআনের দীর্ঘতম আয়াত কী নিয়ে?"}', '{"options": [{"en": "Writing down debts", "bn": "ঋণ লিখে রাখা"}, {"en": "Fasting", "bn": "রোজা"}, {"en": "Hajj", "bn": "হজ"}, {"en": "Inheritance", "bn": "উত্তরাধিকার"}], "correct": 0}', '{"en": "Al-Baqarah 2:282, the ayah of debt.", "bn": "আল-বাকারা ২:২৮২, ঋণের আয়াত।"}', 'Quran 2:282', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('2fc04cd7-e12a-5c91-bc36-74f8ba077525', 'fdadfd9f-ef06-5ce5-bfb5-9a46723d1a23', 'choice', '{"en": "Which surah is named after Friday?", "bn": "কোন সূরার নাম জুমার নামে?"}', '{"options": [{"en": "Al-Jumu‘ah", "bn": "আল-জুমুআ"}, {"en": "As-Sabt", "bn": "আস-সাবত"}, {"en": "Al-Ahzab", "bn": "আল-আহযাব"}, {"en": "Al-Fajr", "bn": "আল-ফাজর"}], "correct": 0}', '{"en": "Al-Jumu‘ah (62) calls the believers to the Friday prayer.", "bn": "আল-জুমুআ (৬২) মুমিনদের জুমার নামাজে আহ্বান করে।"}', 'Quran 62:9', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('360a4c38-565e-5a7e-b930-0a88b11f0836', 'fdadfd9f-ef06-5ce5-bfb5-9a46723d1a23', 'choice', '{"en": "Which surah repeats \"Which of the favours of your Lord will you deny?\"", "bn": "কোন সূরায় \"তোমরা তোমাদের রবের কোন কোন নিয়ামত অস্বীকার করবে?\" বারবার এসেছে?"}', '{"options": [{"en": "Ar-Rahman", "bn": "আর-রহমান"}, {"en": "Al-Mulk", "bn": "আল-মুলক"}, {"en": "Al-Insan", "bn": "আল-ইনসান"}, {"en": "Al-Waqi‘ah", "bn": "আল-ওয়াকিয়া"}], "correct": 0}', '{"en": "Ar-Rahman (55) repeats it 31 times.", "bn": "আর-রহমান (৫৫) সূরায় এটি ৩১ বার এসেছে।"}', 'Quran 55:13', 4) ON CONFLICT (id) DO NOTHING;
