INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('567bd820-98ec-5b37-a3fd-cb7f4267327d', '5ac819da-e472-57d1-9b38-2f0f93b93e18', 'choice', '{"en": "Surah al-‘Asr swears by…?", "bn": "সূরা আল-আসর কীসের কসম খায়?"}', '{"options": [{"en": "Time", "bn": "সময়ের"}, {"en": "The sun", "bn": "সূর্যের"}, {"en": "The fig", "bn": "ডুমুরের"}, {"en": "The night", "bn": "রাতের"}], "correct": 0}', '{"en": "\"By time, indeed mankind is in loss, except…\"", "bn": "\"সময়ের কসম, নিশ্চয়ই মানুষ ক্ষতিতে আছে, তবে…\""}', 'Quran 103:1–3', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('9c1f7ef4-2efc-5bd7-8519-9748a79dcb0f', '5ac819da-e472-57d1-9b38-2f0f93b93e18', 'choice', '{"en": "In al-Kawthar, Allah says He has given the Prophet ﷺ…?", "bn": "আল-কাওসারে আল্লাহ বলেন তিনি নবীজিকে ﷺ দিয়েছেন…?"}', '{"options": [{"en": "Al-Kawthar", "bn": "আল-কাওসার"}, {"en": "A kingdom", "bn": "রাজত্ব"}, {"en": "Gold", "bn": "স্বর্ণ"}, {"en": "Many sons", "bn": "অনেক পুত্র"}], "correct": 0}', '{"en": "Al-Kawthar, a river in Paradise with abundant good.", "bn": "আল-কাওসার, জান্নাতের এক নহর ও প্রভূত কল্যাণ।"}', 'Sahih Muslim 400', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('4914b132-f7a5-5748-a0c7-63ada5487043', '5ac819da-e472-57d1-9b38-2f0f93b93e18', 'choice', '{"en": "Al-Ikhlas: Allah neither begets nor…?", "bn": "আল-ইখলাস: আল্লাহ কাউকে জন্ম দেননি এবং…?"}', '{"options": [{"en": "Is begotten", "bn": "জন্ম নেননি"}, {"en": "Sleeps", "bn": "ঘুমান"}, {"en": "Speaks", "bn": "কথা বলেন"}, {"en": "Forgives", "bn": "ক্ষমা করেন"}], "correct": 0}', '{"en": "\"He neither begets nor is born, nor is there any equivalent to Him.\"", "bn": "\"তিনি জন্ম দেননি, জন্ম নেননি, তাঁর সমতুল্য কেউ নেই।\""}', 'Quran 112:3–4', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('bd3ab7ca-a2ee-58df-b64a-12b3faaf03f3', '5ac819da-e472-57d1-9b38-2f0f93b93e18', 'choice', '{"en": "Al-Falaq seeks refuge with the Lord of…?", "bn": "আল-ফালাক কার রবের কাছে আশ্রয় চায়?"}', '{"options": [{"en": "Daybreak", "bn": "প্রভাতের"}, {"en": "Mankind", "bn": "মানুষের"}, {"en": "The Throne", "bn": "আরশের"}, {"en": "The worlds", "bn": "জগৎসমূহের"}], "correct": 0}', '{"en": "\"Say: I seek refuge in the Lord of daybreak.\"", "bn": "\"বলুন: আমি প্রভাতের রবের আশ্রয় চাই।\""}', 'Quran 113:1', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('06a11e1c-7577-5a6e-b2cb-a600ce111b38', '5ac819da-e472-57d1-9b38-2f0f93b93e18', 'choice', '{"en": "An-Nas seeks refuge from the evil of…?", "bn": "আন-নাস কার অনিষ্ট থেকে আশ্রয় চায়?"}', '{"options": [{"en": "The retreating whisperer", "bn": "আত্মগোপনকারী কুমন্ত্রণাদাতার"}, {"en": "Wild animals", "bn": "বন্য প্রাণীর"}, {"en": "Storms", "bn": "ঝড়ের"}, {"en": "Enemies’ swords", "bn": "শত্রুর তরবারির"}], "correct": 0}', '{"en": "\"…from the evil of the whisperer who withdraws.\"", "bn": "\"…আত্মগোপনকারী কুমন্ত্রণাদাতার অনিষ্ট থেকে।\""}', 'Quran 114:4', 5) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_lessons (id, unit_id, title, kind, sort_order) VALUES ('9d7d50a6-4629-5db7-a2d4-1a59ee72d544', '7daee49e-19b3-53be-8bcb-411b11c7fad4', '{"en": "Part 2", "bn": "পর্ব ২"}', 'lesson', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('4cbc2793-00e7-5e05-898a-901ee3699784', '9d7d50a6-4629-5db7-a2d4-1a59ee72d544', 'choice', '{"en": "An-Nasr: \"When the help of Allah comes and…\"", "bn": "আন-নাসর: \"যখন আল্লাহর সাহায্য আসবে এবং…\""}', '{"options": [{"en": "…the victory", "bn": "…বিজয়"}, {"en": "…the rain", "bn": "…বৃষ্টি"}, {"en": "…the night", "bn": "…রাত"}, {"en": "…the angels", "bn": "…ফেরেশতা"}], "correct": 0}', '{"en": "\"…and you see people entering Allah’s religion in crowds.\"", "bn": "\"…আর তুমি দেখবে মানুষ দলে দলে আল্লাহর দ্বীনে প্রবেশ করছে।\""}', 'Quran 110:1–2', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('03c49f77-7ed5-564b-8ec5-7dfc85292cf5', '9d7d50a6-4629-5db7-a2d4-1a59ee72d544', 'choice', '{"en": "Surah al-Masad is about whom?", "bn": "সূরা আল-মাসাদ কার সম্পর্কে?"}', '{"options": [{"en": "Abu Lahab", "bn": "আবু লাহাব"}, {"en": "Pharaoh", "bn": "ফেরাউন"}, {"en": "Qarun", "bn": "কারুন"}, {"en": "Abraha", "bn": "আবরাহা"}], "correct": 0}', '{"en": "Abu Lahab and his wife, enemies of the Prophet ﷺ.", "bn": "আবু লাহাব ও তার স্ত্রী, নবীজির ﷺ শত্রু।"}', 'Quran 111', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('ec328262-4080-56c2-aa29-7b84fa2bf0e7', '9d7d50a6-4629-5db7-a2d4-1a59ee72d544', 'choice', '{"en": "Al-Ma‘un warns those who neglect prayer and…?", "bn": "আল-মাউন সতর্ক করে যারা নামাজে উদাসীন এবং…?"}', '{"options": [{"en": "Refuse small kindnesses", "bn": "ছোটখাটো সাহায্যও করে না"}, {"en": "Travel far", "bn": "দূরে সফর করে"}, {"en": "Sleep early", "bn": "তাড়াতাড়ি ঘুমায়"}, {"en": "Eat dates", "bn": "খেজুর খায়"}], "correct": 0}', '{"en": "\"…and refuse (to give even) small assistance.\"", "bn": "\"…এবং ছোটখাটো জিনিস দিতেও নিষেধ করে।\""}', 'Quran 107:4–7', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('2f8f7e69-9fc3-5a0c-8378-8a9bd6ffa8d9', '9d7d50a6-4629-5db7-a2d4-1a59ee72d544', 'choice', '{"en": "Surah Quraysh mentions their journeys of…?", "bn": "সূরা কুরাইশে তাদের কোন সফরের উল্লেখ আছে?"}', '{"options": [{"en": "Winter and summer", "bn": "শীত ও গ্রীষ্মের"}, {"en": "Spring and autumn", "bn": "বসন্ত ও শরতের"}, {"en": "Day and night", "bn": "দিন ও রাতের"}, {"en": "Hajj and Umrah", "bn": "হজ ও উমরার"}], "correct": 0}', '{"en": "Their trade caravans in winter and summer.", "bn": "শীত ও গ্রীষ্মে তাদের বাণিজ্য কাফেলা।"}', 'Quran 106:2', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('f871cce8-40e6-5c1f-b04a-4c4cab3b401d', '9d7d50a6-4629-5db7-a2d4-1a59ee72d544', 'choice', '{"en": "At-Takathur warns about competing in…?", "bn": "আত-তাকাসুর কোন প্রতিযোগিতা নিয়ে সতর্ক করে?"}', '{"options": [{"en": "Piling up worldly things", "bn": "দুনিয়ার প্রাচুর্য জমানো"}, {"en": "Good deeds", "bn": "নেক আমল"}, {"en": "Prayer", "bn": "নামাজ"}, {"en": "Learning", "bn": "জ্ঞানার্জন"}], "correct": 0}', '{"en": "\"Competition in (worldly) increase diverts you, until you visit the graves.\"", "bn": "\"প্রাচুর্যের প্রতিযোগিতা তোমাদের উদাসীন রাখে, যতক্ষণ না তোমরা কবরে পৌঁছাও।\""}', 'Quran 102:1–2', 5) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_lessons (id, unit_id, title, kind, sort_order) VALUES ('cd135197-6c97-552e-84ed-d5c1cbc93391', '7daee49e-19b3-53be-8bcb-411b11c7fad4', '{"en": "Unit review", "bn": "ইউনিট রিভিউ"}', 'checkpoint', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('c56f8a07-7322-5d8b-a5ba-f1f728b34536', 'cd135197-6c97-552e-84ed-d5c1cbc93391', 'choice', '{"en": "In al-Kawthar, Allah says He has given the Prophet ﷺ…?", "bn": "আল-কাওসারে আল্লাহ বলেন তিনি নবীজিকে ﷺ দিয়েছেন…?"}', '{"options": [{"en": "Al-Kawthar", "bn": "আল-কাওসার"}, {"en": "A kingdom", "bn": "রাজত্ব"}, {"en": "Gold", "bn": "স্বর্ণ"}, {"en": "Many sons", "bn": "অনেক পুত্র"}], "correct": 0}', '{"en": "Al-Kawthar, a river in Paradise with abundant good.", "bn": "আল-কাওসার, জান্নাতের এক নহর ও প্রভূত কল্যাণ।"}', 'Sahih Muslim 400', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('7b397448-cbdf-5757-9bd1-f7a4d12146f6', 'cd135197-6c97-552e-84ed-d5c1cbc93391', 'choice', '{"en": "Al-Falaq seeks refuge with the Lord of…?", "bn": "আল-ফালাক কার রবের কাছে আশ্রয় চায়?"}', '{"options": [{"en": "Daybreak", "bn": "প্রভাতের"}, {"en": "Mankind", "bn": "মানুষের"}, {"en": "The Throne", "bn": "আরশের"}, {"en": "The worlds", "bn": "জগৎসমূহের"}], "correct": 0}', '{"en": "\"Say: I seek refuge in the Lord of daybreak.\"", "bn": "\"বলুন: আমি প্রভাতের রবের আশ্রয় চাই।\""}', 'Quran 113:1', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('e20b3ce4-5a93-53d6-82b0-9edfd2b8752e', 'cd135197-6c97-552e-84ed-d5c1cbc93391', 'choice', '{"en": "An-Nasr: \"When the help of Allah comes and…\"", "bn": "আন-নাসর: \"যখন আল্লাহর সাহায্য আসবে এবং…\""}', '{"options": [{"en": "…the victory", "bn": "…বিজয়"}, {"en": "…the rain", "bn": "…বৃষ্টি"}, {"en": "…the night", "bn": "…রাত"}, {"en": "…the angels", "bn": "…ফেরেশতা"}], "correct": 0}', '{"en": "\"…and you see people entering Allah’s religion in crowds.\"", "bn": "\"…আর তুমি দেখবে মানুষ দলে দলে আল্লাহর দ্বীনে প্রবেশ করছে।\""}', 'Quran 110:1–2', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('052c22c5-04e2-5f2a-8cfc-e4894b7c80f9', 'cd135197-6c97-552e-84ed-d5c1cbc93391', 'choice', '{"en": "Al-Ma‘un warns those who neglect prayer and…?", "bn": "আল-মাউন সতর্ক করে যারা নামাজে উদাসীন এবং…?"}', '{"options": [{"en": "Refuse small kindnesses", "bn": "ছোটখাটো সাহায্যও করে না"}, {"en": "Travel far", "bn": "দূরে সফর করে"}, {"en": "Sleep early", "bn": "তাড়াতাড়ি ঘুমায়"}, {"en": "Eat dates", "bn": "খেজুর খায়"}], "correct": 0}', '{"en": "\"…and refuse (to give even) small assistance.\"", "bn": "\"…এবং ছোটখাটো জিনিস দিতেও নিষেধ করে।\""}', 'Quran 107:4–7', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('ddb06ee0-29de-5cec-80c4-8eef5aa75d1b', 'cd135197-6c97-552e-84ed-d5c1cbc93391', 'choice', '{"en": "At-Takathur warns about competing in…?", "bn": "আত-তাকাসুর কোন প্রতিযোগিতা নিয়ে সতর্ক করে?"}', '{"options": [{"en": "Piling up worldly things", "bn": "দুনিয়ার প্রাচুর্য জমানো"}, {"en": "Good deeds", "bn": "নেক আমল"}, {"en": "Prayer", "bn": "নামাজ"}, {"en": "Learning", "bn": "জ্ঞানার্জন"}], "correct": 0}', '{"en": "\"Competition in (worldly) increase diverts you, until you visit the graves.\"", "bn": "\"প্রাচুর্যের প্রতিযোগিতা তোমাদের উদাসীন রাখে, যতক্ষণ না তোমরা কবরে পৌঁছাও।\""}', 'Quran 102:1–2', 5) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('f993323f-3dc2-5348-9dcb-8c9e89af12a1', 'cd135197-6c97-552e-84ed-d5c1cbc93391', 'choice', '{"en": "Surah al-‘Asr swears by…?", "bn": "সূরা আল-আসর কীসের কসম খায়?"}', '{"options": [{"en": "Time", "bn": "সময়ের"}, {"en": "The sun", "bn": "সূর্যের"}, {"en": "The fig", "bn": "ডুমুরের"}, {"en": "The night", "bn": "রাতের"}], "correct": 0}', '{"en": "\"By time, indeed mankind is in loss, except…\"", "bn": "\"সময়ের কসম, নিশ্চয়ই মানুষ ক্ষতিতে আছে, তবে…\""}', 'Quran 103:1–3', 6) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_units (id, title, description, color, icon, review_status, sort_order, section_id) VALUES ('acf609d6-2e2b-5433-af52-ca53bf7f9f5b', '{"en": "Stories of the Quran", "bn": "কুরআনের ঘটনাবলি"}', '{}', '#8c7ae6', 'book-open', 'in_review', 1, '89429ae5-8631-51c0-ab21-02bba3e507a9') ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_lessons (id, unit_id, title, kind, sort_order) VALUES ('3b52a467-172e-5aee-8968-2f6563dd974d', 'acf609d6-2e2b-5433-af52-ca53bf7f9f5b', '{"en": "Part 1", "bn": "পর্ব ১"}', 'lesson', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('d654eedc-2723-5592-acaf-1cfe4278a9b7', '3b52a467-172e-5aee-8968-2f6563dd974d', 'choice', '{"en": "The young men who slept in the cave are in which surah?", "bn": "গুহায় ঘুমন্ত যুবকদের ঘটনা কোন সূরায়?"}', '{"options": [{"en": "Al-Kahf", "bn": "আল-কাহফ"}, {"en": "Maryam", "bn": "মারইয়াম"}, {"en": "Yusuf", "bn": "ইউসুফ"}, {"en": "Al-Anbiya", "bn": "আল-আম্বিয়া"}], "correct": 0}', '{"en": "Al-Kahf (\"the Cave\") tells of the People of the Cave.", "bn": "আল-কাহফ (\"গুহা\") সূরায় আসহাবে কাহফের ঘটনা।"}', 'Quran 18:9–26', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('db7eefe9-9e22-5a07-aab9-84304ea60e64', '3b52a467-172e-5aee-8968-2f6563dd974d', 'choice', '{"en": "Which prophet understood the speech of an ant?", "bn": "কোন নবী পিঁপড়ার কথা বুঝতেন?"}', '{"options": [{"en": "Sulayman", "bn": "সুলাইমান"}, {"en": "Dawud", "bn": "দাউদ"}, {"en": "Musa", "bn": "মুসা"}, {"en": "Nuh", "bn": "নুহ"}], "correct": 0}', '{"en": "\"So he smiled, amused at her speech.\"", "bn": "\"অতঃপর তিনি তার কথায় মুচকি হাসলেন।\""}', 'Quran 27:18–19', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('ea166445-0095-5fe6-bf73-fe3e45cdac03', '3b52a467-172e-5aee-8968-2f6563dd974d', 'choice', '{"en": "Which queen visited Sulayman?", "bn": "কোন রানি সুলাইমান (আ.)-এর কাছে এসেছিলেন?"}', '{"options": [{"en": "The Queen of Saba (Sheba)", "bn": "সাবার রানি"}, {"en": "The Queen of Egypt", "bn": "মিশরের রানি"}, {"en": "The Queen of Persia", "bn": "পারস্যের রানি"}, {"en": "The Queen of Rome", "bn": "রোমের রানি"}], "correct": 0}', '{"en": "The story of the Queen of Saba is in surah an-Naml.", "bn": "সাবার রানির ঘটনা সূরা আন-নামলে।"}', 'Quran 27:22–44', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('6b15f35c-7dca-508f-92c2-abb50bdd0868', '3b52a467-172e-5aee-8968-2f6563dd974d', 'choice', '{"en": "The people of ‘Ad, destroyed by a furious wind, were sent which prophet?", "bn": "প্রচণ্ড ঝড়ে ধ্বংস হওয়া আদ জাতির কাছে কোন নবী প্রেরিত হন?"}', '{"options": [{"en": "Hud", "bn": "হুদ"}, {"en": "Salih", "bn": "সালিহ"}, {"en": "Lut", "bn": "লুত"}, {"en": "Shu‘ayb", "bn": "শুআইব"}], "correct": 0}', '{"en": "\"And as for ‘Ad, they were destroyed by a screaming, violent wind.\"", "bn": "\"আর আদ জাতি, তাদের ধ্বংস করা হয়েছিল প্রচণ্ড ঝঞ্ঝাবায়ু দিয়ে।\""}', 'Quran 69:6; 7:65', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('b8b3adf8-6105-5652-ba5e-3bf317247d20', '3b52a467-172e-5aee-8968-2f6563dd974d', 'choice', '{"en": "A she-camel was a sign for the people of which prophet?", "bn": "একটি উটনী কোন নবীর জাতির জন্য নিদর্শন ছিল?"}', '{"options": [{"en": "Salih", "bn": "সালিহ"}, {"en": "Hud", "bn": "হুদ"}, {"en": "Ibrahim", "bn": "ইবরাহিম"}, {"en": "Isa", "bn": "ঈসা"}], "correct": 0}', '{"en": "The she-camel of Allah, sent to Thamud.", "bn": "সামুদ জাতির কাছে পাঠানো আল্লাহর উটনী।"}', 'Quran 7:73', 5) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_lessons (id, unit_id, title, kind, sort_order) VALUES ('490b5e2b-50bd-598d-b0da-ded05a5094c1', 'acf609d6-2e2b-5433-af52-ca53bf7f9f5b', '{"en": "Part 2", "bn": "পর্ব ২"}', 'lesson', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('6fa65dd6-1311-5577-8142-6847ae3e55d4', '490b5e2b-50bd-598d-b0da-ded05a5094c1', 'choice', '{"en": "Musa travelled to learn from a righteous servant of Allah, known as…?", "bn": "মুসা (আ.) আল্লাহর এক নেক বান্দার কাছে শিখতে গিয়েছিলেন, যিনি পরিচিত…?"}', '{"options": [{"en": "Al-Khidr", "bn": "খিজির"}, {"en": "Luqman", "bn": "লুকমান"}, {"en": "Dhul-Kifl", "bn": "যুলকিফল"}, {"en": "Idris", "bn": "ইদরিস"}], "correct": 0}', '{"en": "The story is in al-Kahf; the hadith names him al-Khidr.", "bn": "ঘটনাটি সূরা কাহফে; হাদিসে তাঁর নাম খিজির।"}', 'Quran 18:60–82; Sahih al-Bukhari 122', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('01b3ab55-00f3-5cdf-8a65-9bfa92a21433', '490b5e2b-50bd-598d-b0da-ded05a5094c1', 'choice', '{"en": "Which prophet was thrown into a fire that Allah made cool?", "bn": "কোন নবীকে আগুনে নিক্ষেপ করা হলে আল্লাহ তা শীতল করে দেন?"}', '{"options": [{"en": "Ibrahim", "bn": "ইবরাহিম"}, {"en": "Musa", "bn": "মুসা"}, {"en": "Yahya", "bn": "ইয়াহইয়া"}, {"en": "Ayyub", "bn": "আইয়ুব"}], "correct": 0}', '{"en": "\"O fire, be coolness and safety upon Ibrahim.\"", "bn": "\"হে আগুন, ইবরাহিমের জন্য শীতল ও নিরাপদ হয়ে যাও।\""}', 'Quran 21:69', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('6b8e1929-c931-573b-8ea7-6dcc2c89e554', '490b5e2b-50bd-598d-b0da-ded05a5094c1', 'choice', '{"en": "Whose brothers threw him into a well?", "bn": "কার ভাইয়েরা তাঁকে কূপে ফেলে দিয়েছিল?"}', '{"options": [{"en": "Yusuf", "bn": "ইউসুফ"}, {"en": "Isma‘il", "bn": "ইসমাইল"}, {"en": "Harun", "bn": "হারুন"}, {"en": "Yunus", "bn": "ইউনুস"}], "correct": 0}', '{"en": "\"…and agreed to put him into the bottom of the well.\"", "bn": "\"…এবং তাকে কূপের তলদেশে ফেলার সিদ্ধান্ত নিল।\""}', 'Quran 12:15', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('ff350913-12e7-57c6-950a-423a9d229013', '490b5e2b-50bd-598d-b0da-ded05a5094c1', 'choice', '{"en": "Dhul-Qarnayn built a barrier against whom?", "bn": "যুলকারনাইন কাদের বিরুদ্ধে প্রাচীর নির্মাণ করেন?"}', '{"options": [{"en": "Ya’juj and Ma’juj", "bn": "ইয়াজুজ-মাজুজ"}, {"en": "The people of Lut", "bn": "লুতের জাতি"}, {"en": "Pharaoh’s army", "bn": "ফেরাউনের বাহিনী"}, {"en": "The Romans", "bn": "রোমানরা"}], "correct": 0}', '{"en": "\"…Ya’juj and Ma’juj are causing corruption in the land.\"", "bn": "\"…ইয়াজুজ ও মাজুজ পৃথিবীতে ফাসাদ সৃষ্টি করছে।\""}', 'Quran 18:94–97', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('e457a0d4-9430-577e-922f-2daffc837d4b', '490b5e2b-50bd-598d-b0da-ded05a5094c1', 'choice', '{"en": "Abraha’s army came with which animals to destroy the Ka‘bah?", "bn": "কাবা ধ্বংস করতে আবরাহার বাহিনী কোন প্রাণী নিয়ে এসেছিল?"}', '{"options": [{"en": "Horses", "bn": "ঘোড়া"}, {"en": "Camels", "bn": "উট"}, {"en": "Elephants", "bn": "হাতি"}, {"en": "Lions", "bn": "সিংহ"}], "correct": 2}', '{"en": "Surah al-Fil: Allah sent birds with stones of baked clay.", "bn": "সূরা আল-ফিল: আল্লাহ পোড়া মাটির পাথরসহ পাখি পাঠালেন।"}', 'Quran 105', 5) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_lessons (id, unit_id, title, kind, sort_order) VALUES ('3afccdb9-c0e9-5be8-a121-f107203b424d', 'acf609d6-2e2b-5433-af52-ca53bf7f9f5b', '{"en": "Unit review", "bn": "ইউনিট রিভিউ"}', 'checkpoint', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('b702808d-25e3-5b75-a88d-5db21cd6231b', '3afccdb9-c0e9-5be8-a121-f107203b424d', 'choice', '{"en": "Which prophet understood the speech of an ant?", "bn": "কোন নবী পিঁপড়ার কথা বুঝতেন?"}', '{"options": [{"en": "Sulayman", "bn": "সুলাইমান"}, {"en": "Dawud", "bn": "দাউদ"}, {"en": "Musa", "bn": "মুসা"}, {"en": "Nuh", "bn": "নুহ"}], "correct": 0}', '{"en": "\"So he smiled, amused at her speech.\"", "bn": "\"অতঃপর তিনি তার কথায় মুচকি হাসলেন।\""}', 'Quran 27:18–19', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('b13c4374-0446-53b9-b83d-8cdaed657280', '3afccdb9-c0e9-5be8-a121-f107203b424d', 'choice', '{"en": "The people of ‘Ad, destroyed by a furious wind, were sent which prophet?", "bn": "প্রচণ্ড ঝড়ে ধ্বংস হওয়া আদ জাতির কাছে কোন নবী প্রেরিত হন?"}', '{"options": [{"en": "Hud", "bn": "হুদ"}, {"en": "Salih", "bn": "সালিহ"}, {"en": "Lut", "bn": "লুত"}, {"en": "Shu‘ayb", "bn": "শুআইব"}], "correct": 0}', '{"en": "\"And as for ‘Ad, they were destroyed by a screaming, violent wind.\"", "bn": "\"আর আদ জাতি, তাদের ধ্বংস করা হয়েছিল প্রচণ্ড ঝঞ্ঝাবায়ু দিয়ে।\""}', 'Quran 69:6; 7:65', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('1261baa5-fab4-541b-a7ec-53117a9e3145', '3afccdb9-c0e9-5be8-a121-f107203b424d', 'choice', '{"en": "Musa travelled to learn from a righteous servant of Allah, known as…?", "bn": "মুসা (আ.) আল্লাহর এক নেক বান্দার কাছে শিখতে গিয়েছিলেন, যিনি পরিচিত…?"}', '{"options": [{"en": "Al-Khidr", "bn": "খিজির"}, {"en": "Luqman", "bn": "লুকমান"}, {"en": "Dhul-Kifl", "bn": "যুলকিফল"}, {"en": "Idris", "bn": "ইদরিস"}], "correct": 0}', '{"en": "The story is in al-Kahf; the hadith names him al-Khidr.", "bn": "ঘটনাটি সূরা কাহফে; হাদিসে তাঁর নাম খিজির।"}', 'Quran 18:60–82; Sahih al-Bukhari 122', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('3a050509-3e36-5172-ab2f-820b5f6af400', '3afccdb9-c0e9-5be8-a121-f107203b424d', 'choice', '{"en": "Whose brothers threw him into a well?", "bn": "কার ভাইয়েরা তাঁকে কূপে ফেলে দিয়েছিল?"}', '{"options": [{"en": "Yusuf", "bn": "ইউসুফ"}, {"en": "Isma‘il", "bn": "ইসমাইল"}, {"en": "Harun", "bn": "হারুন"}, {"en": "Yunus", "bn": "ইউনুস"}], "correct": 0}', '{"en": "\"…and agreed to put him into the bottom of the well.\"", "bn": "\"…এবং তাকে কূপের তলদেশে ফেলার সিদ্ধান্ত নিল।\""}', 'Quran 12:15', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('0d51b91a-43ec-54d6-bdb8-dcdee551ae10', '3afccdb9-c0e9-5be8-a121-f107203b424d', 'choice', '{"en": "Abraha’s army came with which animals to destroy the Ka‘bah?", "bn": "কাবা ধ্বংস করতে আবরাহার বাহিনী কোন প্রাণী নিয়ে এসেছিল?"}', '{"options": [{"en": "Horses", "bn": "ঘোড়া"}, {"en": "Camels", "bn": "উট"}, {"en": "Elephants", "bn": "হাতি"}, {"en": "Lions", "bn": "সিংহ"}], "correct": 2}', '{"en": "Surah al-Fil: Allah sent birds with stones of baked clay.", "bn": "সূরা আল-ফিল: আল্লাহ পোড়া মাটির পাথরসহ পাখি পাঠালেন।"}', 'Quran 105', 5) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('51d33813-b632-5c73-90dc-ed41d87f8e17', '3afccdb9-c0e9-5be8-a121-f107203b424d', 'choice', '{"en": "The young men who slept in the cave are in which surah?", "bn": "গুহায় ঘুমন্ত যুবকদের ঘটনা কোন সূরায়?"}', '{"options": [{"en": "Al-Kahf", "bn": "আল-কাহফ"}, {"en": "Maryam", "bn": "মারইয়াম"}, {"en": "Yusuf", "bn": "ইউসুফ"}, {"en": "Al-Anbiya", "bn": "আল-আম্বিয়া"}], "correct": 0}', '{"en": "Al-Kahf (\"the Cave\") tells of the People of the Cave.", "bn": "আল-কাহফ (\"গুহা\") সূরায় আসহাবে কাহফের ঘটনা।"}', 'Quran 18:9–26', 6) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_units (id, title, description, color, icon, review_status, sort_order, section_id) VALUES ('4d75074a-1613-5dfc-9315-a15c9544c196', '{"en": "Complete the ayah (meaning)", "bn": "আয়াত পূর্ণ করুন (অর্থ)"}', '{}', '#8c7ae6', 'book-open', 'in_review', 2, '89429ae5-8631-51c0-ab21-02bba3e507a9') ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_lessons (id, unit_id, title, kind, sort_order) VALUES ('01f2317e-cbc6-50c0-befe-288f8918e9f1', '4d75074a-1613-5dfc-9315-a15c9544c196', '{"en": "Part 1", "bn": "পর্ব ১"}', 'lesson', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('a82869a7-f439-5e98-b507-01164c6880bf', '01f2317e-cbc6-50c0-befe-288f8918e9f1', 'choice', '{"en": "\"Indeed, with hardship comes…\"", "bn": "\"নিশ্চয়ই কষ্টের সাথে আছে…\""}', '{"options": [{"en": "…ease", "bn": "…স্বস্তি"}, {"en": "…more hardship", "bn": "…আরও কষ্ট"}, {"en": "…wealth", "bn": "…সম্পদ"}, {"en": "…sleep", "bn": "…ঘুম"}], "correct": 0}', '{"en": "Said twice in surah ash-Sharh.", "bn": "সূরা আশ-শারহে দুবার বলা হয়েছে।"}', 'Quran 94:5–6', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('73254040-107b-563e-95a5-a2ce23e91c45', '01f2317e-cbc6-50c0-befe-288f8918e9f1', 'choice', '{"en": "\"Allah does not burden a soul beyond its…\"", "bn": "\"আল্লাহ কাউকে তার… এর বাইরে বোঝা দেন না\""}', '{"options": [{"en": "…capacity", "bn": "…সাধ্য"}, {"en": "…age", "bn": "…বয়স"}, {"en": "…wealth", "bn": "…সম্পদ"}, {"en": "…family", "bn": "…পরিবার"}], "correct": 0}', '{"en": "The last ayah of al-Baqarah begins this way.", "bn": "আল-বাকারার শেষ আয়াত এভাবে শুরু।"}', 'Quran 2:286', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('c7abb618-4449-54d8-8c6f-c4a7f146996e', '01f2317e-cbc6-50c0-befe-288f8918e9f1', 'choice', '{"en": "\"So remember Me; I will…\"", "bn": "\"সুতরাং তোমরা আমাকে স্মরণ করো; আমি…\""}', '{"options": [{"en": "…remember you", "bn": "…তোমাদের স্মরণ করব"}, {"en": "…test you", "bn": "…তোমাদের পরীক্ষা করব"}, {"en": "…leave you", "bn": "…তোমাদের ছেড়ে দেব"}, {"en": "…ask you", "bn": "…তোমাদের জিজ্ঞেস করব"}], "correct": 0}', '{"en": "\"…and be grateful to Me and do not deny Me.\"", "bn": "\"…আর আমার কৃতজ্ঞ হও, অকৃতজ্ঞ হয়ো না।\""}', 'Quran 2:152', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('9638b831-3921-5be6-8758-a99e3ab2511b', '01f2317e-cbc6-50c0-befe-288f8918e9f1', 'choice', '{"en": "\"Verily, in the remembrance of Allah do hearts find…\"", "bn": "\"জেনে রাখো, আল্লাহর স্মরণেই হৃদয় পায়…\""}', '{"options": [{"en": "…rest", "bn": "…প্রশান্তি"}, {"en": "…fear", "bn": "…ভয়"}, {"en": "…wealth", "bn": "…সম্পদ"}, {"en": "…fame", "bn": "…খ্যাতি"}], "correct": 0}', '{"en": "Hearts find tranquillity in dhikr.", "bn": "জিকিরে হৃদয় প্রশান্তি পায়।"}', 'Quran 13:28', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('d90a9004-7d2c-52e2-8c0e-7264fcbe2d65', '01f2317e-cbc6-50c0-befe-288f8918e9f1', 'choice', '{"en": "\"And whoever puts his trust in Allah, He is…\"", "bn": "\"আর যে আল্লাহর ওপর ভরসা করে, তিনি…\""}', '{"options": [{"en": "…sufficient for him", "bn": "…তার জন্য যথেষ্ট"}, {"en": "…far from him", "bn": "…তার থেকে দূরে"}, {"en": "…angry with him", "bn": "…তার ওপর রাগান্বিত"}, {"en": "…testing him", "bn": "…তাকে পরীক্ষা করছেন"}], "correct": 0}', '{"en": "Tawakkul: relying on Allah after taking the means.", "bn": "তাওয়াক্কুল: উপায় অবলম্বনের পর আল্লাহর ওপর ভরসা।"}', 'Quran 65:3', 5) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_lessons (id, unit_id, title, kind, sort_order) VALUES ('3edcaa5b-c612-5087-b371-193a04285f77', '4d75074a-1613-5dfc-9315-a15c9544c196', '{"en": "Part 2", "bn": "পর্ব ২"}', 'lesson', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('24e0b6ed-e13d-5eb7-8589-334a5738fc63', '3edcaa5b-c612-5087-b371-193a04285f77', 'choice', '{"en": "\"Call upon Me; I will…\"", "bn": "\"তোমরা আমাকে ডাকো; আমি…\""}', '{"options": [{"en": "…respond to you", "bn": "…তোমাদের ডাকে সাড়া দেব"}, {"en": "…ignore you", "bn": "…উপেক্ষা করব"}, {"en": "…punish you", "bn": "…শাস্তি দেব"}, {"en": "…test you", "bn": "…পরীক্ষা করব"}], "correct": 0}', '{"en": "Dua is worship, and Allah answers.", "bn": "দোয়া ইবাদত, আর আল্লাহ সাড়া দেন।"}', 'Quran 40:60', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('eb231e16-899d-5404-80a3-fc831bc70fba', '3edcaa5b-c612-5087-b371-193a04285f77', 'choice', '{"en": "\"Do not despair of the mercy of…\"", "bn": "\"… এর রহমত থেকে নিরাশ হয়ো না\""}', '{"options": [{"en": "…Allah", "bn": "…আল্লাহ"}, {"en": "…people", "bn": "…মানুষ"}, {"en": "…kings", "bn": "…রাজা"}, {"en": "…friends", "bn": "…বন্ধু"}], "correct": 0}', '{"en": "\"…indeed Allah forgives all sins.\"", "bn": "\"…নিশ্চয়ই আল্লাহ সব গুনাহ ক্ষমা করেন।\""}', 'Quran 39:53', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('b82eb798-a713-593c-bf8d-dcdd3818024a', '3edcaa5b-c612-5087-b371-193a04285f77', 'choice', '{"en": "\"Indeed, Allah is with the…\"", "bn": "\"নিশ্চয়ই আল্লাহ… এর সাথে আছেন\""}', '{"options": [{"en": "…patient", "bn": "…ধৈর্যশীলদের"}, {"en": "…rich", "bn": "…ধনীদের"}, {"en": "…strong", "bn": "…শক্তিশালীদের"}, {"en": "…famous", "bn": "…বিখ্যাতদের"}], "correct": 0}', '{"en": "\"Seek help through patience and prayer; indeed Allah is with the patient.\"", "bn": "\"ধৈর্য ও নামাজের মাধ্যমে সাহায্য চাও; নিশ্চয়ই আল্লাহ ধৈর্যশীলদের সাথে আছেন।\""}', 'Quran 2:153', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('b47a4a8f-8bf3-5b15-bcd0-274b373cc68a', '3edcaa5b-c612-5087-b371-193a04285f77', 'choice', '{"en": "\"…and speak to people…\"", "bn": "\"…এবং মানুষের সাথে বলো…\""}', '{"options": [{"en": "…good words", "bn": "…উত্তম কথা"}, {"en": "…loudly", "bn": "…জোরে"}, {"en": "…rarely", "bn": "…কদাচিৎ"}, {"en": "…in secret", "bn": "…গোপনে"}], "correct": 0}', '{"en": "Part of the covenant taken from the Children of Israel.", "bn": "বনি ইসরাইলের কাছ থেকে নেওয়া অঙ্গীকারের অংশ।"}', 'Quran 2:83', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('a3853418-154c-50ad-8761-750daf6ae185', '3edcaa5b-c612-5087-b371-193a04285f77', 'choice', '{"en": "\"I did not create the jinn and mankind except to…\"", "bn": "\"আমি জিন ও মানুষকে সৃষ্টি করেছি শুধু…\""}', '{"options": [{"en": "…worship Me", "bn": "…আমার ইবাদতের জন্য"}, {"en": "…play", "bn": "…খেলার জন্য"}, {"en": "…sleep", "bn": "…ঘুমানোর জন্য"}, {"en": "…trade", "bn": "…ব্যবসার জন্য"}], "correct": 0}', '{"en": "The purpose of our creation.", "bn": "আমাদের সৃষ্টির উদ্দেশ্য।"}', 'Quran 51:56', 5) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_lessons (id, unit_id, title, kind, sort_order) VALUES ('64bf8f68-b87e-5359-987d-ac6d6f1e5017', '4d75074a-1613-5dfc-9315-a15c9544c196', '{"en": "Unit review", "bn": "ইউনিট রিভিউ"}', 'checkpoint', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('d02f37fd-76b8-5287-8619-f215e0e5bb0e', '64bf8f68-b87e-5359-987d-ac6d6f1e5017', 'choice', '{"en": "\"Allah does not burden a soul beyond its…\"", "bn": "\"আল্লাহ কাউকে তার… এর বাইরে বোঝা দেন না\""}', '{"options": [{"en": "…capacity", "bn": "…সাধ্য"}, {"en": "…age", "bn": "…বয়স"}, {"en": "…wealth", "bn": "…সম্পদ"}, {"en": "…family", "bn": "…পরিবার"}], "correct": 0}', '{"en": "The last ayah of al-Baqarah begins this way.", "bn": "আল-বাকারার শেষ আয়াত এভাবে শুরু।"}', 'Quran 2:286', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('f85428a6-4130-5f95-aec8-fd948cb8b70f', '64bf8f68-b87e-5359-987d-ac6d6f1e5017', 'choice', '{"en": "\"Verily, in the remembrance of Allah do hearts find…\"", "bn": "\"জেনে রাখো, আল্লাহর স্মরণেই হৃদয় পায়…\""}', '{"options": [{"en": "…rest", "bn": "…প্রশান্তি"}, {"en": "…fear", "bn": "…ভয়"}, {"en": "…wealth", "bn": "…সম্পদ"}, {"en": "…fame", "bn": "…খ্যাতি"}], "correct": 0}', '{"en": "Hearts find tranquillity in dhikr.", "bn": "জিকিরে হৃদয় প্রশান্তি পায়।"}', 'Quran 13:28', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('0fc68515-b68b-58b7-be1f-b51cf28bae94', '64bf8f68-b87e-5359-987d-ac6d6f1e5017', 'choice', '{"en": "\"Call upon Me; I will…\"", "bn": "\"তোমরা আমাকে ডাকো; আমি…\""}', '{"options": [{"en": "…respond to you", "bn": "…তোমাদের ডাকে সাড়া দেব"}, {"en": "…ignore you", "bn": "…উপেক্ষা করব"}, {"en": "…punish you", "bn": "…শাস্তি দেব"}, {"en": "…test you", "bn": "…পরীক্ষা করব"}], "correct": 0}', '{"en": "Dua is worship, and Allah answers.", "bn": "দোয়া ইবাদত, আর আল্লাহ সাড়া দেন।"}', 'Quran 40:60', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('eb575fd8-6f9f-5599-bbb9-eac509533975', '64bf8f68-b87e-5359-987d-ac6d6f1e5017', 'choice', '{"en": "\"Indeed, Allah is with the…\"", "bn": "\"নিশ্চয়ই আল্লাহ… এর সাথে আছেন\""}', '{"options": [{"en": "…patient", "bn": "…ধৈর্যশীলদের"}, {"en": "…rich", "bn": "…ধনীদের"}, {"en": "…strong", "bn": "…শক্তিশালীদের"}, {"en": "…famous", "bn": "…বিখ্যাতদের"}], "correct": 0}', '{"en": "\"Seek help through patience and prayer; indeed Allah is with the patient.\"", "bn": "\"ধৈর্য ও নামাজের মাধ্যমে সাহায্য চাও; নিশ্চয়ই আল্লাহ ধৈর্যশীলদের সাথে আছেন।\""}', 'Quran 2:153', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('0db5095d-fd68-51c8-a5b4-a59f586b5afc', '64bf8f68-b87e-5359-987d-ac6d6f1e5017', 'choice', '{"en": "\"I did not create the jinn and mankind except to…\"", "bn": "\"আমি জিন ও মানুষকে সৃষ্টি করেছি শুধু…\""}', '{"options": [{"en": "…worship Me", "bn": "…আমার ইবাদতের জন্য"}, {"en": "…play", "bn": "…খেলার জন্য"}, {"en": "…sleep", "bn": "…ঘুমানোর জন্য"}, {"en": "…trade", "bn": "…ব্যবসার জন্য"}], "correct": 0}', '{"en": "The purpose of our creation.", "bn": "আমাদের সৃষ্টির উদ্দেশ্য।"}', 'Quran 51:56', 5) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('5c87580a-e4e0-5008-b1c7-dbe5648f06dd', '64bf8f68-b87e-5359-987d-ac6d6f1e5017', 'choice', '{"en": "\"Indeed, with hardship comes…\"", "bn": "\"নিশ্চয়ই কষ্টের সাথে আছে…\""}', '{"options": [{"en": "…ease", "bn": "…স্বস্তি"}, {"en": "…more hardship", "bn": "…আরও কষ্ট"}, {"en": "…wealth", "bn": "…সম্পদ"}, {"en": "…sleep", "bn": "…ঘুম"}], "correct": 0}', '{"en": "Said twice in surah ash-Sharh.", "bn": "সূরা আশ-শারহে দুবার বলা হয়েছে।"}', 'Quran 94:5–6', 6) ON CONFLICT (id) DO NOTHING;
