INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('682c2bee-5fef-548c-9157-783011a3292b', '8e979422-6931-5524-8427-53b16da8cc86', 'choice', '{"en": "Who was the first prophet?", "bn": "প্রথম নবী কে?"}', '{"options": [{"en": "Nuh", "bn": "নুহ"}, {"en": "Adam", "bn": "আদম"}, {"en": "Ibrahim", "bn": "ইবরাহিম"}, {"en": "Idris", "bn": "ইদরিস"}], "correct": 1}', '{"en": "Adam (peace be upon him) was the first human and the first prophet.", "bn": "আদম (আ.) প্রথম মানুষ ও প্রথম নবী।"}', NULL, 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('48abe1d2-242e-5563-8a3d-6e82278ff3de', '8e979422-6931-5524-8427-53b16da8cc86', 'choice', '{"en": "Which prophet raised the foundations of the Ka‘bah with his son?", "bn": "কোন নবী ছেলের সাথে কাবার ভিত্তি তুলেছিলেন?"}', '{"options": [{"en": "Ibrahim", "bn": "ইবরাহিম"}, {"en": "Musa", "bn": "মুসা"}, {"en": "Dawud", "bn": "দাউদ"}, {"en": "Sulayman", "bn": "সুলাইমান"}], "correct": 0}', '{"en": "Ibrahim and Isma‘il raised the foundations of the House.", "bn": "ইবরাহিম ও ইসমাইল (আ.) কাবার ভিত্তি তুলেছিলেন।"}', 'Quran 2:127', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('78c3b58f-c1f5-5f3b-bdf9-bf8bf540239a', '8e979422-6931-5524-8427-53b16da8cc86', 'choice', '{"en": "Which prophet was swallowed by a great fish?", "bn": "কোন নবীকে বড় মাছ গিলে ফেলেছিল?"}', '{"options": [{"en": "Yusuf", "bn": "ইউসুফ"}, {"en": "Ayyub", "bn": "আইয়ুব"}, {"en": "Yunus", "bn": "ইউনুস"}, {"en": "Ilyas", "bn": "ইলিয়াস"}], "correct": 2}', '{"en": "Yunus called out from the darkness: \"There is no god but You…\"", "bn": "ইউনুস (আ.) অন্ধকার থেকে ডেকেছিলেন: \"আপনি ছাড়া কোনো উপাস্য নেই…\""}', 'Quran 37:139–144; 21:87', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('b689c86c-daa1-5954-9701-6bf8218cde7a', '8e979422-6931-5524-8427-53b16da8cc86', 'choice', '{"en": "Allah spoke directly to which prophet?", "bn": "আল্লাহ কোন নবীর সাথে সরাসরি কথা বলেছেন?"}', '{"options": [{"en": "Musa", "bn": "মুসা"}, {"en": "Isa", "bn": "ঈসা"}, {"en": "Harun", "bn": "হারুন"}, {"en": "Shu‘ayb", "bn": "শুআইব"}], "correct": 0}', '{"en": "\"And Allah spoke to Musa directly.\"", "bn": "\"আর আল্লাহ মুসার সাথে সরাসরি কথা বলেছেন।\""}', 'Quran 4:164', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('1a9c3dcb-f8c4-55c2-b16f-2bc4fbc3a98a', '8e979422-6931-5524-8427-53b16da8cc86', 'choice', '{"en": "Which prophet built the Ark?", "bn": "কোন নবী নৌকা (কিশতি) তৈরি করেছিলেন?"}', '{"options": [{"en": "Hud", "bn": "হুদ"}, {"en": "Salih", "bn": "সালিহ"}, {"en": "Nuh", "bn": "নুহ"}, {"en": "Lut", "bn": "লুত"}], "correct": 2}', '{"en": "Nuh built the Ark by Allah’s command before the flood.", "bn": "প্লাবনের আগে আল্লাহর আদেশে নুহ (আ.) নৌকা তৈরি করেন।"}', 'Quran 11:37', 5) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_lessons (id, unit_id, title, kind, sort_order) VALUES ('3ae13d6b-de34-5598-905f-a13322fedcaf', '5901118c-7cd6-59b9-b22a-ee2c35a3da0a', '{"en": "Part 2", "bn": "পর্ব ২"}', 'lesson', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('405a954e-fa31-54e4-9e79-cab176049839', '3ae13d6b-de34-5598-905f-a13322fedcaf', 'choice', '{"en": "Which prophet was given the Zabur (Psalms)?", "bn": "কোন নবীকে যাবুর দেওয়া হয়েছিল?"}', '{"options": [{"en": "Dawud", "bn": "দাউদ"}, {"en": "Musa", "bn": "মুসা"}, {"en": "Isa", "bn": "ঈসা"}, {"en": "Zakariyya", "bn": "যাকারিয়া"}], "correct": 0}', '{"en": "\"…and to Dawud We gave the Zabur.\"", "bn": "\"…আর দাউদকে আমি যাবুর দিয়েছি।\""}', 'Quran 4:163', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('c4a028da-d4f6-50aa-8705-4f9e8e80bea7', '3ae13d6b-de34-5598-905f-a13322fedcaf', 'choice', '{"en": "Who is the final prophet?", "bn": "শেষ নবী কে?"}', '{"options": [{"en": "Isa", "bn": "ঈসা"}, {"en": "Muhammad ﷺ", "bn": "মুহাম্মাদ ﷺ"}, {"en": "Yahya", "bn": "ইয়াহইয়া"}, {"en": "Ibrahim", "bn": "ইবরাহিম"}], "correct": 1}', '{"en": "Muhammad ﷺ is the Messenger of Allah and the Seal of the Prophets.", "bn": "মুহাম্মাদ ﷺ আল্লাহর রাসুল ও শেষ নবী।"}', 'Quran 33:40', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('0b399038-d98a-5cce-acef-512a4c5529d2', '3ae13d6b-de34-5598-905f-a13322fedcaf', 'choice', '{"en": "Who was the mother of Prophet Isa?", "bn": "ঈসা (আ.)-এর মা কে ছিলেন?"}', '{"options": [{"en": "Asiya", "bn": "আসিয়া"}, {"en": "Hajar", "bn": "হাজেরা"}, {"en": "Maryam", "bn": "মারইয়াম"}, {"en": "Sarah", "bn": "সারা"}], "correct": 2}', '{"en": "Maryam, honoured with a surah named after her (Quran 19).", "bn": "মারইয়াম (আ.), তাঁর নামে একটি সূরা আছে (সূরা ১৯)।"}', 'Quran 19', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('3ec23055-dbd1-5205-99a4-43738fc35a63', '3ae13d6b-de34-5598-905f-a13322fedcaf', 'choice', '{"en": "Which prophet is known for his patience through long illness?", "bn": "দীর্ঘ অসুস্থতায় ধৈর্যের জন্য কোন নবী প্রসিদ্ধ?"}', '{"options": [{"en": "Ayyub", "bn": "আইয়ুব"}, {"en": "Yaqub", "bn": "ইয়াকুব"}, {"en": "Musa", "bn": "মুসা"}, {"en": "Hud", "bn": "হুদ"}], "correct": 0}', '{"en": "\"Indeed We found him patient; an excellent servant.\"", "bn": "\"নিশ্চয়ই আমি তাকে ধৈর্যশীল পেয়েছি; কত উত্তম বান্দা!\""}', 'Quran 38:44', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('43d31fac-9d59-54bc-898c-42a205c90815', '3ae13d6b-de34-5598-905f-a13322fedcaf', 'choice', '{"en": "Which prophet dreamt of eleven stars, the sun and the moon?", "bn": "কোন নবী এগারোটি তারা, সূর্য ও চাঁদের স্বপ্ন দেখেছিলেন?"}', '{"options": [{"en": "Yusuf", "bn": "ইউসুফ"}, {"en": "Sulayman", "bn": "সুলাইমান"}, {"en": "Ismail", "bn": "ইসমাইল"}, {"en": "Yunus", "bn": "ইউনুস"}], "correct": 0}', '{"en": "Yusuf told his father of the dream as a boy.", "bn": "শৈশবে ইউসুফ (আ.) বাবাকে এই স্বপ্নের কথা বলেছিলেন।"}', 'Quran 12:4', 5) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_lessons (id, unit_id, title, kind, sort_order) VALUES ('54d5ca8e-8ba2-5a6c-9385-3ee1f0fbaaee', '5901118c-7cd6-59b9-b22a-ee2c35a3da0a', '{"en": "Unit review", "bn": "ইউনিট রিভিউ"}', 'checkpoint', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('eb12b00c-3e97-58c0-a758-7160ba6f6680', '54d5ca8e-8ba2-5a6c-9385-3ee1f0fbaaee', 'choice', '{"en": "Which prophet raised the foundations of the Ka‘bah with his son?", "bn": "কোন নবী ছেলের সাথে কাবার ভিত্তি তুলেছিলেন?"}', '{"options": [{"en": "Ibrahim", "bn": "ইবরাহিম"}, {"en": "Musa", "bn": "মুসা"}, {"en": "Dawud", "bn": "দাউদ"}, {"en": "Sulayman", "bn": "সুলাইমান"}], "correct": 0}', '{"en": "Ibrahim and Isma‘il raised the foundations of the House.", "bn": "ইবরাহিম ও ইসমাইল (আ.) কাবার ভিত্তি তুলেছিলেন।"}', 'Quran 2:127', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('3ce8796c-faaa-58e4-bb9b-3b69fbc3f8db', '54d5ca8e-8ba2-5a6c-9385-3ee1f0fbaaee', 'choice', '{"en": "Allah spoke directly to which prophet?", "bn": "আল্লাহ কোন নবীর সাথে সরাসরি কথা বলেছেন?"}', '{"options": [{"en": "Musa", "bn": "মুসা"}, {"en": "Isa", "bn": "ঈসা"}, {"en": "Harun", "bn": "হারুন"}, {"en": "Shu‘ayb", "bn": "শুআইব"}], "correct": 0}', '{"en": "\"And Allah spoke to Musa directly.\"", "bn": "\"আর আল্লাহ মুসার সাথে সরাসরি কথা বলেছেন।\""}', 'Quran 4:164', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('bb2737e7-f026-5ffd-8e5e-f0f04e200f29', '54d5ca8e-8ba2-5a6c-9385-3ee1f0fbaaee', 'choice', '{"en": "Which prophet was given the Zabur (Psalms)?", "bn": "কোন নবীকে যাবুর দেওয়া হয়েছিল?"}', '{"options": [{"en": "Dawud", "bn": "দাউদ"}, {"en": "Musa", "bn": "মুসা"}, {"en": "Isa", "bn": "ঈসা"}, {"en": "Zakariyya", "bn": "যাকারিয়া"}], "correct": 0}', '{"en": "\"…and to Dawud We gave the Zabur.\"", "bn": "\"…আর দাউদকে আমি যাবুর দিয়েছি।\""}', 'Quran 4:163', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('01d9816b-608e-5e0c-a2eb-c1548d2da34a', '54d5ca8e-8ba2-5a6c-9385-3ee1f0fbaaee', 'choice', '{"en": "Who was the mother of Prophet Isa?", "bn": "ঈসা (আ.)-এর মা কে ছিলেন?"}', '{"options": [{"en": "Asiya", "bn": "আসিয়া"}, {"en": "Hajar", "bn": "হাজেরা"}, {"en": "Maryam", "bn": "মারইয়াম"}, {"en": "Sarah", "bn": "সারা"}], "correct": 2}', '{"en": "Maryam, honoured with a surah named after her (Quran 19).", "bn": "মারইয়াম (আ.), তাঁর নামে একটি সূরা আছে (সূরা ১৯)।"}', 'Quran 19', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('b7b95f4d-3238-52f9-b671-d3e354fff6bb', '54d5ca8e-8ba2-5a6c-9385-3ee1f0fbaaee', 'choice', '{"en": "Which prophet dreamt of eleven stars, the sun and the moon?", "bn": "কোন নবী এগারোটি তারা, সূর্য ও চাঁদের স্বপ্ন দেখেছিলেন?"}', '{"options": [{"en": "Yusuf", "bn": "ইউসুফ"}, {"en": "Sulayman", "bn": "সুলাইমান"}, {"en": "Ismail", "bn": "ইসমাইল"}, {"en": "Yunus", "bn": "ইউনুস"}], "correct": 0}', '{"en": "Yusuf told his father of the dream as a boy.", "bn": "শৈশবে ইউসুফ (আ.) বাবাকে এই স্বপ্নের কথা বলেছিলেন।"}', 'Quran 12:4', 5) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('6c3e1565-d8a9-562f-8f23-91250e19a41d', '54d5ca8e-8ba2-5a6c-9385-3ee1f0fbaaee', 'choice', '{"en": "Who was the first prophet?", "bn": "প্রথম নবী কে?"}', '{"options": [{"en": "Nuh", "bn": "নুহ"}, {"en": "Adam", "bn": "আদম"}, {"en": "Ibrahim", "bn": "ইবরাহিম"}, {"en": "Idris", "bn": "ইদরিস"}], "correct": 1}', '{"en": "Adam (peace be upon him) was the first human and the first prophet.", "bn": "আদম (আ.) প্রথম মানুষ ও প্রথম নবী।"}', NULL, 6) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_units (id, title, description, color, icon, review_status, sort_order, section_id) VALUES ('af9e8c14-2f77-59f6-9a41-81d3e85a4621', '{"en": "Prophets of Allah — part 2", "bn": "আল্লাহর নবী-রাসুলগণ — পর্ব ২"}', '{}', '#e1b12c', 'users', 'in_review', 2, '07bf5aab-bcbb-5c29-8531-e6ef84bd48e7') ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_lessons (id, unit_id, title, kind, sort_order) VALUES ('05c80135-39d0-5928-9106-e7a5380f1451', 'af9e8c14-2f77-59f6-9a41-81d3e85a4621', '{"en": "Part 1", "bn": "পর্ব ১"}', 'lesson', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('13e7c046-6be1-5231-a813-d68ef352a0e6', '05c80135-39d0-5928-9106-e7a5380f1451', 'choice', '{"en": "Who was the father of Prophet Yusuf?", "bn": "ইউসুফ (আ.)-এর পিতা কে?"}', '{"options": [{"en": "Ya‘qub", "bn": "ইয়াকুব"}, {"en": "Ishaq", "bn": "ইসহাক"}, {"en": "Ibrahim", "bn": "ইবরাহিম"}, {"en": "Isma‘il", "bn": "ইসমাইল"}], "correct": 0}', '{"en": "Ya‘qub, son of Ishaq, son of Ibrahim.", "bn": "ইয়াকুব, ইসহাকের পুত্র, যিনি ইবরাহিমের পুত্র।"}', 'Quran 12:4–6', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('b47504e1-bb52-5099-a7c1-7c7065b1d76e', '05c80135-39d0-5928-9106-e7a5380f1451', 'choice', '{"en": "Which son of Dawud was a prophet-king?", "bn": "দাউদের কোন পুত্র নবী-রাজা ছিলেন?"}', '{"options": [{"en": "Sulayman", "bn": "সুলাইমান"}, {"en": "Yahya", "bn": "ইয়াহইয়া"}, {"en": "Harun", "bn": "হারুন"}, {"en": "Ilyas", "bn": "ইলিয়াস"}], "correct": 0}', '{"en": "\"And Sulayman inherited Dawud.\"", "bn": "\"আর সুলাইমান দাউদের উত্তরাধিকারী হলেন।\""}', 'Quran 27:16', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('d3596472-edce-51e3-97a0-a358392500d7', '05c80135-39d0-5928-9106-e7a5380f1451', 'choice', '{"en": "Which prophet was given the son Yahya in old age?", "bn": "কোন নবীকে বৃদ্ধ বয়সে পুত্র ইয়াহইয়া দেওয়া হয়?"}', '{"options": [{"en": "Zakariyya", "bn": "যাকারিয়া"}, {"en": "Ibrahim", "bn": "ইবরাহিম"}, {"en": "Nuh", "bn": "নুহ"}, {"en": "Lut", "bn": "লুত"}], "correct": 0}', '{"en": "\"O Zakariyya, We give you good news of a boy whose name is Yahya.\"", "bn": "\"হে যাকারিয়া, আমি তোমাকে এক পুত্রের সুসংবাদ দিচ্ছি, তার নাম ইয়াহইয়া।\""}', 'Quran 19:7', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('7fd62f1e-486e-56ed-a885-081bac5e2ee6', '05c80135-39d0-5928-9106-e7a5380f1451', 'choice', '{"en": "Whose staff turned into a snake?", "bn": "কার লাঠি সাপে পরিণত হয়েছিল?"}', '{"options": [{"en": "Musa", "bn": "মুসা"}, {"en": "Isa", "bn": "ঈসা"}, {"en": "Sulayman", "bn": "সুলাইমান"}, {"en": "Ibrahim", "bn": "ইবরাহিম"}], "correct": 0}', '{"en": "\"So he threw it, and at once it was a snake, moving swiftly.\"", "bn": "\"অতঃপর তিনি তা নিক্ষেপ করলেন, আর তা হয়ে গেল ছুটন্ত সাপ।\""}', 'Quran 20:20', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('8532cdd5-2e5a-5a5c-b47f-1893fa2a088e', '05c80135-39d0-5928-9106-e7a5380f1451', 'choice', '{"en": "Which prophet healed the blind and the leper by Allah’s permission?", "bn": "কোন নবী আল্লাহর অনুমতিতে অন্ধ ও কুষ্ঠরোগীকে সুস্থ করতেন?"}', '{"options": [{"en": "Isa", "bn": "ঈসা"}, {"en": "Ayyub", "bn": "আইয়ুব"}, {"en": "Yunus", "bn": "ইউনুস"}, {"en": "Hud", "bn": "হুদ"}], "correct": 0}', '{"en": "\"…and I heal the blind and the leper, and give life to the dead, by permission of Allah.\"", "bn": "\"…আর আমি আল্লাহর অনুমতিতে অন্ধ ও কুষ্ঠরোগীকে সুস্থ করি এবং মৃতকে জীবিত করি।\""}', 'Quran 3:49', 5) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_lessons (id, unit_id, title, kind, sort_order) VALUES ('bc29ccc9-f965-5d6d-8ed3-831b21db36f2', 'af9e8c14-2f77-59f6-9a41-81d3e85a4621', '{"en": "Part 2", "bn": "পর্ব ২"}', 'lesson', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('fb5b1705-45bc-560e-8a98-98c3f3c42524', 'bc29ccc9-f965-5d6d-8ed3-831b21db36f2', 'choice', '{"en": "Which prophet was sent to the people of Madyan?", "bn": "মাদইয়ানবাসীর কাছে কোন নবী প্রেরিত হন?"}', '{"options": [{"en": "Shu‘ayb", "bn": "শুআইব"}, {"en": "Salih", "bn": "সালিহ"}, {"en": "Hud", "bn": "হুদ"}, {"en": "Lut", "bn": "লুত"}], "correct": 0}', '{"en": "He told them to give full measure and weight.", "bn": "তিনি তাদের মাপ ও ওজন পূর্ণ দিতে বলেছিলেন।"}', 'Quran 7:85', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('bcdd34e8-d853-54f9-a3aa-53129d638213', 'bc29ccc9-f965-5d6d-8ed3-831b21db36f2', 'choice', '{"en": "Who was Musa’s brother and helper?", "bn": "মুসার ভাই ও সহযোগী কে ছিলেন?"}', '{"options": [{"en": "Harun", "bn": "হারুন"}, {"en": "Yusha‘", "bn": "ইউশা"}, {"en": "Ilyas", "bn": "ইলিয়াস"}, {"en": "Shu‘ayb", "bn": "শুআইব"}], "correct": 0}', '{"en": "\"And appoint for me a helper from my family, Harun, my brother.\"", "bn": "\"আর আমার পরিবার থেকে আমার জন্য একজন সাহায্যকারী করে দিন, আমার ভাই হারুনকে।\""}', 'Quran 20:29–30', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('eca5dc9b-d4a1-5f26-9f3f-f3d3063b7987', 'bc29ccc9-f965-5d6d-8ed3-831b21db36f2', 'choice', '{"en": "Which prophet’s people had their cities turned upside down?", "bn": "কোন নবীর জাতির জনপদ উল্টে দেওয়া হয়েছিল?"}', '{"options": [{"en": "Lut", "bn": "লুত"}, {"en": "Nuh", "bn": "নুহ"}, {"en": "Musa", "bn": "মুসা"}, {"en": "Yunus", "bn": "ইউনুস"}], "correct": 0}', '{"en": "\"…We made the highest part of it its lowest.\"", "bn": "\"…আমি তার উপরিভাগকে নিচে করে দিলাম।\""}', 'Quran 11:82', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('df3c7c27-f9e7-524c-add4-be32bcf0f4e8', 'bc29ccc9-f965-5d6d-8ed3-831b21db36f2', 'choice', '{"en": "How many prophets are named in the Quran?", "bn": "কুরআনে কতজন নবীর নাম আছে?"}', '{"options": [{"en": "10", "bn": "১০"}, {"en": "25", "bn": "২৫"}, {"en": "40", "bn": "৪০"}, {"en": "124", "bn": "১২৪"}], "correct": 1}', '{"en": "Twenty-five prophets are mentioned by name.", "bn": "পঁচিশজন নবীর নাম উল্লেখ আছে।"}', NULL, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('fb443f2e-eceb-5c6a-bc96-2844a88075b7', 'bc29ccc9-f965-5d6d-8ed3-831b21db36f2', 'choice', '{"en": "Who was called \"Khalilullah\", the close friend of Allah?", "bn": "কাকে \"খলিলুল্লাহ\" (আল্লাহর অন্তরঙ্গ বন্ধু) বলা হয়?"}', '{"options": [{"en": "Ibrahim", "bn": "ইবরাহিম"}, {"en": "Musa", "bn": "মুসা"}, {"en": "Isa", "bn": "ঈসা"}, {"en": "Nuh", "bn": "নুহ"}], "correct": 0}', '{"en": "\"And Allah took Ibrahim as an intimate friend.\"", "bn": "\"আর আল্লাহ ইবরাহিমকে অন্তরঙ্গ বন্ধু হিসেবে গ্রহণ করেছেন।\""}', 'Quran 4:125', 5) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_lessons (id, unit_id, title, kind, sort_order) VALUES ('a660cbec-1394-5d9f-9eb3-e06104fb89db', 'af9e8c14-2f77-59f6-9a41-81d3e85a4621', '{"en": "Unit review", "bn": "ইউনিট রিভিউ"}', 'checkpoint', 3) ON CONFLICT (id) DO NOTHING;
