INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('54b59b58-50a6-59a3-824e-4afaed1ca065', 'a660cbec-1394-5d9f-9eb3-e06104fb89db', 'choice', '{"en": "Whose staff turned into a snake?", "bn": "কার লাঠি সাপে পরিণত হয়েছিল?"}', '{"options": [{"en": "Musa", "bn": "মুসা"}, {"en": "Isa", "bn": "ঈসা"}, {"en": "Sulayman", "bn": "সুলাইমান"}, {"en": "Ibrahim", "bn": "ইবরাহিম"}], "correct": 0}', '{"en": "\"So he threw it, and at once it was a snake, moving swiftly.\"", "bn": "\"অতঃপর তিনি তা নিক্ষেপ করলেন, আর তা হয়ে গেল ছুটন্ত সাপ।\""}', 'Quran 20:20', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('d7348e55-7266-5186-9b08-a2f860c4c9f6', 'a660cbec-1394-5d9f-9eb3-e06104fb89db', 'choice', '{"en": "Which prophet was sent to the people of Madyan?", "bn": "মাদইয়ানবাসীর কাছে কোন নবী প্রেরিত হন?"}', '{"options": [{"en": "Shu‘ayb", "bn": "শুআইব"}, {"en": "Salih", "bn": "সালিহ"}, {"en": "Hud", "bn": "হুদ"}, {"en": "Lut", "bn": "লুত"}], "correct": 0}', '{"en": "He told them to give full measure and weight.", "bn": "তিনি তাদের মাপ ও ওজন পূর্ণ দিতে বলেছিলেন।"}', 'Quran 7:85', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('1434bf5b-8c11-574e-bc01-d5544c5634d1', 'a660cbec-1394-5d9f-9eb3-e06104fb89db', 'choice', '{"en": "Which prophet’s people had their cities turned upside down?", "bn": "কোন নবীর জাতির জনপদ উল্টে দেওয়া হয়েছিল?"}', '{"options": [{"en": "Lut", "bn": "লুত"}, {"en": "Nuh", "bn": "নুহ"}, {"en": "Musa", "bn": "মুসা"}, {"en": "Yunus", "bn": "ইউনুস"}], "correct": 0}', '{"en": "\"…We made the highest part of it its lowest.\"", "bn": "\"…আমি তার উপরিভাগকে নিচে করে দিলাম।\""}', 'Quran 11:82', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('9ef1d345-b807-52bf-8588-ed4c3fdf96d5', 'a660cbec-1394-5d9f-9eb3-e06104fb89db', 'choice', '{"en": "Who was called \"Khalilullah\", the close friend of Allah?", "bn": "কাকে \"খলিলুল্লাহ\" (আল্লাহর অন্তরঙ্গ বন্ধু) বলা হয়?"}', '{"options": [{"en": "Ibrahim", "bn": "ইবরাহিম"}, {"en": "Musa", "bn": "মুসা"}, {"en": "Isa", "bn": "ঈসা"}, {"en": "Nuh", "bn": "নুহ"}], "correct": 0}', '{"en": "\"And Allah took Ibrahim as an intimate friend.\"", "bn": "\"আর আল্লাহ ইবরাহিমকে অন্তরঙ্গ বন্ধু হিসেবে গ্রহণ করেছেন।\""}', 'Quran 4:125', 5) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('40eeeda3-ad16-5b9a-bfe3-23d89a99b82a', 'a660cbec-1394-5d9f-9eb3-e06104fb89db', 'choice', '{"en": "Who was the father of Prophet Yusuf?", "bn": "ইউসুফ (আ.)-এর পিতা কে?"}', '{"options": [{"en": "Ya‘qub", "bn": "ইয়াকুব"}, {"en": "Ishaq", "bn": "ইসহাক"}, {"en": "Ibrahim", "bn": "ইবরাহিম"}, {"en": "Isma‘il", "bn": "ইসমাইল"}], "correct": 0}', '{"en": "Ya‘qub, son of Ishaq, son of Ibrahim.", "bn": "ইয়াকুব, ইসহাকের পুত্র, যিনি ইবরাহিমের পুত্র।"}', 'Quran 12:4–6', 6) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_units (id, title, description, color, icon, review_status, sort_order, section_id) VALUES ('53a2b8d5-d112-5a2d-bd87-9e0d44457bd9', '{"en": "Prophets of Allah — part 3", "bn": "আল্লাহর নবী-রাসুলগণ — পর্ব ৩"}', '{}', '#e1b12c', 'users', 'in_review', 3, '07bf5aab-bcbb-5c29-8531-e6ef84bd48e7') ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_lessons (id, unit_id, title, kind, sort_order) VALUES ('219d7c48-b624-548d-ad1c-1d00012ec660', '53a2b8d5-d112-5a2d-bd87-9e0d44457bd9', '{"en": "Part 1", "bn": "পর্ব ১"}', 'lesson', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('07fe44e3-3b47-5801-81d6-6972bea8918d', '219d7c48-b624-548d-ad1c-1d00012ec660', 'choice', '{"en": "Which prophet’s whole people believed and were spared the punishment?", "bn": "কোন নবীর পুরো জাতি ঈমান এনে শাস্তি থেকে রক্ষা পায়?"}', '{"options": [{"en": "Yunus", "bn": "ইউনুস"}, {"en": "Nuh", "bn": "নুহ"}, {"en": "Hud", "bn": "হুদ"}, {"en": "Salih", "bn": "সালিহ"}], "correct": 0}', '{"en": "\"…except the people of Yunus; when they believed, We removed from them the punishment.\"", "bn": "\"…ইউনুসের জাতি ছাড়া; যখন তারা ঈমান আনল, আমি তাদের থেকে শাস্তি সরিয়ে নিলাম।\""}', 'Quran 10:98', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('9bb41e38-8550-5d8b-999f-4da49580028b', '219d7c48-b624-548d-ad1c-1d00012ec660', 'choice', '{"en": "Which prophet was a carpenter?", "bn": "কোন নবী কাঠমিস্ত্রি ছিলেন?"}', '{"options": [{"en": "Zakariyya", "bn": "যাকারিয়া"}, {"en": "Dawud", "bn": "দাউদ"}, {"en": "Idris", "bn": "ইদরিস"}, {"en": "Musa", "bn": "মুসা"}], "correct": 0}', '{"en": "\"Zakariyya was a carpenter.\"", "bn": "\"যাকারিয়া কাঠমিস্ত্রি ছিলেন।\""}', 'Sahih Muslim 2379', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('d7ff0d87-fdbf-5875-a0f5-533c0c7e9165', '219d7c48-b624-548d-ad1c-1d00012ec660', 'choice', '{"en": "Which prophet was taught to make armour?", "bn": "কোন নবীকে বর্ম বানানো শেখানো হয়েছিল?"}', '{"options": [{"en": "Dawud", "bn": "দাউদ"}, {"en": "Nuh", "bn": "নুহ"}, {"en": "Yusuf", "bn": "ইউসুফ"}, {"en": "Ibrahim", "bn": "ইবরাহিম"}], "correct": 0}', '{"en": "\"And We taught him the making of coats of armour for you.\"", "bn": "\"আর আমি তাকে তোমাদের জন্য বর্ম তৈরি শিখিয়েছিলাম।\""}', 'Quran 21:80', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('38d40692-978c-5568-ba66-58b1b364430f', '219d7c48-b624-548d-ad1c-1d00012ec660', 'choice', '{"en": "Which prophet interpreted the king’s dream of seven fat cows?", "bn": "কোন নবী রাজার সাতটি মোটা গাভীর স্বপ্নের ব্যাখ্যা দেন?"}', '{"options": [{"en": "Yusuf", "bn": "ইউসুফ"}, {"en": "Musa", "bn": "মুসা"}, {"en": "Danyal", "bn": "দানিয়েল"}, {"en": "Sulayman", "bn": "সুলাইমান"}], "correct": 0}', '{"en": "Seven years of plenty, then seven of drought.", "bn": "সাত বছর প্রাচুর্য, তারপর সাত বছর খরা।"}', 'Quran 12:43–49', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('37f64103-50d9-55b9-8183-64af2b892e71', '219d7c48-b624-548d-ad1c-1d00012ec660', 'choice', '{"en": "Who made the golden calf while Musa was away?", "bn": "মুসার অনুপস্থিতিতে সোনার বাছুর কে বানিয়েছিল?"}', '{"options": [{"en": "As-Samiri", "bn": "সামেরি"}, {"en": "Harun", "bn": "হারুন"}, {"en": "Qarun", "bn": "কারুন"}, {"en": "Haman", "bn": "হামান"}], "correct": 0}', '{"en": "\"…and the Samiri led them astray.\"", "bn": "\"…আর সামেরি তাদের পথভ্রষ্ট করেছে।\""}', 'Quran 20:85–88', 5) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_lessons (id, unit_id, title, kind, sort_order) VALUES ('b8760b35-9e2a-5bdd-80b2-939650b877ad', '53a2b8d5-d112-5a2d-bd87-9e0d44457bd9', '{"en": "Part 2", "bn": "পর্ব ২"}', 'lesson', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('1c2795cc-ce8a-5675-9739-d71b8972f435', 'b8760b35-9e2a-5bdd-80b2-939650b877ad', 'choice', '{"en": "Which prophet was raised up to Allah and not crucified?", "bn": "কোন নবীকে আল্লাহ নিজের কাছে তুলে নিয়েছেন, তাঁকে ক্রুশবিদ্ধ করা হয়নি?"}', '{"options": [{"en": "Isa", "bn": "ঈসা"}, {"en": "Yahya", "bn": "ইয়াহইয়া"}, {"en": "Idris", "bn": "ইদরিস"}, {"en": "Ilyas", "bn": "ইলিয়াস"}], "correct": 0}', '{"en": "\"…they did not kill him, nor crucify him… rather Allah raised him to Himself.\"", "bn": "\"…তারা তাকে হত্যা করেনি, ক্রুশবিদ্ধও করেনি… বরং আল্লাহ তাকে নিজের কাছে তুলে নিয়েছেন।\""}', 'Quran 4:157–158', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('eb490dc4-fb56-5412-b3c1-570251fa6023', 'b8760b35-9e2a-5bdd-80b2-939650b877ad', 'choice', '{"en": "Which prophet was given wisdom while still a child?", "bn": "কোন নবীকে শিশু অবস্থাতেই প্রজ্ঞা দেওয়া হয়েছিল?"}', '{"options": [{"en": "Yahya", "bn": "ইয়াহইয়া"}, {"en": "Harun", "bn": "হারুন"}, {"en": "Lut", "bn": "লুত"}, {"en": "Hud", "bn": "হুদ"}], "correct": 0}', '{"en": "\"…and We gave him wisdom while still a child.\"", "bn": "\"…আর আমি তাকে শৈশবেই প্রজ্ঞা দান করেছিলাম।\""}', 'Quran 19:12', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('ce5cc17f-a9bb-5e72-bf69-a53628476e94', 'b8760b35-9e2a-5bdd-80b2-939650b877ad', 'choice', '{"en": "About which prophet does the Quran say \"We raised him to a high station\"?", "bn": "কোন নবী সম্পর্কে কুরআন বলে \"আমি তাকে উচ্চ মর্যাদায় উন্নীত করেছি\"?"}', '{"options": [{"en": "Idris", "bn": "ইদরিস"}, {"en": "Shu‘ayb", "bn": "শুআইব"}, {"en": "Ayyub", "bn": "আইয়ুব"}, {"en": "Lut", "bn": "লুত"}], "correct": 0}', '{"en": "\"And mention in the Book Idris… and We raised him to a high station.\"", "bn": "\"আর কিতাবে ইদরিসের কথা স্মরণ করো… আর আমি তাকে উচ্চ মর্যাদায় উন্নীত করেছি।\""}', 'Quran 19:56–57', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('6856cbdd-b064-5cfe-bdbc-8d2158841b3a', 'b8760b35-9e2a-5bdd-80b2-939650b877ad', 'choice', '{"en": "Which prophet’s son refused to board the Ark?", "bn": "কোন নবীর ছেলে নৌকায় উঠতে অস্বীকার করেছিল?"}', '{"options": [{"en": "Nuh", "bn": "নুহ"}, {"en": "Ibrahim", "bn": "ইবরাহিম"}, {"en": "Ya‘qub", "bn": "ইয়াকুব"}, {"en": "Lut", "bn": "লুত"}], "correct": 0}', '{"en": "\"…I will take refuge on a mountain to protect me from the water.\"", "bn": "\"…আমি এক পাহাড়ে আশ্রয় নেব, যা আমাকে পানি থেকে রক্ষা করবে।\""}', 'Quran 11:42–43', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('0a9ac5a5-e0e7-5d1c-997e-3f4677280e74', 'b8760b35-9e2a-5bdd-80b2-939650b877ad', 'choice', '{"en": "Which prophet had the wind made subject to him?", "bn": "কোন নবীর জন্য বাতাসকে অনুগত করা হয়েছিল?"}', '{"options": [{"en": "Sulayman", "bn": "সুলাইমান"}, {"en": "Musa", "bn": "মুসা"}, {"en": "Hud", "bn": "হুদ"}, {"en": "Nuh", "bn": "নুহ"}], "correct": 0}', '{"en": "\"And to Sulayman (We subjected) the wind, blowing forcefully at his command.\"", "bn": "\"আর সুলাইমানের জন্য (অনুগত করেছিলাম) প্রবল বাতাস, যা তার আদেশে বইত।\""}', 'Quran 21:81', 5) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_lessons (id, unit_id, title, kind, sort_order) VALUES ('e77d9943-9e46-588e-99b1-f67c7d5a797a', '53a2b8d5-d112-5a2d-bd87-9e0d44457bd9', '{"en": "Unit review", "bn": "ইউনিট রিভিউ"}', 'checkpoint', 3) ON CONFLICT (id) DO NOTHING;
