INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('71d49a33-7fd2-5568-a1da-e553eb9d626e', 'e77d9943-9e46-588e-99b1-f67c7d5a797a', 'choice', '{"en": "Which prophet interpreted the king’s dream of seven fat cows?", "bn": "কোন নবী রাজার সাতটি মোটা গাভীর স্বপ্নের ব্যাখ্যা দেন?"}', '{"options": [{"en": "Yusuf", "bn": "ইউসুফ"}, {"en": "Musa", "bn": "মুসা"}, {"en": "Danyal", "bn": "দানিয়েল"}, {"en": "Sulayman", "bn": "সুলাইমান"}], "correct": 0}', '{"en": "Seven years of plenty, then seven of drought.", "bn": "সাত বছর প্রাচুর্য, তারপর সাত বছর খরা।"}', 'Quran 12:43–49', 2) ON CONFLICT (id) DO NOTHING;
