INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('61f66710-6436-55f8-9c2c-3ff051925842', 'e77d9943-9e46-588e-99b1-f67c7d5a797a', 'choice', '{"en": "About which prophet does the Quran say \"We raised him to a high station\"?", "bn": "কোন নবী সম্পর্কে কুরআন বলে \"আমি তাকে উচ্চ মর্যাদায় উন্নীত করেছি\"?"}', '{"options": [{"en": "Idris", "bn": "ইদরিস"}, {"en": "Shu‘ayb", "bn": "শুআইব"}, {"en": "Ayyub", "bn": "আইয়ুব"}, {"en": "Lut", "bn": "লুত"}], "correct": 0}', '{"en": "\"And mention in the Book Idris… and We raised him to a high station.\"", "bn": "\"আর কিতাবে ইদরিসের কথা স্মরণ করো… আর আমি তাকে উচ্চ মর্যাদায় উন্নীত করেছি।\""}', 'Quran 19:56–57', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('504e3141-122e-5cbb-a1b7-a984d3d507d7', 'e77d9943-9e46-588e-99b1-f67c7d5a797a', 'choice', '{"en": "Which prophet had the wind made subject to him?", "bn": "কোন নবীর জন্য বাতাসকে অনুগত করা হয়েছিল?"}', '{"options": [{"en": "Sulayman", "bn": "সুলাইমান"}, {"en": "Musa", "bn": "মুসা"}, {"en": "Hud", "bn": "হুদ"}, {"en": "Nuh", "bn": "নুহ"}], "correct": 0}', '{"en": "\"And to Sulayman (We subjected) the wind, blowing forcefully at his command.\"", "bn": "\"আর সুলাইমানের জন্য (অনুগত করেছিলাম) প্রবল বাতাস, যা তার আদেশে বইত।\""}', 'Quran 21:81', 5) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('a53fff1f-64d9-55e6-b3a3-997a7b7da6fd', 'e77d9943-9e46-588e-99b1-f67c7d5a797a', 'choice', '{"en": "Which prophet’s whole people believed and were spared the punishment?", "bn": "কোন নবীর পুরো জাতি ঈমান এনে শাস্তি থেকে রক্ষা পায়?"}', '{"options": [{"en": "Yunus", "bn": "ইউনুস"}, {"en": "Nuh", "bn": "নুহ"}, {"en": "Hud", "bn": "হুদ"}, {"en": "Salih", "bn": "সালিহ"}], "correct": 0}', '{"en": "\"…except the people of Yunus; when they believed, We removed from them the punishment.\"", "bn": "\"…ইউনুসের জাতি ছাড়া; যখন তারা ঈমান আনল, আমি তাদের থেকে শাস্তি সরিয়ে নিলাম।\""}', 'Quran 10:98', 6) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_units (id, title, description, color, icon, review_status, sort_order, section_id) VALUES ('886e56ac-7e84-53d4-af10-86f08558c56f', '{"en": "Life of the Prophet ﷺ", "bn": "নবীজির ﷺ জীবনী"}', '{}', '#e1b12c', 'users', 'in_review', 1, '3fd6bdd2-2a56-50a5-884d-234f2d4784f7') ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_lessons (id, unit_id, title, kind, sort_order) VALUES ('49a25df2-9894-5fb3-ab76-8fca84a4cc0d', '886e56ac-7e84-53d4-af10-86f08558c56f', '{"en": "Part 1", "bn": "পর্ব ১"}', 'lesson', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('81558192-6d8f-589b-9fda-3934ee093e71', '49a25df2-9894-5fb3-ab76-8fca84a4cc0d', 'choice', '{"en": "In which city was the Prophet ﷺ born?", "bn": "নবী ﷺ কোন শহরে জন্মগ্রহণ করেন?"}', '{"options": [{"en": "Madinah", "bn": "মদিনা"}, {"en": "Makkah", "bn": "মক্কা"}, {"en": "Ta’if", "bn": "তায়েফ"}, {"en": "Jerusalem", "bn": "জেরুজালেম"}], "correct": 1}', '{"en": "He ﷺ was born in Makkah.", "bn": "তিনি ﷺ মক্কায় জন্মগ্রহণ করেন।"}', NULL, 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('4391fa9e-f6b2-5b90-94e9-3c308f9cccb7', '49a25df2-9894-5fb3-ab76-8fca84a4cc0d', 'choice', '{"en": "He ﷺ was born in the \"Year of the…\"?", "bn": "তিনি ﷺ জন্মগ্রহণ করেন কোন \"বছরে\"?"}', '{"options": [{"en": "Flood", "bn": "প্লাবনের"}, {"en": "Elephant", "bn": "হাতির"}, {"en": "Famine", "bn": "দুর্ভিক্ষের"}, {"en": "Treaty", "bn": "চুক্তির"}], "correct": 1}', '{"en": "The year Abraha’s army with elephants came to destroy the Ka‘bah (see surah al-Fil).", "bn": "যে বছর আবরাহার হস্তীবাহিনী কাবা ধ্বংস করতে এসেছিল (সূরা আল-ফিল)।"}', 'Quran 105', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('e8f39034-9c7e-53a8-b67c-32548efbfa96', '49a25df2-9894-5fb3-ab76-8fca84a4cc0d', 'choice', '{"en": "What was the name of his mother?", "bn": "তাঁর মায়ের নাম কী ছিল?"}', '{"options": [{"en": "Halimah", "bn": "হালিমা"}, {"en": "Aminah", "bn": "আমিনা"}, {"en": "Khadijah", "bn": "খাদিজা"}, {"en": "Fatimah", "bn": "ফাতিমা"}], "correct": 1}', '{"en": "Aminah bint Wahb.", "bn": "আমিনা বিনতে ওয়াহাব।"}', NULL, 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('bc72077c-64cf-528b-a755-0f7d0fba6163', '49a25df2-9894-5fb3-ab76-8fca84a4cc0d', 'choice', '{"en": "Who was his first wife?", "bn": "তাঁর প্রথম স্ত্রী কে ছিলেন?"}', '{"options": [{"en": "‘A’ishah", "bn": "আয়েশা"}, {"en": "Khadijah", "bn": "খাদিজা"}, {"en": "Hafsah", "bn": "হাফসা"}, {"en": "Sawdah", "bn": "সাওদা"}], "correct": 1}', '{"en": "Khadijah bint Khuwaylid, the first to believe in him.", "bn": "খাদিজা বিনতে খুয়াইলিদ, যিনি সবার আগে তাঁর প্রতি ঈমান আনেন।"}', 'Sahih al-Bukhari 3', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('5dd74fa7-4978-5029-8727-37edd5ce7696', '49a25df2-9894-5fb3-ab76-8fca84a4cc0d', 'choice', '{"en": "Where did the first revelation come to him?", "bn": "প্রথম ওহি কোথায় এসেছিল?"}', '{"options": [{"en": "Cave of Thawr", "bn": "সাওর গুহা"}, {"en": "Cave of Hira", "bn": "হেরা গুহা"}, {"en": "Mount Uhud", "bn": "উহুদ পাহাড়"}, {"en": "The Ka‘bah", "bn": "কাবা"}], "correct": 1}', '{"en": "He ﷺ used to worship in the cave of Hira, where Jibril came to him.", "bn": "তিনি ﷺ হেরা গুহায় ইবাদত করতেন; সেখানেই জিবরাইল আসেন।"}', 'Sahih al-Bukhari 3', 5) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_lessons (id, unit_id, title, kind, sort_order) VALUES ('97791085-7dd1-5794-b3c5-73e11ee687cb', '886e56ac-7e84-53d4-af10-86f08558c56f', '{"en": "Part 2", "bn": "পর্ব ২"}', 'lesson', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('4ca83c5a-e930-5778-80e1-d466ed8dd9fb', '97791085-7dd1-5794-b3c5-73e11ee687cb', 'choice', '{"en": "To which city did the Prophet ﷺ make Hijrah?", "bn": "নবী ﷺ কোন শহরে হিজরত করেন?"}', '{"options": [{"en": "Ta’if", "bn": "তায়েফ"}, {"en": "Madinah", "bn": "মদিনা"}, {"en": "Abyssinia", "bn": "হাবশা"}, {"en": "Damascus", "bn": "দামেস্ক"}], "correct": 1}', '{"en": "Yathrib, which became al-Madinah.", "bn": "ইয়াসরিব, যা পরে মদিনা নামে পরিচিত হয়।"}', NULL, 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('ed25a19d-dc72-56b2-9003-687c50f8fc72', '97791085-7dd1-5794-b3c5-73e11ee687cb', 'choice', '{"en": "Who was with him in the cave during the Hijrah?", "bn": "হিজরতের সময় গুহায় তাঁর সাথে কে ছিলেন?"}', '{"options": [{"en": "‘Umar", "bn": "উমর"}, {"en": "‘Ali", "bn": "আলী"}, {"en": "Abu Bakr", "bn": "আবু বকর"}, {"en": "‘Uthman", "bn": "উসমান"}], "correct": 2}', '{"en": "\"…the second of two, when they were in the cave…\"", "bn": "\"…দুজনের দ্বিতীয়জন, যখন তারা গুহায় ছিলেন…\""}', 'Quran 9:40', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('2a91aeb8-4d06-5b9a-9c0d-20f5bf599aa1', '97791085-7dd1-5794-b3c5-73e11ee687cb', 'choice', '{"en": "What was the first major battle of Islam?", "bn": "ইসলামের প্রথম বড় যুদ্ধ কোনটি?"}', '{"options": [{"en": "Uhud", "bn": "উহুদ"}, {"en": "Badr", "bn": "বদর"}, {"en": "The Trench", "bn": "খন্দক"}, {"en": "Hunayn", "bn": "হুনাইন"}], "correct": 1}', '{"en": "Badr, in Ramadan of 2 AH.", "bn": "বদর, হিজরি দ্বিতীয় সনের রমজানে।"}', 'Quran 3:123', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('f4bbff32-153d-50e0-ab34-dad6594dc0a8', '97791085-7dd1-5794-b3c5-73e11ee687cb', 'choice', '{"en": "In which year after the Hijrah was Makkah conquered?", "bn": "হিজরতের কত বছর পর মক্কা বিজয় হয়?"}', '{"options": [{"en": "2 AH", "bn": "হিজরি ২"}, {"en": "5 AH", "bn": "হিজরি ৫"}, {"en": "8 AH", "bn": "হিজরি ৮"}, {"en": "10 AH", "bn": "হিজরি ১০"}], "correct": 2}', '{"en": "Makkah was opened in Ramadan, 8 AH.", "bn": "হিজরি ৮ সনের রমজানে মক্কা বিজয় হয়।"}', NULL, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('9bfe3f96-e293-540e-8786-17b0dce8fd7e', '97791085-7dd1-5794-b3c5-73e11ee687cb', 'choice', '{"en": "Where is the Prophet ﷺ buried?", "bn": "নবী ﷺ কোথায় সমাহিত?"}', '{"options": [{"en": "Makkah", "bn": "মক্কা"}, {"en": "Madinah", "bn": "মদিনা"}, {"en": "Jerusalem", "bn": "জেরুজালেম"}, {"en": "Ta’if", "bn": "তায়েফ"}], "correct": 1}', '{"en": "In Madinah, in what is now part of his masjid.", "bn": "মদিনায়, যা এখন তাঁর মসজিদের অংশ।"}', NULL, 5) ON CONFLICT (id) DO NOTHING;
