INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('c1034f28-2ea8-5db1-a11a-df44115cd21f', 'e011dee6-47aa-57b7-9219-c423805bd076', 'choice', '{"en": "What was the name of the Prophet’s ﷺ father?", "bn": "নবীজির ﷺ পিতার নাম কী?"}', '{"options": [{"en": "‘Abdullah", "bn": "আবদুল্লাহ"}, {"en": "Abu Talib", "bn": "আবু তালিব"}, {"en": "‘Abd al-Muttalib", "bn": "আবদুল মুত্তালিব"}, {"en": "Hamzah", "bn": "হামজা"}], "correct": 0}', '{"en": "‘Abdullah ibn ‘Abd al-Muttalib, who died before the Prophet ﷺ was born.", "bn": "আবদুল্লাহ ইবনে আবদুল মুত্তালিব, নবীজির জন্মের আগেই ইন্তেকাল করেন।"}', NULL, 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('6b6cbe30-093f-52ae-a59a-8179f6dc2c21', 'e011dee6-47aa-57b7-9219-c423805bd076', 'choice', '{"en": "Which grandfather looked after him as a child?", "bn": "শৈশবে কোন দাদা তাঁর দেখাশোনা করেন?"}', '{"options": [{"en": "‘Abd al-Muttalib", "bn": "আবদুল মুত্তালিব"}, {"en": "Hashim", "bn": "হাশিম"}, {"en": "Qusayy", "bn": "কুসাই"}, {"en": "Abu Lahab", "bn": "আবু লাহাব"}], "correct": 0}', '{"en": "After his mother died, his grandfather ‘Abd al-Muttalib, then his uncle Abu Talib.", "bn": "মায়ের মৃত্যুর পর দাদা আবদুল মুত্তালিব, তারপর চাচা আবু তালিব।"}', NULL, 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('30679558-9fd1-5d96-84b4-ba36ea6052cd', 'e011dee6-47aa-57b7-9219-c423805bd076', 'choice', '{"en": "Which uncle protected him in Makkah?", "bn": "কোন চাচা মক্কায় তাঁকে রক্ষা করেছিলেন?"}', '{"options": [{"en": "Abu Talib", "bn": "আবু তালিব"}, {"en": "Abu Lahab", "bn": "আবু লাহাব"}, {"en": "Abu Jahl", "bn": "আবু জাহল"}, {"en": "Abu Sufyan", "bn": "আবু সুফিয়ান"}], "correct": 0}', '{"en": "Abu Talib protected him until his death in the \"Year of Sorrow\".", "bn": "আবু তালিব \"দুঃখের বছরে\" মৃত্যু পর্যন্ত তাঁকে রক্ষা করেন।"}', NULL, 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('67d62619-2bf4-5328-a433-5d0c30a6c6ae', 'e011dee6-47aa-57b7-9219-c423805bd076', 'choice', '{"en": "How old was he when the first revelation came?", "bn": "প্রথম ওহির সময় তাঁর বয়স কত ছিল?"}', '{"options": [{"en": "25", "bn": "২৫"}, {"en": "30", "bn": "৩০"}, {"en": "40", "bn": "৪০"}, {"en": "53", "bn": "৫৩"}], "correct": 2}', '{"en": "Revelation began when he was forty.", "bn": "চল্লিশ বছর বয়সে ওহি শুরু হয়।"}', 'Sahih al-Bukhari 3851', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('90d6f923-589e-5e22-b7ff-d33c338e39ea', 'e011dee6-47aa-57b7-9219-c423805bd076', 'choice', '{"en": "Which treaty was made with Quraysh in 6 AH?", "bn": "হিজরি ৬ সনে কুরাইশের সাথে কোন সন্ধি হয়?"}', '{"options": [{"en": "Hudaybiyyah", "bn": "হুদাইবিয়া"}, {"en": "‘Aqabah", "bn": "আকাবা"}, {"en": "Madinah", "bn": "মদিনা"}, {"en": "Ta’if", "bn": "তায়েফ"}], "correct": 0}', '{"en": "The treaty of Hudaybiyyah, called \"a clear victory\".", "bn": "হুদাইবিয়ার সন্ধি, যাকে \"সুস্পষ্ট বিজয়\" বলা হয়েছে।"}', 'Quran 48:1', 5) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_lessons (id, unit_id, title, kind, sort_order) VALUES ('0598a253-335c-5f5e-80d6-9e4cf1fc4899', '5f9cad71-9359-5877-ac91-733c8e7350d4', '{"en": "Part 2", "bn": "পর্ব ২"}', 'lesson', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('8f8ee23e-e46f-5c42-9b41-064f84c1f85c', '0598a253-335c-5f5e-80d6-9e4cf1fc4899', 'choice', '{"en": "In which battle did archers leave their posts?", "bn": "কোন যুদ্ধে তীরন্দাজরা তাদের অবস্থান ছেড়েছিল?"}', '{"options": [{"en": "Badr", "bn": "বদর"}, {"en": "Uhud", "bn": "উহুদ"}, {"en": "Khandaq", "bn": "খন্দক"}, {"en": "Khaybar", "bn": "খায়বার"}], "correct": 1}', '{"en": "At Uhud, leaving the hill turned the battle.", "bn": "উহুদে টিলা ছেড়ে যাওয়ায় যুদ্ধের মোড় ঘুরে যায়।"}', 'Quran 3:152; Sahih al-Bukhari 3039', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('8b9bf97f-f6b7-5a02-9580-eeef6d157307', '0598a253-335c-5f5e-80d6-9e4cf1fc4899', 'choice', '{"en": "The Battle of the Trench is also called…?", "bn": "খন্দকের যুদ্ধের আরেক নাম কী?"}', '{"options": [{"en": "Al-Ahzab (the Confederates)", "bn": "আল-আহযাব (সম্মিলিত বাহিনী)"}, {"en": "Hunayn", "bn": "হুনাইন"}, {"en": "Tabuk", "bn": "তাবুক"}, {"en": "Mu’tah", "bn": "মুতা"}], "correct": 0}', '{"en": "Surah al-Ahzab describes it.", "bn": "সূরা আল-আহযাবে এর বর্ণনা আছে।"}', 'Quran 33:9–25', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('59c6b06b-3d39-5111-ac03-58bb5d485bda', '0598a253-335c-5f5e-80d6-9e4cf1fc4899', 'choice', '{"en": "The \"Year of Sorrow\" was when he lost…?", "bn": "\"দুঃখের বছরে\" তিনি কাদের হারান?"}', '{"options": [{"en": "Khadijah and Abu Talib", "bn": "খাদিজা ও আবু তালিব"}, {"en": "Hamzah and Ja‘far", "bn": "হামজা ও জাফর"}, {"en": "His parents", "bn": "তাঁর বাবা-মা"}, {"en": "His sons", "bn": "তাঁর পুত্রগণ"}], "correct": 0}', '{"en": "Both died in the same year, before the Hijrah.", "bn": "হিজরতের আগে একই বছরে দুজনই ইন্তেকাল করেন।"}', NULL, 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('f8abb431-7fe4-5da7-84ee-e5ff54672d9b', '0598a253-335c-5f5e-80d6-9e4cf1fc4899', 'choice', '{"en": "In which year was the Farewell Hajj?", "bn": "বিদায় হজ কোন বছর হয়?"}', '{"options": [{"en": "8 AH", "bn": "হিজরি ৮"}, {"en": "9 AH", "bn": "হিজরি ৯"}, {"en": "10 AH", "bn": "হিজরি ১০"}, {"en": "11 AH", "bn": "হিজরি ১১"}], "correct": 2}', '{"en": "10 AH; he ﷺ passed away in 11 AH.", "bn": "হিজরি ১০ সনে; তিনি ﷺ হিজরি ১১ সনে ইন্তেকাল করেন।"}', NULL, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('bd97b356-4e47-5785-b4ba-63a3c88089a0', '0598a253-335c-5f5e-80d6-9e4cf1fc4899', 'choice', '{"en": "Which town’s people stoned him when he invited them to Islam?", "bn": "কোন শহরের লোকেরা ইসলামের দাওয়াত দেওয়ায় তাঁকে পাথর মেরেছিল?"}', '{"options": [{"en": "Ta’if", "bn": "তায়েফ"}, {"en": "Yathrib", "bn": "ইয়াসরিব"}, {"en": "Jeddah", "bn": "জেদ্দা"}, {"en": "Khaybar", "bn": "খায়বার"}], "correct": 0}', '{"en": "At Ta’if he was hurt, yet he prayed for their descendants.", "bn": "তায়েফে আহত হয়েও তিনি তাদের বংশধরদের জন্য দোয়া করেন।"}', 'Sahih al-Bukhari 3231', 5) ON CONFLICT (id) DO NOTHING;
