INSERT INTO is_learn_lessons (id, unit_id, title, kind, sort_order) VALUES ('8b7257bd-5e67-55e8-91d6-b61168b33d23', 'd1afa718-24ac-52cd-8b7a-066c12b0b8ed', '{"en": "Part 1", "bn": "পর্ব ১"}', 'lesson', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('cf32cb2f-b92d-5ff5-a461-720c7c254561', '8b7257bd-5e67-55e8-91d6-b61168b33d23', 'choice', '{"en": "Laylat al-Qadr is better than how many months?", "bn": "লাইলাতুল কদর কত মাসের চেয়ে উত্তম?"}', '{"options": [{"en": "100", "bn": "১০০"}, {"en": "1,000", "bn": "১,০০০"}, {"en": "70", "bn": "৭০"}, {"en": "12", "bn": "১২"}], "correct": 1}', '{"en": "\"The Night of Decree is better than a thousand months.\"", "bn": "\"কদরের রাত হাজার মাসের চেয়ে উত্তম।\""}', 'Quran 97:3', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('1c2a29d2-6673-5045-813d-36119f7a511e', '8b7257bd-5e67-55e8-91d6-b61168b33d23', 'choice', '{"en": "What is the pre-dawn meal before fasting called?", "bn": "রোজার আগে ভোররাতের খাবারকে কী বলে?"}', '{"options": [{"en": "Iftar", "bn": "ইফতার"}, {"en": "Suhur (Sehri)", "bn": "সেহরি"}, {"en": "Walimah", "bn": "ওয়ালিমা"}, {"en": "‘Aqiqah", "bn": "আকিকা"}], "correct": 1}', '{"en": "\"Take suhur, for in suhur there is blessing.\"", "bn": "\"সেহরি খাও, কারণ সেহরিতে বরকত আছে।\""}', 'Sahih al-Bukhari 1923', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('46ab9539-bde1-56aa-846e-5336d54d671e', '8b7257bd-5e67-55e8-91d6-b61168b33d23', 'choice', '{"en": "When should Zakat al-Fitr be given?", "bn": "সদকাতুল ফিতর কখন দিতে হয়?"}', '{"options": [{"en": "After Eid prayer", "bn": "ঈদের নামাজের পর"}, {"en": "Before the Eid prayer", "bn": "ঈদের নামাজের আগে"}, {"en": "In Muharram", "bn": "মহররমে"}, {"en": "Any time in the year", "bn": "বছরের যেকোনো সময়"}], "correct": 1}', '{"en": "The Prophet ﷺ ordered it to be given before people go out to the prayer.", "bn": "নবী ﷺ নামাজে বের হওয়ার আগেই তা আদায়ের নির্দেশ দিয়েছেন।"}', 'Sahih al-Bukhari 1503', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('53ebfb67-d790-5014-bd8f-1a362a727176', '8b7257bd-5e67-55e8-91d6-b61168b33d23', 'choice', '{"en": "What is the night prayer of Ramadan commonly called?", "bn": "রমজানের রাতের বিশেষ নামাজকে কী বলে?"}', '{"options": [{"en": "Tarawih", "bn": "তারাবিহ"}, {"en": "Duha", "bn": "দুহা"}, {"en": "Ishraq", "bn": "ইশরাক"}, {"en": "Istikharah", "bn": "ইস্তিখারা"}], "correct": 0}', '{"en": "Tarawih: whoever stands in Ramadan with faith and hoping for reward is forgiven his past sins.", "bn": "তারাবিহ: ঈমান ও সওয়াবের আশায় রমজানে রাত জেগে নামাজ পড়লে আগের গুনাহ মাফ হয়।"}', 'Sahih al-Bukhari 37', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('4edc6f62-53ba-558a-af79-535bb5d240ab', '8b7257bd-5e67-55e8-91d6-b61168b33d23', 'choice', '{"en": "Which surah is about Laylat al-Qadr?", "bn": "কোন সূরা লাইলাতুল কদর সম্পর্কে?"}', '{"options": [{"en": "Al-Qadr", "bn": "আল-কদর"}, {"en": "Al-Fajr", "bn": "আল-ফাজর"}, {"en": "Al-Layl", "bn": "আল-লাইল"}, {"en": "Ad-Duha", "bn": "আদ-দুহা"}], "correct": 0}', '{"en": "Surah al-Qadr (97).", "bn": "সূরা আল-কদর (৯৭)।"}', 'Quran 97', 5) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_lessons (id, unit_id, title, kind, sort_order) VALUES ('4fe20667-307a-59cb-9ea1-ae917176c6f1', 'd1afa718-24ac-52cd-8b7a-066c12b0b8ed', '{"en": "Part 2", "bn": "পর্ব ২"}', 'lesson', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('8a47f25b-c194-5fec-9c58-a2166fe9e474', '4fe20667-307a-59cb-9ea1-ae917176c6f1', 'choice', '{"en": "What is the Eid at the end of Ramadan called?", "bn": "রমজানের শেষে যে ঈদ, তার নাম কী?"}', '{"options": [{"en": "Eid al-Adha", "bn": "ঈদুল আযহা"}, {"en": "Eid al-Fitr", "bn": "ঈদুল ফিতর"}, {"en": "Mawlid", "bn": "মিলাদ"}, {"en": "Ashura", "bn": "আশুরা"}], "correct": 1}', '{"en": "Eid al-Fitr, on 1 Shawwal.", "bn": "ঈদুল ফিতর, ১ শাওয়াল।"}', NULL, 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('dae14d2c-0d61-50c2-9fbe-d422fa990266', '4fe20667-307a-59cb-9ea1-ae917176c6f1', 'choice', '{"en": "In which nights should Laylat al-Qadr be sought?", "bn": "লাইলাতুল কদর কোন রাতগুলোতে খুঁজতে বলা হয়েছে?"}', '{"options": [{"en": "The first ten nights", "bn": "প্রথম দশ রাত"}, {"en": "The odd nights of the last ten", "bn": "শেষ দশকের বেজোড় রাত"}, {"en": "Only the 15th night", "bn": "শুধু ১৫তম রাত"}, {"en": "Any night of the year", "bn": "বছরের যেকোনো রাত"}], "correct": 1}', '{"en": "\"Seek it in the odd nights of the last ten of Ramadan.\"", "bn": "\"রমজানের শেষ দশকের বেজোড় রাতগুলোতে তা খোঁজো।\""}', 'Sahih al-Bukhari 2017', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('ef770a32-c39a-58be-b2c9-463f8f0dff08', '4fe20667-307a-59cb-9ea1-ae917176c6f1', 'choice', '{"en": "With what did the Prophet ﷺ prefer to break his fast?", "bn": "নবী ﷺ কী দিয়ে ইফতার করতে পছন্দ করতেন?"}', '{"options": [{"en": "Fresh or dry dates", "bn": "তাজা বা শুকনো খেজুর"}, {"en": "Milk", "bn": "দুধ"}, {"en": "Bread", "bn": "রুটি"}, {"en": "Honey", "bn": "মধু"}], "correct": 0}', '{"en": "Fresh dates, else dry dates, else a few sips of water.", "bn": "তাজা খেজুর, না থাকলে শুকনো খেজুর, তাও না থাকলে কয়েক চুমুক পানি।"}', 'Sunan Abi Dawud 2356', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('40c4f84c-9fe9-52e2-a8e9-7470d1a1eadf', '4fe20667-307a-59cb-9ea1-ae917176c6f1', 'choice', '{"en": "Six voluntary fasts after Ramadan are kept in which month?", "bn": "রমজানের পর ছয়টি নফল রোজা কোন মাসে?"}', '{"options": [{"en": "Shawwal", "bn": "শাওয়াল"}, {"en": "Muharram", "bn": "মহররম"}, {"en": "Rajab", "bn": "রজব"}, {"en": "Dhul Qa‘dah", "bn": "জিলকদ"}], "correct": 0}', '{"en": "Ramadan followed by six of Shawwal is like fasting the whole year.", "bn": "রমজানের পর শাওয়ালের ছয় রোজা সারা বছর রোজা রাখার মতো।"}', 'Sahih Muslim 1164', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('f60840e5-bdac-5ad4-9df4-73ff4f781e6d', '4fe20667-307a-59cb-9ea1-ae917176c6f1', 'choice', '{"en": "Which ayah says \"Fasting is prescribed for you\"?", "bn": "কোন আয়াতে বলা হয়েছে \"তোমাদের ওপর রোজা ফরজ করা হয়েছে\"?"}', '{"options": [{"en": "2:183", "bn": "২:১৮৩"}, {"en": "3:97", "bn": "৩:৯৭"}, {"en": "9:60", "bn": "৯:৬০"}, {"en": "97:1", "bn": "৯৭:১"}], "correct": 0}', '{"en": "Al-Baqarah 2:183, \"…so that you may attain taqwa.\"", "bn": "আল-বাকারা ২:১৮৩, \"…যাতে তোমরা তাকওয়া অর্জন করতে পারো।\""}', 'Quran 2:183', 5) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_lessons (id, unit_id, title, kind, sort_order) VALUES ('5c30eb93-0fe9-5f3f-985e-e64eb7174b92', 'd1afa718-24ac-52cd-8b7a-066c12b0b8ed', '{"en": "Unit review", "bn": "ইউনিট রিভিউ"}', 'checkpoint', 3) ON CONFLICT (id) DO NOTHING;
