INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('2798bbe9-4cf1-5bd6-8b7f-ff0cfeb049a7', '5c30eb93-0fe9-5f3f-985e-e64eb7174b92', 'choice', '{"en": "What is the Eid at the end of Ramadan called?", "bn": "রমজানের শেষে যে ঈদ, তার নাম কী?"}', '{"options": [{"en": "Eid al-Adha", "bn": "ঈদুল আযহা"}, {"en": "Eid al-Fitr", "bn": "ঈদুল ফিতর"}, {"en": "Mawlid", "bn": "মিলাদ"}, {"en": "Ashura", "bn": "আশুরা"}], "correct": 1}', '{"en": "Eid al-Fitr, on 1 Shawwal.", "bn": "ঈদুল ফিতর, ১ শাওয়াল।"}', NULL, 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('575823e5-1133-5b56-8d7c-69b94f3036c2', '5c30eb93-0fe9-5f3f-985e-e64eb7174b92', 'choice', '{"en": "With what did the Prophet ﷺ prefer to break his fast?", "bn": "নবী ﷺ কী দিয়ে ইফতার করতে পছন্দ করতেন?"}', '{"options": [{"en": "Fresh or dry dates", "bn": "তাজা বা শুকনো খেজুর"}, {"en": "Milk", "bn": "দুধ"}, {"en": "Bread", "bn": "রুটি"}, {"en": "Honey", "bn": "মধু"}], "correct": 0}', '{"en": "Fresh dates, else dry dates, else a few sips of water.", "bn": "তাজা খেজুর, না থাকলে শুকনো খেজুর, তাও না থাকলে কয়েক চুমুক পানি।"}', 'Sunan Abi Dawud 2356', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('e3efd482-9cab-5e0f-8040-fda009f13699', '5c30eb93-0fe9-5f3f-985e-e64eb7174b92', 'choice', '{"en": "Which ayah says \"Fasting is prescribed for you\"?", "bn": "কোন আয়াতে বলা হয়েছে \"তোমাদের ওপর রোজা ফরজ করা হয়েছে\"?"}', '{"options": [{"en": "2:183", "bn": "২:১৮৩"}, {"en": "3:97", "bn": "৩:৯৭"}, {"en": "9:60", "bn": "৯:৬০"}, {"en": "97:1", "bn": "৯৭:১"}], "correct": 0}', '{"en": "Al-Baqarah 2:183, \"…so that you may attain taqwa.\"", "bn": "আল-বাকারা ২:১৮৩, \"…যাতে তোমরা তাকওয়া অর্জন করতে পারো।\""}', 'Quran 2:183', 5) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('8ce5bd3f-fee2-5a41-9096-d6bb06bbf391', '5c30eb93-0fe9-5f3f-985e-e64eb7174b92', 'choice', '{"en": "Laylat al-Qadr is better than how many months?", "bn": "লাইলাতুল কদর কত মাসের চেয়ে উত্তম?"}', '{"options": [{"en": "100", "bn": "১০০"}, {"en": "1,000", "bn": "১,০০০"}, {"en": "70", "bn": "৭০"}, {"en": "12", "bn": "১২"}], "correct": 1}', '{"en": "\"The Night of Decree is better than a thousand months.\"", "bn": "\"কদরের রাত হাজার মাসের চেয়ে উত্তম।\""}', 'Quran 97:3', 6) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_units (id, title, description, color, icon, review_status, sort_order, section_id) VALUES ('2f2415a7-7cda-5bee-8cf5-d6dc01ce54cc', '{"en": "Fasting: the basics", "bn": "রোজার মৌলিক বিধান"}', '{}', '#c23616', 'moon', 'in_review', 2, 'fff79906-c2c6-5d1c-a596-1ad5a3da0cf4') ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_lessons (id, unit_id, title, kind, sort_order) VALUES ('b3a6754f-6ff9-55a2-b815-ce2d6ef19968', '2f2415a7-7cda-5bee-8cf5-d6dc01ce54cc', '{"en": "Part 1", "bn": "পর্ব ১"}', 'lesson', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('af9c2e28-7b87-531a-ab7e-ce613a1286b0', 'b3a6754f-6ff9-55a2-b815-ce2d6ef19968', 'choice', '{"en": "If someone eats forgetfully while fasting, then…?", "bn": "রোজা অবস্থায় কেউ ভুলে খেয়ে ফেললে…?"}', '{"options": [{"en": "The fast continues", "bn": "রোজা চলবে"}, {"en": "The fast is broken", "bn": "রোজা ভেঙে যাবে"}, {"en": "He must fast 60 days", "bn": "৬০ দিন রোজা রাখতে হবে"}, {"en": "He must give charity", "bn": "সদকা দিতে হবে"}], "correct": 0}', '{"en": "\"…let him complete his fast, for Allah fed him and gave him drink.\"", "bn": "\"…সে যেন রোজা পূর্ণ করে, কারণ আল্লাহই তাকে খাইয়েছেন ও পান করিয়েছেন।\""}', 'Sahih al-Bukhari 1933', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('d90f7008-67a7-5d86-b674-2a0f838246ca', 'b3a6754f-6ff9-55a2-b815-ce2d6ef19968', 'choice', '{"en": "When does the fast begin each day?", "bn": "প্রতিদিন রোজা কখন শুরু হয়?"}', '{"options": [{"en": "At true dawn (Fajr)", "bn": "সুবহে সাদিক (ফজর)"}, {"en": "At sunrise", "bn": "সূর্যোদয়ে"}, {"en": "At midnight", "bn": "মধ্যরাতে"}, {"en": "At Dhuhr", "bn": "যোহরে"}], "correct": 0}', '{"en": "\"…until the white thread of dawn becomes distinct to you from the black thread.\"", "bn": "\"…যতক্ষণ না ভোরের সাদা রেখা কালো রেখা থেকে স্পষ্ট হয়।\""}', 'Quran 2:187', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('1ee89e91-47de-55d6-829e-9973babd2996', 'b3a6754f-6ff9-55a2-b815-ce2d6ef19968', 'choice', '{"en": "When does the fast end?", "bn": "রোজা কখন শেষ হয়?"}', '{"options": [{"en": "At sunset", "bn": "সূর্যাস্তে"}, {"en": "At Asr", "bn": "আসরে"}, {"en": "At Isha", "bn": "ইশায়"}, {"en": "At midnight", "bn": "মধ্যরাতে"}], "correct": 0}', '{"en": "\"…then complete the fast until the night.\"", "bn": "\"…তারপর রাত পর্যন্ত রোজা পূর্ণ করো।\""}', 'Quran 2:187', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('9dae0559-8992-5c46-8e15-5a00c2ab12f4', 'b3a6754f-6ff9-55a2-b815-ce2d6ef19968', 'choice', '{"en": "Who may skip fasting in Ramadan and make it up later?", "bn": "কে রমজানে রোজা না রেখে পরে কাজা করতে পারে?"}', '{"options": [{"en": "The sick and the traveller", "bn": "অসুস্থ ও মুসাফির"}, {"en": "Anyone who is busy", "bn": "যে ব্যস্ত"}, {"en": "Students", "bn": "ছাত্ররা"}, {"en": "Nobody", "bn": "কেউ না"}], "correct": 0}', '{"en": "\"…whoever is ill or on a journey, then an equal number of other days.\"", "bn": "\"…যে অসুস্থ বা সফরে থাকে, সে অন্য দিনে সমান সংখ্যা পূর্ণ করবে।\""}', 'Quran 2:184', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('66e0425f-7e03-523d-bd7f-a12b971b961a', 'b3a6754f-6ff9-55a2-b815-ce2d6ef19968', 'choice', '{"en": "Someone who can never fast (e.g. very old) should…?", "bn": "যে কখনো রোজা রাখতে পারবে না (যেমন অতি বৃদ্ধ), তার করণীয়…?"}', '{"options": [{"en": "Feed a poor person for each day", "bn": "প্রতিদিনের বদলে একজন গরিবকে খাওয়ানো"}, {"en": "Pray extra", "bn": "বেশি নামাজ পড়া"}, {"en": "Do nothing", "bn": "কিছুই না"}, {"en": "Fast at night", "bn": "রাতে রোজা রাখা"}], "correct": 0}', '{"en": "\"…a ransom: feeding a poor person (each day).\"", "bn": "\"…ফিদিয়া: (প্রতিদিন) একজন মিসকিনকে খাওয়ানো।\""}', 'Quran 2:184', 5) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_lessons (id, unit_id, title, kind, sort_order) VALUES ('c80e7600-b1ee-5136-b778-b59c79644d12', '2f2415a7-7cda-5bee-8cf5-d6dc01ce54cc', '{"en": "Part 2", "bn": "পর্ব ২"}', 'lesson', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('ba7cc538-6a44-5db8-9da8-eeac5dc25028', 'c80e7600-b1ee-5136-b778-b59c79644d12', 'choice', '{"en": "What is the sunnah about iftar time?", "bn": "ইফতারের সময় নিয়ে সুন্নাহ কী?"}', '{"options": [{"en": "Hasten it at sunset", "bn": "সূর্যাস্ত হলেই দ্রুত ইফতার"}, {"en": "Delay it until Isha", "bn": "ইশা পর্যন্ত দেরি"}, {"en": "Eat it at midnight", "bn": "মধ্যরাতে খাওয়া"}, {"en": "Skip it", "bn": "বাদ দেওয়া"}], "correct": 0}', '{"en": "\"People will remain upon good as long as they hasten the iftar.\"", "bn": "\"মানুষ ততদিন কল্যাণে থাকবে যতদিন তারা দ্রুত ইফতার করবে।\""}', 'Sahih al-Bukhari 1957', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('bbc2a571-677d-5f2b-af42-7a30272a70c0', 'c80e7600-b1ee-5136-b778-b59c79644d12', 'choice', '{"en": "Fasting Ramadan with faith and hoping for reward brings…?", "bn": "ঈমান ও সওয়াবের আশায় রমজানের রোজা রাখলে কী হয়?"}', '{"options": [{"en": "Forgiveness of past sins", "bn": "আগের গুনাহ মাফ"}, {"en": "Wealth", "bn": "সম্পদ"}, {"en": "Fame", "bn": "খ্যাতি"}, {"en": "Nothing special", "bn": "বিশেষ কিছু না"}], "correct": 0}', '{"en": "\"…his previous sins will be forgiven.\"", "bn": "\"…তার আগের গুনাহ মাফ করে দেওয়া হবে।\""}', 'Sahih al-Bukhari 38', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('8e0f8f7b-6850-5c44-9adc-8f5fe82bf177', 'c80e7600-b1ee-5136-b778-b59c79644d12', 'choice', '{"en": "Allah says in a hadith qudsi, \"Fasting is for Me and…\"", "bn": "হাদিসে কুদসিতে আল্লাহ বলেন, \"রোজা আমার জন্য এবং…\""}', '{"options": [{"en": "…I will reward it", "bn": "…আমিই এর প্রতিদান দেব"}, {"en": "…it is easy", "bn": "…এটি সহজ"}, {"en": "…it is optional", "bn": "…এটি ঐচ্ছিক"}, {"en": "…it is once a year", "bn": "…এটি বছরে একবার"}], "correct": 0}', '{"en": "A fasting person’s reward is given by Allah Himself.", "bn": "রোজাদারের প্রতিদান আল্লাহ নিজেই দেবেন।"}', 'Sahih al-Bukhari 1904', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('f4854e17-9306-5285-a83a-06e52303cac0', 'c80e7600-b1ee-5136-b778-b59c79644d12', 'choice', '{"en": "Staying in the masjid for worship in the last ten days is called…?", "bn": "শেষ দশকে ইবাদতের জন্য মসজিদে অবস্থানকে কী বলে?"}', '{"options": [{"en": "I‘tikaf", "bn": "ইতিকাফ"}, {"en": "Tarawih", "bn": "তারাবিহ"}, {"en": "Hajj", "bn": "হজ"}, {"en": "Qiyam", "bn": "কিয়াম"}], "correct": 0}', '{"en": "The Prophet ﷺ did i‘tikaf in the last ten days of Ramadan.", "bn": "নবী ﷺ রমজানের শেষ দশকে ইতিকাফ করতেন।"}', 'Sahih al-Bukhari 2026', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('dfbdc3c6-76b0-597b-b2cf-5db96879e42d', 'c80e7600-b1ee-5136-b778-b59c79644d12', 'choice', '{"en": "Why was fasting prescribed, according to 2:183?", "bn": "২:১৮৩ অনুযায়ী রোজা কেন ফরজ করা হয়েছে?"}', '{"options": [{"en": "So you may attain taqwa", "bn": "যাতে তোমরা তাকওয়া অর্জন করতে পারো"}, {"en": "To lose weight", "bn": "ওজন কমাতে"}, {"en": "To save food", "bn": "খাবার বাঁচাতে"}, {"en": "For sport", "bn": "খেলাধুলার জন্য"}], "correct": 0}', '{"en": "\"…as it was prescribed for those before you, so that you may attain taqwa.\"", "bn": "\"…যেমন তোমাদের পূর্ববর্তীদের ওপর ফরজ করা হয়েছিল, যাতে তোমরা তাকওয়া অর্জন করতে পারো।\""}', 'Quran 2:183', 5) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_lessons (id, unit_id, title, kind, sort_order) VALUES ('3f7fd906-675c-5098-a13d-e9b4ff90f711', '2f2415a7-7cda-5bee-8cf5-d6dc01ce54cc', '{"en": "Unit review", "bn": "ইউনিট রিভিউ"}', 'checkpoint', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('3904c0ed-2c7d-533b-bf99-7612cfed1c20', '3f7fd906-675c-5098-a13d-e9b4ff90f711', 'choice', '{"en": "When does the fast begin each day?", "bn": "প্রতিদিন রোজা কখন শুরু হয়?"}', '{"options": [{"en": "At true dawn (Fajr)", "bn": "সুবহে সাদিক (ফজর)"}, {"en": "At sunrise", "bn": "সূর্যোদয়ে"}, {"en": "At midnight", "bn": "মধ্যরাতে"}, {"en": "At Dhuhr", "bn": "যোহরে"}], "correct": 0}', '{"en": "\"…until the white thread of dawn becomes distinct to you from the black thread.\"", "bn": "\"…যতক্ষণ না ভোরের সাদা রেখা কালো রেখা থেকে স্পষ্ট হয়।\""}', 'Quran 2:187', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('1a589fe8-a8cd-5058-bfdb-6b908046ef46', '3f7fd906-675c-5098-a13d-e9b4ff90f711', 'choice', '{"en": "Who may skip fasting in Ramadan and make it up later?", "bn": "কে রমজানে রোজা না রেখে পরে কাজা করতে পারে?"}', '{"options": [{"en": "The sick and the traveller", "bn": "অসুস্থ ও মুসাফির"}, {"en": "Anyone who is busy", "bn": "যে ব্যস্ত"}, {"en": "Students", "bn": "ছাত্ররা"}, {"en": "Nobody", "bn": "কেউ না"}], "correct": 0}', '{"en": "\"…whoever is ill or on a journey, then an equal number of other days.\"", "bn": "\"…যে অসুস্থ বা সফরে থাকে, সে অন্য দিনে সমান সংখ্যা পূর্ণ করবে।\""}', 'Quran 2:184', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('87ac96dc-ddc7-500d-86ff-44051d6a9c66', '3f7fd906-675c-5098-a13d-e9b4ff90f711', 'choice', '{"en": "What is the sunnah about iftar time?", "bn": "ইফতারের সময় নিয়ে সুন্নাহ কী?"}', '{"options": [{"en": "Hasten it at sunset", "bn": "সূর্যাস্ত হলেই দ্রুত ইফতার"}, {"en": "Delay it until Isha", "bn": "ইশা পর্যন্ত দেরি"}, {"en": "Eat it at midnight", "bn": "মধ্যরাতে খাওয়া"}, {"en": "Skip it", "bn": "বাদ দেওয়া"}], "correct": 0}', '{"en": "\"People will remain upon good as long as they hasten the iftar.\"", "bn": "\"মানুষ ততদিন কল্যাণে থাকবে যতদিন তারা দ্রুত ইফতার করবে।\""}', 'Sahih al-Bukhari 1957', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('af7c38b2-fd7d-5f7d-b571-b8810aed52e2', '3f7fd906-675c-5098-a13d-e9b4ff90f711', 'choice', '{"en": "Allah says in a hadith qudsi, \"Fasting is for Me and…\"", "bn": "হাদিসে কুদসিতে আল্লাহ বলেন, \"রোজা আমার জন্য এবং…\""}', '{"options": [{"en": "…I will reward it", "bn": "…আমিই এর প্রতিদান দেব"}, {"en": "…it is easy", "bn": "…এটি সহজ"}, {"en": "…it is optional", "bn": "…এটি ঐচ্ছিক"}, {"en": "…it is once a year", "bn": "…এটি বছরে একবার"}], "correct": 0}', '{"en": "A fasting person’s reward is given by Allah Himself.", "bn": "রোজাদারের প্রতিদান আল্লাহ নিজেই দেবেন।"}', 'Sahih al-Bukhari 1904', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('298e7c40-23f0-5f77-ae2e-0cea3e028185', '3f7fd906-675c-5098-a13d-e9b4ff90f711', 'choice', '{"en": "Why was fasting prescribed, according to 2:183?", "bn": "২:১৮৩ অনুযায়ী রোজা কেন ফরজ করা হয়েছে?"}', '{"options": [{"en": "So you may attain taqwa", "bn": "যাতে তোমরা তাকওয়া অর্জন করতে পারো"}, {"en": "To lose weight", "bn": "ওজন কমাতে"}, {"en": "To save food", "bn": "খাবার বাঁচাতে"}, {"en": "For sport", "bn": "খেলাধুলার জন্য"}], "correct": 0}', '{"en": "\"…as it was prescribed for those before you, so that you may attain taqwa.\"", "bn": "\"…যেমন তোমাদের পূর্ববর্তীদের ওপর ফরজ করা হয়েছিল, যাতে তোমরা তাকওয়া অর্জন করতে পারো।\""}', 'Quran 2:183', 5) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('6ceebef3-d7f9-5c81-bc3b-85c271bd3120', '3f7fd906-675c-5098-a13d-e9b4ff90f711', 'choice', '{"en": "If someone eats forgetfully while fasting, then…?", "bn": "রোজা অবস্থায় কেউ ভুলে খেয়ে ফেললে…?"}', '{"options": [{"en": "The fast continues", "bn": "রোজা চলবে"}, {"en": "The fast is broken", "bn": "রোজা ভেঙে যাবে"}, {"en": "He must fast 60 days", "bn": "৬০ দিন রোজা রাখতে হবে"}, {"en": "He must give charity", "bn": "সদকা দিতে হবে"}], "correct": 0}', '{"en": "\"…let him complete his fast, for Allah fed him and gave him drink.\"", "bn": "\"…সে যেন রোজা পূর্ণ করে, কারণ আল্লাহই তাকে খাইয়েছেন ও পান করিয়েছেন।\""}', 'Sahih al-Bukhari 1933', 6) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_units (id, title, description, color, icon, review_status, sort_order, section_id) VALUES ('06e480ae-dcb0-5e6a-bf3f-1548fd3ad40e', '{"en": "Eid", "bn": "ঈদ"}', '{}', '#c23616', 'moon', 'in_review', 3, 'fff79906-c2c6-5d1c-a596-1ad5a3da0cf4') ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_lessons (id, unit_id, title, kind, sort_order) VALUES ('45c88f77-b2cd-57e2-be99-68e5e9e1dc98', '06e480ae-dcb0-5e6a-bf3f-1548fd3ad40e', '{"en": "Part 1", "bn": "পর্ব ১"}', 'lesson', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('4dceb3d4-6c88-59c3-a1f0-efc39d51154e', '45c88f77-b2cd-57e2-be99-68e5e9e1dc98', 'choice', '{"en": "How many Eids do Muslims celebrate each year?", "bn": "মুসলমানরা প্রতি বছর কয়টি ঈদ উদ্‌যাপন করে?"}', '{"options": [{"en": "1", "bn": "১"}, {"en": "2", "bn": "২"}, {"en": "3", "bn": "৩"}, {"en": "4", "bn": "৪"}], "correct": 1}', '{"en": "\"Allah has replaced them with two better days: al-Adha and al-Fitr.\"", "bn": "\"আল্লাহ তোমাদের এর বদলে দুটি উত্তম দিন দিয়েছেন: আযহা ও ফিতর।\""}', 'Sunan Abi Dawud 1134', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('4d2efc39-3a5d-5cae-8e4a-55d41e547cf3', '45c88f77-b2cd-57e2-be99-68e5e9e1dc98', 'choice', '{"en": "Eid al-Adha is on…?", "bn": "ঈদুল আযহা কোন তারিখে?"}', '{"options": [{"en": "10 Dhul Hijjah", "bn": "১০ জিলহজ"}, {"en": "1 Shawwal", "bn": "১ শাওয়াল"}, {"en": "27 Ramadan", "bn": "২৭ রমজান"}, {"en": "1 Muharram", "bn": "১ মহররম"}], "correct": 0}', '{"en": "The day after Arafah.", "bn": "আরাফার পরের দিন।"}', NULL, 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('47ba3d55-b02a-514f-9fc8-089bf67f8953', '45c88f77-b2cd-57e2-be99-68e5e9e1dc98', 'choice', '{"en": "In the Eid prayer, does the khutbah come before or after the prayer?", "bn": "ঈদের নামাজে খুতবা নামাজের আগে না পরে?"}', '{"options": [{"en": "After", "bn": "পরে"}, {"en": "Before", "bn": "আগে"}, {"en": "There is none", "bn": "নেই"}, {"en": "Both", "bn": "দুটোই"}], "correct": 0}', '{"en": "The Prophet ﷺ prayed first, then gave the khutbah.", "bn": "নবী ﷺ আগে নামাজ পড়তেন, তারপর খুতবা দিতেন।"}', 'Sahih al-Bukhari 962', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('329e2477-354f-5c8d-80a8-39b4ee2dae43', '45c88f77-b2cd-57e2-be99-68e5e9e1dc98', 'choice', '{"en": "What is sunnah to eat before going to the Eid al-Fitr prayer?", "bn": "ঈদুল ফিতরের নামাজে যাওয়ার আগে কী খাওয়া সুন্নাত?"}', '{"options": [{"en": "Dates, an odd number", "bn": "বেজোড় সংখ্যক খেজুর"}, {"en": "Nothing", "bn": "কিছু না"}, {"en": "Meat", "bn": "গোশত"}, {"en": "Sweets only", "bn": "শুধু মিষ্টি"}], "correct": 0}', '{"en": "He ﷺ would not go out on Eid al-Fitr until he had eaten some dates, an odd number.", "bn": "ঈদুল ফিতরে তিনি ﷺ বেজোড় সংখ্যক খেজুর না খেয়ে বের হতেন না।"}', 'Sahih al-Bukhari 953', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('b0f44166-61f2-5420-8a07-854f44e4d989', '45c88f77-b2cd-57e2-be99-68e5e9e1dc98', 'choice', '{"en": "On Eid al-Adha, the sunnah is to eat…?", "bn": "ঈদুল আযহায় সুন্নাত হলো খাওয়া…?"}', '{"options": [{"en": "After the prayer", "bn": "নামাজের পরে"}, {"en": "Before the prayer", "bn": "নামাজের আগে"}, {"en": "Only at night", "bn": "শুধু রাতে"}, {"en": "Nothing all day", "bn": "সারাদিন কিছু না"}], "correct": 0}', '{"en": "He ﷺ did not eat on the day of al-Adha until he had prayed.", "bn": "আযহার দিন তিনি ﷺ নামাজ না পড়ে খেতেন না।"}', 'Jami‘ at-Tirmidhi 542', 5) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_lessons (id, unit_id, title, kind, sort_order) VALUES ('ec277e47-dd21-5efd-b209-a1daa50bab6f', '06e480ae-dcb0-5e6a-bf3f-1548fd3ad40e', '{"en": "Part 2", "bn": "পর্ব ২"}', 'lesson', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('2b1832be-6f8b-5a0f-82a8-4cea58cd9ac4', 'ec277e47-dd21-5efd-b209-a1daa50bab6f', 'choice', '{"en": "Is fasting allowed on the two Eid days?", "bn": "দুই ঈদের দিন কি রোজা রাখা যায়?"}', '{"options": [{"en": "No", "bn": "না"}, {"en": "Yes", "bn": "হ্যাঁ"}, {"en": "Only half a day", "bn": "শুধু অর্ধদিন"}, {"en": "Only for adults", "bn": "শুধু প্রাপ্তবয়স্কদের"}], "correct": 0}', '{"en": "The Prophet ﷺ forbade fasting on the day of Fitr and the day of Adha.", "bn": "নবী ﷺ ফিতর ও আযহার দিনে রোজা রাখতে নিষেধ করেছেন।"}', 'Sahih al-Bukhari 1990', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('c0343932-1861-51f9-a560-7af8e6171587', 'ec277e47-dd21-5efd-b209-a1daa50bab6f', 'choice', '{"en": "Coming back from the Eid prayer, the sunnah is to…?", "bn": "ঈদের নামাজ থেকে ফেরার সময় সুন্নাত হলো…?"}', '{"options": [{"en": "Take a different route", "bn": "ভিন্ন পথে ফেরা"}, {"en": "Run", "bn": "দৌড়ানো"}, {"en": "Stay silent all day", "bn": "সারাদিন চুপ থাকা"}, {"en": "Go by boat", "bn": "নৌকায় যাওয়া"}], "correct": 0}', '{"en": "On Eid he ﷺ would go by one way and return by another.", "bn": "ঈদে তিনি ﷺ এক পথে যেতেন, অন্য পথে ফিরতেন।"}', 'Sahih al-Bukhari 986', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('943f8bfc-1020-5024-a949-9ae4da6e73ea', 'ec277e47-dd21-5efd-b209-a1daa50bab6f', 'choice', '{"en": "When are the Eid al-Adha sacrifices made?", "bn": "ঈদুল আযহার কোরবানি কখন করা হয়?"}', '{"options": [{"en": "After the Eid prayer", "bn": "ঈদের নামাজের পরে"}, {"en": "The night before", "bn": "আগের রাতে"}, {"en": "Before Fajr", "bn": "ফজরের আগে"}, {"en": "In Ramadan", "bn": "রমজানে"}], "correct": 0}', '{"en": "\"Whoever slaughters before the prayer must slaughter again.\"", "bn": "\"যে নামাজের আগে জবাই করে, তাকে আবার জবাই করতে হবে।\""}', 'Sahih al-Bukhari 5545', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('4e49b3d4-4a30-5d08-81f3-95e9fd44ac5b', 'ec277e47-dd21-5efd-b209-a1daa50bab6f', 'choice', '{"en": "Eid al-Fitr celebrates completing…?", "bn": "ঈদুল ফিতর কী সম্পন্ন হওয়ার আনন্দ?"}', '{"options": [{"en": "The fast of Ramadan", "bn": "রমজানের রোজা"}, {"en": "Hajj", "bn": "হজ"}, {"en": "The school year", "bn": "শিক্ষাবর্ষ"}, {"en": "The harvest", "bn": "ফসল তোলা"}], "correct": 0}', '{"en": "\"…and to complete the number (of days) and glorify Allah for guiding you.\"", "bn": "\"…যাতে তোমরা সংখ্যা পূর্ণ করো এবং তোমাদের হেদায়াতের জন্য আল্লাহর মহিমা ঘোষণা করো।\""}', 'Quran 2:185', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('d95e924c-4732-5dec-8289-4c61aedb1c6d', 'ec277e47-dd21-5efd-b209-a1daa50bab6f', 'choice', '{"en": "The days of Tashriq are days of…?", "bn": "আইয়ামে তাশরিক কীসের দিন?"}', '{"options": [{"en": "Eating, drinking and remembering Allah", "bn": "খাওয়া, পান করা ও আল্লাহর জিকির"}, {"en": "Fasting", "bn": "রোজা"}, {"en": "Silence", "bn": "নীরবতা"}, {"en": "Travel only", "bn": "শুধু সফর"}], "correct": 0}', '{"en": "\"The days of Tashriq are days of eating and drinking (and remembering Allah).\"", "bn": "\"আইয়ামে তাশরিক খাওয়া ও পান করার (এবং আল্লাহর জিকিরের) দিন।\""}', 'Sahih Muslim 1141', 5) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_lessons (id, unit_id, title, kind, sort_order) VALUES ('5f25c368-6ce0-512d-8335-3853d57e9675', '06e480ae-dcb0-5e6a-bf3f-1548fd3ad40e', '{"en": "Unit review", "bn": "ইউনিট রিভিউ"}', 'checkpoint', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('96a0f451-c8db-5ae2-94ce-0737db83ecc4', '5f25c368-6ce0-512d-8335-3853d57e9675', 'choice', '{"en": "Eid al-Adha is on…?", "bn": "ঈদুল আযহা কোন তারিখে?"}', '{"options": [{"en": "10 Dhul Hijjah", "bn": "১০ জিলহজ"}, {"en": "1 Shawwal", "bn": "১ শাওয়াল"}, {"en": "27 Ramadan", "bn": "২৭ রমজান"}, {"en": "1 Muharram", "bn": "১ মহররম"}], "correct": 0}', '{"en": "The day after Arafah.", "bn": "আরাফার পরের দিন।"}', NULL, 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('b7c1e944-b84e-567b-b2c3-0adfdbbf80f0', '5f25c368-6ce0-512d-8335-3853d57e9675', 'choice', '{"en": "What is sunnah to eat before going to the Eid al-Fitr prayer?", "bn": "ঈদুল ফিতরের নামাজে যাওয়ার আগে কী খাওয়া সুন্নাত?"}', '{"options": [{"en": "Dates, an odd number", "bn": "বেজোড় সংখ্যক খেজুর"}, {"en": "Nothing", "bn": "কিছু না"}, {"en": "Meat", "bn": "গোশত"}, {"en": "Sweets only", "bn": "শুধু মিষ্টি"}], "correct": 0}', '{"en": "He ﷺ would not go out on Eid al-Fitr until he had eaten some dates, an odd number.", "bn": "ঈদুল ফিতরে তিনি ﷺ বেজোড় সংখ্যক খেজুর না খেয়ে বের হতেন না।"}', 'Sahih al-Bukhari 953', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('e1aed237-c697-5a57-9fbf-344c860a87c4', '5f25c368-6ce0-512d-8335-3853d57e9675', 'choice', '{"en": "Is fasting allowed on the two Eid days?", "bn": "দুই ঈদের দিন কি রোজা রাখা যায়?"}', '{"options": [{"en": "No", "bn": "না"}, {"en": "Yes", "bn": "হ্যাঁ"}, {"en": "Only half a day", "bn": "শুধু অর্ধদিন"}, {"en": "Only for adults", "bn": "শুধু প্রাপ্তবয়স্কদের"}], "correct": 0}', '{"en": "The Prophet ﷺ forbade fasting on the day of Fitr and the day of Adha.", "bn": "নবী ﷺ ফিতর ও আযহার দিনে রোজা রাখতে নিষেধ করেছেন।"}', 'Sahih al-Bukhari 1990', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('21484f1f-3875-5385-8728-99749f01b7bf', '5f25c368-6ce0-512d-8335-3853d57e9675', 'choice', '{"en": "When are the Eid al-Adha sacrifices made?", "bn": "ঈদুল আযহার কোরবানি কখন করা হয়?"}', '{"options": [{"en": "After the Eid prayer", "bn": "ঈদের নামাজের পরে"}, {"en": "The night before", "bn": "আগের রাতে"}, {"en": "Before Fajr", "bn": "ফজরের আগে"}, {"en": "In Ramadan", "bn": "রমজানে"}], "correct": 0}', '{"en": "\"Whoever slaughters before the prayer must slaughter again.\"", "bn": "\"যে নামাজের আগে জবাই করে, তাকে আবার জবাই করতে হবে।\""}', 'Sahih al-Bukhari 5545', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('71eb70c4-1997-5e67-8bb3-cf2262034afa', '5f25c368-6ce0-512d-8335-3853d57e9675', 'choice', '{"en": "The days of Tashriq are days of…?", "bn": "আইয়ামে তাশরিক কীসের দিন?"}', '{"options": [{"en": "Eating, drinking and remembering Allah", "bn": "খাওয়া, পান করা ও আল্লাহর জিকির"}, {"en": "Fasting", "bn": "রোজা"}, {"en": "Silence", "bn": "নীরবতা"}, {"en": "Travel only", "bn": "শুধু সফর"}], "correct": 0}', '{"en": "\"The days of Tashriq are days of eating and drinking (and remembering Allah).\"", "bn": "\"আইয়ামে তাশরিক খাওয়া ও পান করার (এবং আল্লাহর জিকিরের) দিন।\""}', 'Sahih Muslim 1141', 5) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('0827232b-f553-52ca-afa1-ea0e66865dff', '5f25c368-6ce0-512d-8335-3853d57e9675', 'choice', '{"en": "How many Eids do Muslims celebrate each year?", "bn": "মুসলমানরা প্রতি বছর কয়টি ঈদ উদ্‌যাপন করে?"}', '{"options": [{"en": "1", "bn": "১"}, {"en": "2", "bn": "২"}, {"en": "3", "bn": "৩"}, {"en": "4", "bn": "৪"}], "correct": 1}', '{"en": "\"Allah has replaced them with two better days: al-Adha and al-Fitr.\"", "bn": "\"আল্লাহ তোমাদের এর বদলে দুটি উত্তম দিন দিয়েছেন: আযহা ও ফিতর।\""}', 'Sunan Abi Dawud 1134', 6) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_units (id, title, description, color, icon, review_status, sort_order, section_id) VALUES ('497c4a54-cc8c-5a6f-a6e8-5d5e92bd414f', '{"en": "Zakat & charity", "bn": "যাকাত ও দান"}', '{}', '#c23616', 'moon', 'in_review', 1, 'a948793e-9cde-541f-9f21-59fc2ad50acb') ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_lessons (id, unit_id, title, kind, sort_order) VALUES ('44b3165f-2814-5c56-aa0a-1ca927188d38', '497c4a54-cc8c-5a6f-a6e8-5d5e92bd414f', '{"en": "Part 1", "bn": "পর্ব ১"}', 'lesson', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('8de72f23-da86-5d61-bc33-b18885b773a9', '44b3165f-2814-5c56-aa0a-1ca927188d38', 'choice', '{"en": "For whom is Zakat al-Fitr given?", "bn": "সদকাতুল ফিতর কার পক্ষ থেকে দিতে হয়?"}', '{"options": [{"en": "Only rich men", "bn": "শুধু ধনী পুরুষ"}, {"en": "Every Muslim, young and old", "bn": "ছোট-বড় প্রত্যেক মুসলমান"}, {"en": "Only fasting adults", "bn": "শুধু রোজাদার প্রাপ্তবয়স্ক"}, {"en": "Only scholars", "bn": "শুধু আলেম"}], "correct": 1}', '{"en": "\"…on the slave and the free, male and female, young and old of the Muslims.\"", "bn": "\"…মুসলমানদের দাস-স্বাধীন, নারী-পুরুষ, ছোট-বড় সবার ওপর।\""}', 'Sahih al-Bukhari 1503', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('c1c7d162-754d-5199-aff6-85a016cec650', '44b3165f-2814-5c56-aa0a-1ca927188d38', 'choice', '{"en": "Which ayah lists who may receive zakat?", "bn": "কোন আয়াতে যাকাতের হকদারদের তালিকা আছে?"}', '{"options": [{"en": "9:60", "bn": "৯:৬০"}, {"en": "2:255", "bn": "২:২৫৫"}, {"en": "1:5", "bn": "১:৫"}, {"en": "112:1", "bn": "১১২:১"}], "correct": 0}', '{"en": "At-Tawbah 9:60.", "bn": "আত-তাওবা ৯:৬০।"}', 'Quran 9:60', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('1ff6e7f5-129c-525d-a671-017c8f35a83b', '44b3165f-2814-5c56-aa0a-1ca927188d38', 'choice', '{"en": "How many groups may receive zakat?", "bn": "কত শ্রেণির মানুষ যাকাত পেতে পারে?"}', '{"options": [{"en": "4", "bn": "৪"}, {"en": "6", "bn": "৬"}, {"en": "8", "bn": "৮"}, {"en": "10", "bn": "১০"}], "correct": 2}', '{"en": "The poor, the needy, its collectors, those whose hearts are reconciled, freeing captives, debtors, in the way of Allah, and the stranded traveller.", "bn": "গরিব, মিসকিন, আদায়কারী, মন জয় করার জন্য, দাসমুক্তি, ঋণগ্রস্ত, আল্লাহর পথে এবং বিপদগ্রস্ত মুসাফির।"}', 'Quran 9:60', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('62555e93-c29c-5b0f-829f-8d2f47d6531f', '44b3165f-2814-5c56-aa0a-1ca927188d38', 'choice', '{"en": "Voluntary charity is called…?", "bn": "নফল দানকে কী বলে?"}', '{"options": [{"en": "Sadaqah", "bn": "সদকা"}, {"en": "Jizyah", "bn": "জিজিয়া"}, {"en": "Kharaj", "bn": "খারাজ"}, {"en": "Diyah", "bn": "দিয়াত"}], "correct": 0}', '{"en": "Sadaqah: any charity given for Allah’s sake.", "bn": "সদকা: আল্লাহর সন্তুষ্টির জন্য যেকোনো দান।"}', NULL, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('49c5b2e2-8e44-50bc-b6aa-fc38c5068edd', '44b3165f-2814-5c56-aa0a-1ca927188d38', 'choice', '{"en": "Charity that keeps rewarding after death is called…?", "bn": "মৃত্যুর পরেও সওয়াব দিতে থাকা দানকে কী বলে?"}', '{"options": [{"en": "Sadaqah jariyah", "bn": "সদকায়ে জারিয়া"}, {"en": "Fidyah", "bn": "ফিদিয়া"}, {"en": "Kaffarah", "bn": "কাফফারা"}, {"en": "Mahr", "bn": "মোহর"}], "correct": 0}', '{"en": "\"When a person dies, his deeds end except three: ongoing charity, beneficial knowledge, or a righteous child who prays for him.\"", "bn": "\"মানুষ মারা গেলে তার আমল বন্ধ হয়, তিনটি ছাড়া: চলমান সদকা, উপকারী জ্ঞান, অথবা নেক সন্তান যে তার জন্য দোয়া করে।\""}', 'Sahih Muslim 1631', 5) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_lessons (id, unit_id, title, kind, sort_order) VALUES ('ff0d4a21-0621-59a9-9c5c-6ccb6d4d3e4e', '497c4a54-cc8c-5a6f-a6e8-5d5e92bd414f', '{"en": "Part 2", "bn": "পর্ব ২"}', 'lesson', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('447d029e-7376-580a-82ce-d77847dfef61', 'ff0d4a21-0621-59a9-9c5c-6ccb6d4d3e4e', 'choice', '{"en": "Zakat on savings is due after they stay above the nisab for…?", "bn": "সঞ্চয় কতদিন নিসাবের ওপরে থাকলে যাকাত ফরজ হয়?"}', '{"options": [{"en": "One week", "bn": "এক সপ্তাহ"}, {"en": "One month", "bn": "এক মাস"}, {"en": "One lunar year", "bn": "এক চান্দ্র বছর"}, {"en": "Ten years", "bn": "দশ বছর"}], "correct": 2}', '{"en": "A full lunar year (hawl).", "bn": "পূর্ণ এক চান্দ্র বছর (হাওল)।"}', 'Sunan Abi Dawud 1573', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('d2905609-f987-59c9-afaa-17057705bb9f', 'ff0d4a21-0621-59a9-9c5c-6ccb6d4d3e4e', 'choice', '{"en": "Among those shaded on the Day of Judgement is one who gave charity so secretly that…?", "bn": "কিয়ামতের দিন ছায়াপ্রাপ্তদের একজন এমনভাবে গোপনে দান করেছে যে…?"}', '{"options": [{"en": "His left hand did not know what his right gave", "bn": "তার বাম হাত জানত না ডান হাত কী দিয়েছে"}, {"en": "Nobody received it", "bn": "কেউ তা পায়নি"}, {"en": "He forgot it", "bn": "সে ভুলে গেছে"}, {"en": "It was in the masjid", "bn": "তা মসজিদে ছিল"}], "correct": 0}', '{"en": "One of the seven whom Allah shades in His shade.", "bn": "আল্লাহ যে সাত শ্রেণিকে তাঁর ছায়ায় আশ্রয় দেবেন, তাদের একজন।"}', 'Sahih al-Bukhari 660', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('7e10e8e0-366d-5d55-ae5c-ba1edcb5c8ea', 'ff0d4a21-0621-59a9-9c5c-6ccb6d4d3e4e', 'choice', '{"en": "According to the hadith, what does charity do to wealth?", "bn": "হাদিস অনুযায়ী দান সম্পদের কী করে?"}', '{"options": [{"en": "It does not decrease it", "bn": "তা কমায় না"}, {"en": "It halves it", "bn": "অর্ধেক করে"}, {"en": "It ends it", "bn": "শেষ করে দেয়"}, {"en": "Nothing is said", "bn": "কিছু বলা হয়নি"}], "correct": 0}', '{"en": "\"Charity does not decrease wealth.\"", "bn": "\"দান সম্পদ কমায় না।\""}', 'Sahih Muslim 2588', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('d4b95228-4a5c-54fb-9665-cbbd79b46a84', 'ff0d4a21-0621-59a9-9c5c-6ccb6d4d3e4e', 'choice', '{"en": "To whom may you NOT give your zakat?", "bn": "কাকে আপনার যাকাত দেওয়া যায় না?"}', '{"options": [{"en": "A poor neighbour", "bn": "গরিব প্রতিবেশী"}, {"en": "A stranded traveller", "bn": "বিপদগ্রস্ত মুসাফির"}, {"en": "Your own parents", "bn": "নিজের বাবা-মা"}, {"en": "A person in debt", "bn": "ঋণগ্রস্ত ব্যক্তি"}], "correct": 2}', '{"en": "You support your parents and children from your own wealth, not from zakat.", "bn": "বাবা-মা ও সন্তানের ভরণপোষণ নিজের সম্পদ থেকে দিতে হয়, যাকাত থেকে নয়।"}', NULL, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('d1f6c876-f702-5407-addd-51044801abf3', 'ff0d4a21-0621-59a9-9c5c-6ccb6d4d3e4e', 'choice', '{"en": "Which charity is best, according to the hadith?", "bn": "হাদিস অনুযায়ী কোন দান সর্বোত্তম?"}', '{"options": [{"en": "Given while healthy and hoping to be rich", "bn": "সুস্থ অবস্থায়, ধনী হওয়ার আশা থাকতে দেওয়া দান"}, {"en": "Given only at death", "bn": "শুধু মৃত্যুর সময় দেওয়া"}, {"en": "Given for praise", "bn": "প্রশংসার জন্য দেওয়া"}, {"en": "Given rarely", "bn": "কদাচিৎ দেওয়া"}], "correct": 0}', '{"en": "\"…that you give while healthy, fearing poverty and hoping for wealth.\"", "bn": "\"…যা তুমি সুস্থ অবস্থায়, দারিদ্র্যের ভয় ও ধনী হওয়ার আশা নিয়ে দাও।\""}', 'Sahih al-Bukhari 1419', 5) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_lessons (id, unit_id, title, kind, sort_order) VALUES ('663b449e-80b9-51c2-a67c-c8b8542f034e', '497c4a54-cc8c-5a6f-a6e8-5d5e92bd414f', '{"en": "Unit review", "bn": "ইউনিট রিভিউ"}', 'checkpoint', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('b70f9fbd-53ac-5444-a97f-ef87110b833d', '663b449e-80b9-51c2-a67c-c8b8542f034e', 'choice', '{"en": "Which ayah lists who may receive zakat?", "bn": "কোন আয়াতে যাকাতের হকদারদের তালিকা আছে?"}', '{"options": [{"en": "9:60", "bn": "৯:৬০"}, {"en": "2:255", "bn": "২:২৫৫"}, {"en": "1:5", "bn": "১:৫"}, {"en": "112:1", "bn": "১১২:১"}], "correct": 0}', '{"en": "At-Tawbah 9:60.", "bn": "আত-তাওবা ৯:৬০।"}', 'Quran 9:60', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('237459e0-4596-5e6c-8658-f5150cdecd79', '663b449e-80b9-51c2-a67c-c8b8542f034e', 'choice', '{"en": "Voluntary charity is called…?", "bn": "নফল দানকে কী বলে?"}', '{"options": [{"en": "Sadaqah", "bn": "সদকা"}, {"en": "Jizyah", "bn": "জিজিয়া"}, {"en": "Kharaj", "bn": "খারাজ"}, {"en": "Diyah", "bn": "দিয়াত"}], "correct": 0}', '{"en": "Sadaqah: any charity given for Allah’s sake.", "bn": "সদকা: আল্লাহর সন্তুষ্টির জন্য যেকোনো দান।"}', NULL, 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('50537498-cdcd-515b-b899-b0d961b5e7b4', '663b449e-80b9-51c2-a67c-c8b8542f034e', 'choice', '{"en": "Zakat on savings is due after they stay above the nisab for…?", "bn": "সঞ্চয় কতদিন নিসাবের ওপরে থাকলে যাকাত ফরজ হয়?"}', '{"options": [{"en": "One week", "bn": "এক সপ্তাহ"}, {"en": "One month", "bn": "এক মাস"}, {"en": "One lunar year", "bn": "এক চান্দ্র বছর"}, {"en": "Ten years", "bn": "দশ বছর"}], "correct": 2}', '{"en": "A full lunar year (hawl).", "bn": "পূর্ণ এক চান্দ্র বছর (হাওল)।"}', 'Sunan Abi Dawud 1573', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('c797bda6-bb17-5426-8ddb-4839ee06e9ed', '663b449e-80b9-51c2-a67c-c8b8542f034e', 'choice', '{"en": "According to the hadith, what does charity do to wealth?", "bn": "হাদিস অনুযায়ী দান সম্পদের কী করে?"}', '{"options": [{"en": "It does not decrease it", "bn": "তা কমায় না"}, {"en": "It halves it", "bn": "অর্ধেক করে"}, {"en": "It ends it", "bn": "শেষ করে দেয়"}, {"en": "Nothing is said", "bn": "কিছু বলা হয়নি"}], "correct": 0}', '{"en": "\"Charity does not decrease wealth.\"", "bn": "\"দান সম্পদ কমায় না।\""}', 'Sahih Muslim 2588', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('0a755f9d-8e06-57ca-8dc1-7556cc181f3e', '663b449e-80b9-51c2-a67c-c8b8542f034e', 'choice', '{"en": "Which charity is best, according to the hadith?", "bn": "হাদিস অনুযায়ী কোন দান সর্বোত্তম?"}', '{"options": [{"en": "Given while healthy and hoping to be rich", "bn": "সুস্থ অবস্থায়, ধনী হওয়ার আশা থাকতে দেওয়া দান"}, {"en": "Given only at death", "bn": "শুধু মৃত্যুর সময় দেওয়া"}, {"en": "Given for praise", "bn": "প্রশংসার জন্য দেওয়া"}, {"en": "Given rarely", "bn": "কদাচিৎ দেওয়া"}], "correct": 0}', '{"en": "\"…that you give while healthy, fearing poverty and hoping for wealth.\"", "bn": "\"…যা তুমি সুস্থ অবস্থায়, দারিদ্র্যের ভয় ও ধনী হওয়ার আশা নিয়ে দাও।\""}', 'Sahih al-Bukhari 1419', 5) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('8cf89297-3385-5851-a0b1-efe116c6d3c0', '663b449e-80b9-51c2-a67c-c8b8542f034e', 'choice', '{"en": "For whom is Zakat al-Fitr given?", "bn": "সদকাতুল ফিতর কার পক্ষ থেকে দিতে হয়?"}', '{"options": [{"en": "Only rich men", "bn": "শুধু ধনী পুরুষ"}, {"en": "Every Muslim, young and old", "bn": "ছোট-বড় প্রত্যেক মুসলমান"}, {"en": "Only fasting adults", "bn": "শুধু রোজাদার প্রাপ্তবয়স্ক"}, {"en": "Only scholars", "bn": "শুধু আলেম"}], "correct": 1}', '{"en": "\"…on the slave and the free, male and female, young and old of the Muslims.\"", "bn": "\"…মুসলমানদের দাস-স্বাধীন, নারী-পুরুষ, ছোট-বড় সবার ওপর।\""}', 'Sahih al-Bukhari 1503', 6) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_units (id, title, description, color, icon, review_status, sort_order, section_id) VALUES ('26a77735-7f05-5002-8be5-d7afa80569a9', '{"en": "Hajj & Umrah", "bn": "হজ ও উমরা"}', '{}', '#c23616', 'moon', 'in_review', 2, 'a948793e-9cde-541f-9f21-59fc2ad50acb') ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_lessons (id, unit_id, title, kind, sort_order) VALUES ('d7a87548-7ab6-587d-9530-2392ff7b24e2', '26a77735-7f05-5002-8be5-d7afa80569a9', '{"en": "Part 1", "bn": "পর্ব ১"}', 'lesson', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('76eaddba-ac2f-5f12-8ac0-e83e92bb57a9', 'd7a87548-7ab6-587d-9530-2392ff7b24e2', 'choice', '{"en": "Walking around the Ka‘bah is called…?", "bn": "কাবা প্রদক্ষিণকে কী বলে?"}', '{"options": [{"en": "Sa‘i", "bn": "সাঈ"}, {"en": "Tawaf", "bn": "তাওয়াফ"}, {"en": "Wuquf", "bn": "উকুফ"}, {"en": "Ramy", "bn": "রামি"}], "correct": 1}', '{"en": "Tawaf: going around the Ka‘bah.", "bn": "তাওয়াফ: কাবার চারপাশে প্রদক্ষিণ।"}', 'Quran 22:29', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('3e204af0-2c41-54fd-a1aa-4b4111116ccd', 'd7a87548-7ab6-587d-9530-2392ff7b24e2', 'choice', '{"en": "How many circuits make one tawaf?", "bn": "এক তাওয়াফে কয়টি চক্কর?"}', '{"options": [{"en": "3", "bn": "৩"}, {"en": "5", "bn": "৫"}, {"en": "7", "bn": "৭"}, {"en": "10", "bn": "১০"}], "correct": 2}', '{"en": "Seven circuits, starting at the Black Stone.", "bn": "হাজরে আসওয়াদ থেকে শুরু করে সাতটি চক্কর।"}', 'Sahih Muslim 1218', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('03fd1aa5-c83f-526f-9cf2-d3b1528276e8', 'd7a87548-7ab6-587d-9530-2392ff7b24e2', 'choice', '{"en": "Walking between Safa and Marwah is called…?", "bn": "সাফা ও মারওয়ার মাঝে চলাকে কী বলে?"}', '{"options": [{"en": "Sa‘i", "bn": "সাঈ"}, {"en": "Tawaf", "bn": "তাওয়াফ"}, {"en": "Ihram", "bn": "ইহরাম"}, {"en": "Nafr", "bn": "নাফর"}], "correct": 0}', '{"en": "\"Indeed, Safa and Marwah are among the symbols of Allah.\"", "bn": "\"নিশ্চয়ই সাফা ও মারওয়া আল্লাহর নিদর্শনসমূহের অন্তর্ভুক্ত।\""}', 'Quran 2:158', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('8e2e6008-624b-55fe-bae4-b9b533c69305', 'd7a87548-7ab6-587d-9530-2392ff7b24e2', 'choice', '{"en": "Which day is the heart of Hajj, as the Prophet ﷺ said \"Hajj is…\"?", "bn": "নবী ﷺ বলেছেন \"হজ হলো…\", কোন দিন হজের মূল?"}', '{"options": [{"en": "Arafah", "bn": "আরাফা"}, {"en": "Eid", "bn": "ঈদ"}, {"en": "Tarwiyah", "bn": "তারবিয়া"}, {"en": "Tashriq", "bn": "তাশরিক"}], "correct": 0}', '{"en": "\"Hajj is Arafah.\"", "bn": "\"হজ হলো আরাফা।\""}', 'Jami‘ at-Tirmidhi 889', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('a8ecb800-68ed-51c6-ada0-d4fa179db859', 'd7a87548-7ab6-587d-9530-2392ff7b24e2', 'choice', '{"en": "Where do pilgrims spend the night after Arafah?", "bn": "আরাফার পর হাজিরা রাত কাটান কোথায়?"}', '{"options": [{"en": "Mina", "bn": "মিনা"}, {"en": "Muzdalifah", "bn": "মুজদালিফা"}, {"en": "Madinah", "bn": "মদিনা"}, {"en": "Ta’if", "bn": "তায়েফ"}], "correct": 1}', '{"en": "\"…then when you depart from Arafat, remember Allah at al-Mash‘ar al-Haram (Muzdalifah).\"", "bn": "\"…যখন আরাফাত থেকে ফিরবে, মাশআরুল হারামে (মুজদালিফা) আল্লাহকে স্মরণ করো।\""}', 'Quran 2:198', 5) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_lessons (id, unit_id, title, kind, sort_order) VALUES ('632d71c0-3c51-5cf5-bf01-6cb62e4158cb', '26a77735-7f05-5002-8be5-d7afa80569a9', '{"en": "Part 2", "bn": "পর্ব ২"}', 'lesson', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('d30f5ac0-b44c-5848-a955-db03f4ffab0a', '632d71c0-3c51-5cf5-bf01-6cb62e4158cb', 'choice', '{"en": "Where are the stone pillars (jamarat) stoned?", "bn": "জামারাতে পাথর নিক্ষেপ কোথায় হয়?"}', '{"options": [{"en": "Mina", "bn": "মিনা"}, {"en": "Arafat", "bn": "আরাফাত"}, {"en": "Quba", "bn": "কুবা"}, {"en": "Uhud", "bn": "উহুদ"}], "correct": 0}', '{"en": "The jamarat are in Mina.", "bn": "জামারাত মিনায় অবস্থিত।"}', NULL, 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('8f3c1923-6abc-57fe-8f94-8540246449c0', '632d71c0-3c51-5cf5-bf01-6cb62e4158cb', 'choice', '{"en": "What is the black stone in the Ka‘bah’s corner called?", "bn": "কাবার কোণের কালো পাথরকে কী বলে?"}', '{"options": [{"en": "Al-Hajar al-Aswad", "bn": "হাজরে আসওয়াদ"}, {"en": "Maqam Ibrahim", "bn": "মাকামে ইবরাহিম"}, {"en": "Hijr Isma‘il", "bn": "হিজরে ইসমাইল"}, {"en": "Al-Multazam", "bn": "মুলতাযাম"}], "correct": 0}', '{"en": "Tawaf begins at al-Hajar al-Aswad.", "bn": "হাজরে আসওয়াদ থেকে তাওয়াফ শুরু হয়।"}', NULL, 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('dd61a7a5-99b0-5287-aeb6-c47f833ec9d4', '632d71c0-3c51-5cf5-bf01-6cb62e4158cb', 'choice', '{"en": "When can Umrah be performed?", "bn": "উমরা কখন করা যায়?"}', '{"options": [{"en": "Only in Ramadan", "bn": "শুধু রমজানে"}, {"en": "Only in Dhul Hijjah", "bn": "শুধু জিলহজে"}, {"en": "Any time of the year", "bn": "বছরের যেকোনো সময়"}, {"en": "Only on Fridays", "bn": "শুধু শুক্রবার"}], "correct": 2}', '{"en": "Umrah has no fixed season; Umrah in Ramadan has a special reward.", "bn": "উমরার নির্দিষ্ট সময় নেই; রমজানের উমরার বিশেষ সওয়াব আছে।"}', 'Sahih al-Bukhari 1782', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('7cdac3a0-3b63-594f-9da1-42894468fc68', '632d71c0-3c51-5cf5-bf01-6cb62e4158cb', 'choice', '{"en": "The Eid al-Adha sacrifice recalls the story of…?", "bn": "ঈদুল আযহার কোরবানি কার ঘটনা স্মরণ করায়?"}', '{"options": [{"en": "Nuh and the Ark", "bn": "নুহ ও কিশতি"}, {"en": "Ibrahim and his son", "bn": "ইবরাহিম ও তাঁর পুত্র"}, {"en": "Musa and Pharaoh", "bn": "মুসা ও ফেরাউন"}, {"en": "Yunus and the fish", "bn": "ইউনুস ও মাছ"}], "correct": 1}', '{"en": "Ibrahim’s readiness to sacrifice his son, ransomed with a great sacrifice.", "bn": "ইবরাহিম (আ.)-এর পুত্রকে কোরবানির প্রস্তুতি, যার বিনিময়ে মহান কোরবানি দেওয়া হয়।"}', 'Quran 37:102–107', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('057db2d4-8955-5b84-ba22-8c2e918d089b', '632d71c0-3c51-5cf5-bf01-6cb62e4158cb', 'choice', '{"en": "The sacred state entered for Hajj or Umrah is…?", "bn": "হজ বা উমরার জন্য যে পবিত্র অবস্থায় প্রবেশ করা হয় তা হলো…?"}', '{"options": [{"en": "Ihram", "bn": "ইহরাম"}, {"en": "I‘tikaf", "bn": "ইতিকাফ"}, {"en": "Wudu", "bn": "অজু"}, {"en": "Tayammum", "bn": "তায়াম্মুম"}], "correct": 0}', '{"en": "Ihram begins at the miqat with the intention and talbiyah.", "bn": "মিকাতে নিয়ত ও তালবিয়ার মাধ্যমে ইহরাম শুরু হয়।"}', NULL, 5) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_lessons (id, unit_id, title, kind, sort_order) VALUES ('a5872854-3ead-5885-a0c4-75a78e4739be', '26a77735-7f05-5002-8be5-d7afa80569a9', '{"en": "Unit review", "bn": "ইউনিট রিভিউ"}', 'checkpoint', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('2008b2ec-31c2-54ce-81bf-0839a4374866', 'a5872854-3ead-5885-a0c4-75a78e4739be', 'choice', '{"en": "How many circuits make one tawaf?", "bn": "এক তাওয়াফে কয়টি চক্কর?"}', '{"options": [{"en": "3", "bn": "৩"}, {"en": "5", "bn": "৫"}, {"en": "7", "bn": "৭"}, {"en": "10", "bn": "১০"}], "correct": 2}', '{"en": "Seven circuits, starting at the Black Stone.", "bn": "হাজরে আসওয়াদ থেকে শুরু করে সাতটি চক্কর।"}', 'Sahih Muslim 1218', 1) ON CONFLICT (id) DO NOTHING;
