INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('99ca0d19-ebe8-5cde-9696-0b63f75a5e4b', 'a5872854-3ead-5885-a0c4-75a78e4739be', 'choice', '{"en": "Walking around the Ka‘bah is called…?", "bn": "কাবা প্রদক্ষিণকে কী বলে?"}', '{"options": [{"en": "Sa‘i", "bn": "সাঈ"}, {"en": "Tawaf", "bn": "তাওয়াফ"}, {"en": "Wuquf", "bn": "উকুফ"}, {"en": "Ramy", "bn": "রামি"}], "correct": 1}', '{"en": "Tawaf: going around the Ka‘bah.", "bn": "তাওয়াফ: কাবার চারপাশে প্রদক্ষিণ।"}', 'Quran 22:29', 6) ON CONFLICT (id) DO NOTHING;
